insert into public.glossary_terms (term, definition, category, categories, related_terms, slug, source_url)
values
  ($glossary$AA Coffee Grading$glossary$, $glossary$AA Coffee Grading refers to a size-based classification system for green coffee beans, primarily used in Kenya and other East African countries. The “AA” designation means beans of the largest size category, typically 7.2mm or larger in diameter . This grading method sorts beans through screens with specific-sized holes, with larger beans generally associated with higher quality. In Kenya’s grading hierarchy, AA represents the premium classification, followed by grades like AB, PB ( peaberry ), and others .$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$aa-coffee-grading$glossary$, $glossary$https://coffee-dictionary.com/aa-coffee-grading/$glossary$),
  ($glossary$Acrid Coffee Taste$glossary$, $glossary$Acrid Coffee Taste refers to a specific and undesirable flavor defect in coffee. It has a harsh, sharp, and irritating quality, which is characteristic of a burning or pungent bitterness. This flaw is distinct from desirable acidity and indicates problems that can range from production and roasting to the brewing process itself.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$acrid-coffee-taste$glossary$, $glossary$https://coffee-dictionary.com/acrid-coffee-taste/$glossary$),
  ($glossary$AeroPress$glossary$, $glossary$The AeroPress is a portable, versatile coffee brewer that uses air pressure to push hot water through coffee grounds, producing a concentrated, smooth cup in under two minutes.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$aeropress$glossary$, $glossary$https://coffee-dictionary.com/aeropress/$glossary$),
  ($glossary$Aerobie$glossary$, $glossary$The Aerobie coffee maker is a manual brewing device that uses air pressure to extract coffee. It involves steeping ground coffee in hot water before using a plunger to force the liquid through a filter. The device consists of a cylindrical chamber, a plunger, and paper filters that remove sediment while allowing oils to pass through.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$aerobie$glossary$, $glossary$https://coffee-dictionary.com/aerobie/$glossary$),
  ($glossary$Affogato$glossary$, $glossary$Affogato, from the Italian word meaning “drowned,” is a classic Italian dessert-beverage hybrid that consists of a scoop of vanilla gelato or ice cream over which a shot of hot espresso is poured . This elegant creation occupies a unique position in coffee culture , straddling the line between dessert and coffee drink .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$affogato$glossary$, $glossary$https://coffee-dictionary.com/affogato/$glossary$),
  ($glossary$After Dinner Roast$glossary$, $glossary$Definition and Common Usage After Dinner Roast refers to a dark roast coffee made for consumption after meals. This roast style undergoes extended heating at temperatures between 370°F–540°F during the Maillard reaction, resulting in beans with a bold, rich flavor profile . The intense roasting process reduces caffeine content somewhat compared to lighter roasts—a typical dark roast contains approximately 51 mg of caffeine per serving versus 60 mg in light roasts .$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[$rel$coffee roasting$rel$]::text[], $glossary$after-dinner-roast$glossary$, $glossary$https://coffee-dictionary.com/after-dinner-roast/$glossary$),
  ($glossary$Aftertaste in Coffee$glossary$, $glossary$Aftertaste in Coffee (also known as the finish ) refers to the lingering sensory impression of flavor , aroma, and mouthfeel that remains after swallowing. It has a role in indicating coffee quality and brewing precision. This final impression can evolve, revealing deeper notes that are characteristic of the bean’s origin, processing method, and roast level.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$aftertaste-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/aftertaste-in-coffee/$glossary$),
  ($glossary$Aftertastes$glossary$, $glossary$Aftertastes—the lingering flavors and mouthfeel sensations post-sip—form coffee’s final impression, bridging initial taste to lasting memory. These residual notes, spanning sweet to ashy, emerge from bean origin, roast, and extraction. Crucially, they expose what first sips may conceal: roast flaws, fading freshness, or brewing missteps.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$aftertastes$glossary$, $glossary$https://coffee-dictionary.com/aftertastes/$glossary$),
  ($glossary$Aged Coffee$glossary$, $glossary$Aged Coffee refers to coffee produced by storing green, unroasted beans for an extended period, which can range from two to three years to much longer. This process requires controlled conditions and is distinct from coffee that is stale or poorly stored. The managed storage helps develop a specific flavor profile. The resulting brew has earthy and pungent flavors, lower acidity , and increased body .$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$aged-coffee$glossary$, $glossary$https://coffee-dictionary.com/aged-coffee/$glossary$),
  ($glossary$Ageing$glossary$, $glossary$Ageing, spelled as “aging” in American English, is the gradual accumulation of changes in an individual over the course of their life. In humans, this is a complex, multidimensional journey involving physical, psychological, and social transformation.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$ageing$glossary$, $glossary$https://coffee-dictionary.com/ageing/$glossary$),
  ($glossary$Air Roaster$glossary$, $glossary$An air roaster, also known as a fluid bed roaster, is a coffee roasting machine that uses hot air as the primary heat transfer medium to roast coffee beans. The core principle involves suspending green coffee beans in a stream of heated air, creating a “fluid bed” where beans float and tumble continuously during the roasting process .$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$air-roaster$glossary$, $glossary$https://coffee-dictionary.com/air-roaster/$glossary$),
  ($glossary$Alan Adler$glossary$, $glossary$Alan Adler is an American inventor. His inventions include aerodynamic toys, such as footballs with fins and flying rings and discs. His Aerobie Pro flying ring set several world records for the farthest thrown object. In 2005 he invented a coffee brewing device and method called the AeroPress . He has approximately 40 patents in electronics, optics, and aerodynamics.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$alan-adler$glossary$, $glossary$https://coffee-dictionary.com/alan-adler/$glossary$),
  ($glossary$Alkaline Taste in Coffee$glossary$, $glossary$Alkaline Taste in Coffee is a sensory term in coffee tasting describing a dry, chalky, or soapy sensation, distinct from true acidity or bitterness, primarily perceived at the back of the tongue. It is a key characteristic of many dark-roasted coffees and beans from specific regions like Indonesia. Despite the name, coffee is chemically acidic, with this taste arising from minerals and roasting byproducts.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$alkaline-taste-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/alkaline-taste-in-coffee/$glossary$),
  ($glossary$Altura Coffee$glossary$, $glossary$Altura Coffee (from the Spanish word for ‘height’) refers to a designation for coffee beans cultivated at high altitudes, typically above 1,200 meters (4,000 feet). This term is a quality marker for high-grown, often mountain-grown, coffee. It means beans that have matured slowly in cooler temperatures, a process that produces greater density and a more complex flavor profile.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$altura-coffee$glossary$, $glossary$https://coffee-dictionary.com/altura-coffee/$glossary$),
  ($glossary$Alzheimer’s disease$glossary$, $glossary$Alzheimer’s disease is a progressive neurodegenerative disorder characterized by memory loss, cognitive decline, and behavioral changes, primarily associated with the accumulation of amyloid-beta plaques and tau protein tangles in the brain. In some cases, early signs can appear as early as the mid-40s.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$alzheimers-disease$glossary$, $glossary$https://coffee-dictionary.com/alzheimers-disease/$glossary$),
  ($glossary$American Roast$glossary$, $glossary$American Roast refers to a medium-level roast on the coffee spectrum, between lighter roasts (such as Cinnamon or Light) and darker varieties (like French or Italian) . This roast level has beans with a rich brown color and lacks the oily surface seen in darker roasts . American Roast strikes a balance in flavor, preserving some of the bean’s original characteristics while developing deeper caramelized notes.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[$rel$coffee roasting$rel$]::text[], $glossary$american-roast$glossary$, $glossary$https://coffee-dictionary.com/american-roast/$glossary$),
  ($glossary$Antestia Bug Damage$glossary$, $glossary$Antestia bugs (Antestiopsis spp.), also known as variegated coffee bugs or shield bugs, are small insects belonging to the Pentatomidae family that feed on coffee plants. These pests pierce coffee cherries and beans with their mouthparts, causing physical damage and introducing harmful bacteria into the fruit . The bacteria produce 2-isopropyl-3-methoxypyrazine (IMP) when beans are heated at high temperature , resulting in the distinctive potato taste defect (PTD) .$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$antestia-bug-damage-on-coffee-beans$glossary$, $glossary$https://coffee-dictionary.com/antestia-bug-damage-on-coffee-beans/$glossary$),
  ($glossary$Arabian Mocha Coffee$glossary$, $glossary$Arabian Mocha Coffee refers to a premium single-origin coffee variety cultivated in Yemen’s mountainous regions across the Arabian Peninsula . This coffee has a medium to full body with bright acidity and a complex sensory profile . The beans undergo dry processing, where they ferment inside the fruit, developing their signature taste characteristics . The resulting cup has a rich, wine-like flavor with distinctive chocolatey undertones .$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$arabian-mocha-coffee$glossary$, $glossary$https://coffee-dictionary.com/arabian-mocha-coffee/$glossary$),
  ($glossary$Arabic coffee$glossary$, $glossary$Arabic coffee is a general name that refers to the two main ways coffee is prepared in many Arab countries: Turkish-style, and Saudi Coffee. The Turkish coffee brewing method is common in the Levant, but brewed without the addition of sugar. Cardamom is often added, or it is served plain قهوة سادة qahwah sādah (lit. “plain coffee”).$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Dallah (coffee pot)$rel$]::text[], $glossary$arabic-coffee$glossary$, $glossary$https://coffee-dictionary.com/arabic-coffee/$glossary$),
  ($glossary$Artisan Coffee$glossary$, $glossary$Artisan Coffee refers to coffee produced through a hands-on, craftsmanship-focused process. This approach is known for small-batch roasting , direct relationships with farmers, and meticulous attention to quality from cultivation to brewing . It is a type of production within the specialty coffee movement, distinguished by its philosophy and production scale.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$artisan-coffee$glossary$, $glossary$https://coffee-dictionary.com/artisan-coffee/$glossary$),
  ($glossary$Arusha Coffee$glossary$, $glossary$Arusha coffee takes its name from the Arusha region in northern Tanzania, where this Arabica variety has been cultivated since the colonial period. The variety emerged from French Mission Bourbon stock introduced to the area in the early 20th century, adapting to the volcanic soils and high-altitude conditions surrounding Mount Meru and Mount Kilimanjaro.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$arusha-coffee$glossary$, $glossary$https://coffee-dictionary.com/arusha-coffee/$glossary$),
  ($glossary$Ashy Coffee$glossary$, $glossary$Ashy Coffee Definition and Sensory Profile Ashy coffee refers to beans with a burnt character reminiscent of cigarette ash or fireplace remnants. This negative flavor attribute results from excessive roasting , particularly when beans remain in a drum roaster beyond approximately 17 minutes, leading to burnt or baked flavors . The ashy profile has a dry, powdery sensation on the palate, often accompanied by bitter , charcoal-like notes that overwhelm the coffee’s inherent qualities.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$ashy-coffee$glossary$, $glossary$https://coffee-dictionary.com/ashy-coffee/$glossary$),
  ($glossary$Asian palm civet$glossary$, $glossary$A civet is a small, slender mammal, most active at night, that inhabits the tropical forests of Asia and Africa. The term refers to over a dozen distinct species, with the greatest variety found in Southeast Asia. The most well-known of these is the African Civet, or *Civettictis civetta*. Historically, this animal was the main source of a powerful musky substance used in the creation of fine perfumes, giving it significant economic importance for centuries.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$asian-palm-civet$glossary$, $glossary$https://coffee-dictionary.com/asian-palm-civet/$glossary$),
  ($glossary$Aspiration in Coffee Tasting$glossary$, $glossary$Aspiration in Coffee Tasting refers to a standardized sensory evaluation technique. It involves a taster drawing brewed coffee into the mouth through vigorous, audible suction. The technique is a core component of professional coffee cupping protocols. This method atomizes the liquid to coat the tongue evenly and releases aromatic vapors for retronasal olfaction.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$aspiration-in-coffee-tasting$glossary$, $glossary$https://coffee-dictionary.com/aspiration-in-coffee-tasting/$glossary$),
  ($glossary$Astringency in Coffee$glossary$, $glossary$Astringency in coffee describes a tactile sensation rather than a taste, characterized by a dry, puckering feeling in the mouth similar to the experience of over-extracted espresso or strong black tea . This sensation occurs when compounds in the brew bind with proteins in saliva, reducing lubrication and creating a rough, sometimes chalky mouthfeel . While mild astringency can add complexity to a coffee’s sensory profile, excessive astringency is generally considered a defect in the cup.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$astringency-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/astringency-in-coffee/$glossary$),
  ($glossary$Australia$glossary$, $glossary$Australia , officially the Commonwealth of Australia, is a country comprising the mainland of the Australian continent, the island of Tasmania and numerous smaller islands. It is the world’s sixth-largest country by total area. Neighbouring countries include Indonesia , East Timor and Papua New Guinea to the north; the Solomon Islands, Vanuatu and New Caledonia to the north-east; and New Zealand to the south-east.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$australia$glossary$, $glossary$https://coffee-dictionary.com/australia/$glossary$),
  ($glossary$Baggy Coffee$glossary$, $glossary$Baggy Coffee refers to a traditional brewing method where coffee grounds are placed in a cup, then saturated with hot water and left to steep. After approximately 4 minutes, the grounds sink to the bottom . The coffee becomes drinkable between 5-15 minutes after the initial break, allowing time for flavors to develop while the temperature drops to a comfortable drinking range .$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[]::text[], $glossary$baggy-coffee$glossary$, $glossary$https://coffee-dictionary.com/baggy-coffee/$glossary$),
  ($glossary$Baked Coffee$glossary$, $glossary$Baked Coffee A roasting defect characterized by flat, dull flavor profiles lacking complexity and vibrancy. Baked coffee results from insufficient heat application during the development phase after first crack . The sensory profile has distinctly underwhelming characteristics: muted acidity , diminished sweetness, and a generic caramelized taste that lacks distinction . When cupped, baked coffees often show a papery mouthfeel with minimal aromatic qualities.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$baked-coffee$glossary$, $glossary$https://coffee-dictionary.com/baked-coffee/$glossary$),
  ($glossary$Balance in Coffee$glossary$, $glossary$Balance in coffee refers to a harmonious and pleasing equilibrium where no single attribute—acidity, sweetness, bitterness , body, or flavor—dominates over the others. This concept is one of the sought-after qualities in specialty coffee , distinguishing exceptional cups from good ones. A balanced coffee is not neutral; it can be complex and vibrant, but its elements are integrated and none are jarring or out of place.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$balance-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/balance-in-coffee/$glossary$),
  ($glossary$Bar (unit)$glossary$, $glossary$Many coffee machines use pressure to enhance brewing parameters. Some of the devices that use pressure are single serve coffee machines , such as Keurig, or Tassimo, and espresso machines . Other devices are the Moka pot , or steam espresso makers. Pressure is measured in bar.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[$rel$Pressure$rel$, $rel$Pressure gauge$rel$]::text[], $glossary$bar-unit$glossary$, $glossary$https://coffee-dictionary.com/bar-unit/$glossary$),
  ($glossary$Barista$glossary$, $glossary$A barista is a trained coffee professional who specializes in preparing and serving espresso-based drinks, with expertise in extraction, milk texturing, and latte art.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$barista$glossary$, $glossary$https://coffee-dictionary.com/barista/$glossary$),
  ($glossary$Beaker (glassware)$glossary$, $glossary$The main piece of a French press is a glass beaker. Because the beaker is exposed to high temperatures in a short time, they are subject to thermal shock , This is why beakers for French press coffee makers are made of borosilicate glass , or more recently, of stainless steel .$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$beaker-glassware$glossary$, $glossary$https://coffee-dictionary.com/beaker-glassware/$glossary$),
  ($glossary$Bean Hopper$glossary$, $glossary$A bean hopper is the compartment atop a coffee grinder that stores whole coffee beans before grinding. Made from plastic, metal, or glass, it protects beans from light, air, and moisture—factors that harm freshness and flavor. Its design controls bean flow into the grinder’s burrs, ensuring even grind size for consistent extraction .$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$bean-hopper$glossary$, $glossary$https://coffee-dictionary.com/bean-hopper/$glossary$),
  ($glossary$Beko$glossary$, $glossary$Beko is a domestic appliance and consumer electronics brand of Arçelik A. Ş.. Beko Elektronik A. Ş. (later Grundig Elektronik A. Ş. ) was a Turkish consumer electronics manufacturer, owned by Arçelik. In 2004 Beko Elektronik purchased Grundig and by January 2005, Beko and its rival Turkish electronics and white goods brand Vestel accounted for more than half of all TV sets manufactured in Europe. In April 2008 Beko renamed itself Grundig Elektronik A. Ş.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$beko$glossary$, $glossary$https://coffee-dictionary.com/beko/$glossary$),
  ($glossary$Bialetti$glossary$, $glossary$A Bialetti is an Italian brand synonymous with the Moka Express, a stovetop coffee maker invented by Alfonso Bialetti in 1933. It has a distinctive octagonal aluminum body and brews espresso-like coffee by forcing steam-pressurized water through ground coffee. Its affordability and simplicity democratized café-style brewing, establishing it as a global household staple.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$bialetti$glossary$, $glossary$https://coffee-dictionary.com/bialetti/$glossary$),
  ($glossary$Bialetti Moka Express$glossary$, $glossary$Invented in 1933 by Alfonso Bialetti, the Bialetti Moka Express is a stovetop coffee maker that uses steam pressure to make espresso-like coffee. Its three-chamber design—a water-filled base, a middle funnel for ground coffee, and a top collector for the brew—relies on a pressure-driven mechanism. When heated, steam pushes water through the grounds, creating a rich, concentrated coffee.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Moka pot$rel$]::text[], $glossary$bialetti-moka-express$glossary$, $glossary$https://coffee-dictionary.com/bialetti-moka-express/$glossary$),
  ($glossary$Bica$glossary$, $glossary$Bica (pronounced BEE-kah) refers to Portugal ’s standard espresso -style coffee. It is a small, strong shot served in a demitasse cup and is known for being the default coffee ordered nationwide. The term is often used interchangeably with um café (a coffee). As a type of espresso variation, it involves extracting a larger volume of water, which produces a smoother taste . This characteristic flavor profile is linked to Portugal’s tradition of lighter coffee roasting .$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$bica$glossary$, $glossary$https://coffee-dictionary.com/bica/$glossary$),
  ($glossary$Bicerin$glossary$, $glossary$Bicerin (pronounced bee-cheh-REEN) is a traditional layered coffee beverage from Turin, Italy. Its name derives from the Piedmontese word for ‘small glass’. The drink is a specific type of coffee-chocolate preparation, celebrated for its three distinct, un-stirred layers.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$bicerin$glossary$, $glossary$https://coffee-dictionary.com/bicerin/$glossary$),
  ($glossary$Bisphenol A$glossary$, $glossary$Bisphenol A (BPA) is an organic compound with the chemical formula (CH3)2C(C6H4OH)2. It is a key building block for making clear, strong plastics and epoxy resins. First used commercially in 1957, its global production now reaches about 3.6 million tons every year. This BPA-based plastic is found in many everyday items, including water bottles, sports gear, and digital media like CDs. In industry, it has a crucial role in lining water pipes to prevent corrosion and coating the insides of many food and beverage cans, forming a protective barrier.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$bisphenol-a$glossary$, $glossary$https://coffee-dictionary.com/bisphenol-a/$glossary$),
  ($glossary$Bitterness in Coffee$glossary$, $glossary$Bitterness represents one of the five basic tastes that the human palate can detect, with receptors concentrated primarily at the back of the tongue. In coffee, this fundamental taste sensation results from the extraction of specific compounds, particularly caffeine and certain phenolic acids. The primary chemical contributors to coffee’s bitter profile are caffeine and chlorogenic acid lactones, which develop during the roasting process .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$bitterness-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/bitterness-in-coffee/$glossary$),
  ($glossary$Black & Decker$glossary$, $glossary$Black & Decker has a division of domestic coffee maker appliances. The division focuses on the auto drip coffee makers as the most popular coffee brewing method .$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$black-decker$glossary$, $glossary$https://coffee-dictionary.com/black-decker/$glossary$),
  ($glossary$Black eye$glossary$, $glossary$A Black Eye is a coffee drink composed of a standard drip coffee (typically 8-12 oz) with a double shot of espresso added to it . The double shot of espresso contributes approximately 60mL of concentrated coffee, enhancing both the caffeine content and flavor profile . While caffeine levels vary depending on factors such as bean type, roasting , and brewing methods , a Black Eye is likely to contain over 500 mg of caffeine per serving, significantly exceeding the daily recommended dose of 400 mg . Compared to a Red Eye or Depth Charge, which includes a single shot of espresso and ranges from 250-400 mg of caffeine, the Black Eye offers a more potent caffeine boost . Known for its robust and intense flavor, this drink strikes a balance between the strength of espresso and the milder taste of drip coffee .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$black-eye$glossary$, $glossary$https://coffee-dictionary.com/black-eye/$glossary$),
  ($glossary$Bodum$glossary$, $glossary$Bodum, Inc. , (also known as BODUM) is a tableware and kitchenware company founded in Copenhagen, Denmark, in 1944 by Peter Bodum. In 1978, the son of the founder and new chief executive officer, Jørgen Bodum, moved the company to Switzerland to relocate Bodum to central Europe. Among the products Bodum makes are the Bodum French press , vacuum coffee brewers (the “Santos”), and double-walled beverage glasses made of borosilicate glass .$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$bodum$glossary$, $glossary$https://coffee-dictionary.com/bodum/$glossary$),
  ($glossary$Boiler$glossary$, $glossary$A boiler is a closed vessel in which water or other fluid is heated. The heated or vaporized fluid exits the boiler for use in various processes or heating applications, including boiler-based power generation, cooking, and sanitation.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$boiler$glossary$, $glossary$https://coffee-dictionary.com/boiler/$glossary$),
  ($glossary$Bonavita$glossary$, $glossary$Bonavita is a coffee equipment brand established in 2009, known for affordable, precision-designed brewers and kettles catering to home and professional users. It gained prominence with SCA-certified automatic drip brewers, meeting strict specialty coffee standards for temperature and extraction . The brand’s gooseneck kettles and pour-over brewers balance functionality, durability, and value, democratizing specialty coffee.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$bonavita$glossary$, $glossary$https://coffee-dictionary.com/bonavita/$glossary$),
  ($glossary$Borosilicate glass$glossary$, $glossary$Borosilicate glass is a type of glass with the main glass-forming constituents silica and boron oxide. Borosilicate glasses are known for having very low coefficients of thermal expansion (~3 × 10 /°C at 20°C), making them resistant to thermal shock, more so than any other common glass. Such glass is less subject to thermal stress and is commonly used for the construction of reagent bottles. Borosilicate glass is sold under such trade names as Kimax, Pyrex, Endural, Schott, or Refmex.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$borosilicate-glass$glossary$, $glossary$https://coffee-dictionary.com/borosilicate-glass/$glossary$),
  ($glossary$Brain damage$glossary$, $glossary$“Brain damage” or “ Brain Injury ” (BI) refers to damage to or the loss of brain cells. These injuries can stem from a wide range of internal and external sources. In a coffee context, the term is used metaphorically to describe the catastrophic and irreversible overheating of coffee beans during roasting.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$brain-damage$glossary$, $glossary$https://coffee-dictionary.com/brain-damage/$glossary$),
  ($glossary$Bready Coffee$glossary$, $glossary$Bready coffee refers to under-roasted or underdeveloped coffee beans , characterized by flavors that suggest raw dough, bread, grains, or crackers. This descriptor means a roast defect rather than an origin-specific characteristic; any coffee bean type can develop these qualities when subjected to improper roasting techniques. The term emerged from modern specialty coffee roasting and quality control practices to diagnose and communicate roast profile flaws.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$bready-coffee-a-sign-of-underdevelopment$glossary$, $glossary$https://coffee-dictionary.com/bready-coffee-a-sign-of-underdevelopment/$glossary$),
  ($glossary$Breve$glossary$, $glossary$The breve is a type of espresso-based beverage comparable to a caffè latte . The term refers to an American version that uses half-and-half instead of milk. This method produces a coffee drink known for its richer, creamier character than a traditional latte.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$breve$glossary$, $glossary$https://coffee-dictionary.com/breve/$glossary$),
  ($glossary$Breville$glossary$, $glossary$Breville refers to an Australian appliance manufacturer founded in 1932 by Bill O’Brien and Harry Norville in Sydney. The company name combines the founders’ surnames – “Bill” and “Norville” creating “Breville” . Initially focused on radio components and mine detectors during World War II, Breville shifted to kitchen appliances in the post-war era. The brand gained prominence in the 1970s with the introduction of the sandwich toaster, which became synonymous with the Breville name in Australia and New Zealand.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$breville$glossary$, $glossary$https://coffee-dictionary.com/breville/$glossary$),
  ($glossary$Brightness in Coffee$glossary$, $glossary$Brightness in coffee refers to a pleasant, tangy acidity that creates a lively and vibrant flavor experience. This characteristic manifests as citrusy, fruity , or wine-like notes that add complexity and energy to each sip.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$brightness-in-coffee-a-tangy-flavor-profile$glossary$, $glossary$https://coffee-dictionary.com/brightness-in-coffee-a-tangy-flavor-profile/$glossary$),
  ($glossary$Brikka pot$glossary$, $glossary$The Brikka Pot, Bialetti’s stovetop espresso maker , distinguishes itself from traditional moka pots through its patented weighted valve, which produces a crema-like foam layer. By dynamically regulating pressure (explained in Mechanism and Weighted Valve), the valve helps a richer, espresso-like extraction, improving texture and aroma. This results in a velvety mouthfeel and intensified flavor, merging stovetop simplicity with espresso-machine quality.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Moka pot$rel$]::text[], $glossary$brikka-pot$glossary$, $glossary$https://coffee-dictionary.com/brikka-pot/$glossary$),
  ($glossary$Briny$glossary$, $glossary$Briny describes a coffee taste that evokes the salty, savory character of seawater or brine, creating a brackish sensation on the palate. This flavor descriptor is one of the most unwelcome characteristics a coffee can have, as it alters the expected taste profile in an unpleasant direction.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$briny-coffee-taste-and-flavor-descriptors$glossary$, $glossary$https://coffee-dictionary.com/briny-coffee-taste-and-flavor-descriptors/$glossary$),
  ($glossary$Bucharest$glossary$, $glossary$Bucharest is a major coffee center, with one specialty café per 52,000 inhabitants, more than Berlin , or Copenhagen . The last years, the specialty coffee scene has grown exponentially.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$bucharest$glossary$, $glossary$https://coffee-dictionary.com/bucharest/$glossary$),
  ($glossary$Bunn-o-Matic Corporation$glossary$, $glossary$Bunn-O-Matic Corporation is a manufacturer of coffee and tea-making equipment headquartered in Springfield, Illinois with a sister plant in Creston, Iowa. Founded by George Bunn, who invented the fluted coffee filter , its customers are primarily institutional foodservice providers. The company also offers a product line for home use and introduced the first commercial quality drip brewer for the home market in 1972. Its products are sold under the Bunn and Bunn-o-Matic brands.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$bunn-o-matic-corporation$glossary$, $glossary$https://coffee-dictionary.com/bunn-o-matic-corporation/$glossary$),
  ($glossary$Burr Grinder$glossary$, $glossary$A burr grinder uses two abrasive surfaces (burrs) to crush coffee beans to a consistent particle size, producing more uniform grounds than blade grinders for better extraction.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$coffee grinder$rel$]::text[], $glossary$burr-grinder$glossary$, $glossary$https://coffee-dictionary.com/burr-grinder/$glossary$),
  ($glossary$Cafestol$glossary$, $glossary$Cafestol is a diterpene molecule present in coffee. A typical bean of Coffea arabica contains about 0.6% cafestol by weight. Cafestol is present in its highest quantity in unfiltered coffee drinks such as French press coffee or Turkish coffee /Greek coffee. In filtered coffee drinks such as drip brewed coffee, it is present in only negligible amounts. Studies have shown that regular consumption of boiled coffee increases serum cholesterol by 8% in men and 10% in women. This increase in cholesterol, more specifically Low Density Lypoprotein (LDL) cholesterol has been linked to various cardiovascular diseases. Heavy consumption of cafestol is particularly a problem for those who have a genetic mutation that slows down metabolism of coffee in the body and is likely not an issue for the general population.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$cafestol$glossary$, $glossary$https://coffee-dictionary.com/cafestol/$glossary$),
  ($glossary$Caffe Americano$glossary$, $glossary$Caffè Americano, or Americano (English: American coffee) is a style of coffee prepared by adding hot water to espresso , giving it a similar strength to, but different flavor from regular drip coffee. The strength of an Americano varies with the number of shots of espresso and the amount of water added. The name is also spelled with varying capitalization and use of diacritics.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$caffe-americano$glossary$, $glossary$https://coffee-dictionary.com/caffe-americano/$glossary$),
  ($glossary$Caffeine$glossary$, $glossary$Caffeine is a bitter , white crystalline xanthine alkaloid that acts as a stimulant drug. Caffeine is found in varying quantities in the seeds, leaves, and fruit of some plants, where it acts as a natural pesticide that paralyzes and kills certain insects feeding on the plants, as well as enhancing the reward memory of pollinators.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$caffeine$glossary$, $glossary$https://coffee-dictionary.com/caffeine/$glossary$),
  ($glossary$Caffeine Extraction$glossary$, $glossary$Caffeine Extraction in Coffee Brewing Caffeine extraction occurs during the brewing process as water dissolves and pulls caffeine molecules from ground coffee. The extraction rate depends on several factors, including grind size , water temperature , and brewing time. Research shows that a standard brewing ratio of 15:1 (150g water to 10g coffee) provides optimal extraction conditions . Grind size significantly impacts extraction – finer grinds increase surface area and caffeine extraction rates.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$caffeine-extraction$glossary$, $glossary$https://coffee-dictionary.com/caffeine-extraction/$glossary$),
  ($glossary$Caffè Latte$glossary$, $glossary$Caffè Latte is a drink commonly prepared with one third espresso and two thirds steamed milk . The name is a portmanteau of the Italian words Caffè, which means coffee, and Latte, which means milk.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$caffe-latte$glossary$, $glossary$https://coffee-dictionary.com/caffe-latte/$glossary$),
  ($glossary$Caffè Mocha$glossary$, $glossary$Caffè Mocha is a popular coffee beverage blending espresso, steamed milk , and chocolate, often finished with whipped cream. Its name originates from Mocha, Yemen, a historic port city renowned for its coffee trade and beans with a naturally chocolatey profile, which directly influenced the drink’s flavor concept. It serves as a chocolate-infused version of a caffè latte or a hot chocolate enhanced with espresso.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$caffe-mocha$glossary$, $glossary$https://coffee-dictionary.com/caffe-mocha/$glossary$),
  ($glossary$Caffè crema$glossary$, $glossary$Caffè crema sometimes misspelled cafe crema, refers to two different espresso drinks. Caffè crema is an old name for espresso , and it was used in the 1940s and the 50s. The other drink named caffè crema is a long espresso drink originating in Europe. Caffè crema is primarily served in Switzerland, Austria and northern Italy, along the Italian/ Swiss and Italian/ Austrian border. Caffè crema generally means “espresso”. However, in technical discussions, referring to the long drink, it may be referred to as Swiss caffè crema.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$caffe-crema$glossary$, $glossary$https://coffee-dictionary.com/caffe-crema/$glossary$),
  ($glossary$Café Bombón$glossary$, $glossary$Café Bombón (pronounced kah-FEY bohm-BON) is a traditional Spanish coffee drink and a popular variation of espresso . The drink consists of equal parts freshly brewed espresso and sweetened condensed milk. It is known for its distinct two-layer appearance, which is presented in a small clear glass. Originating from Spain ’s Valencia region, Café Bombón features a simple, sweet, and robust flavor profile.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$cafe-bombon$glossary$, $glossary$https://coffee-dictionary.com/cafe-bombon/$glossary$),
  ($glossary$Café Romano$glossary$, $glossary$Café Romano is a traditional Italian coffee preparation that combines espresso with lemon. It consists of a single or double shot of espresso served with either a slice of fresh lemon or lemon zest on the side.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$cafe-romano$glossary$, $glossary$https://coffee-dictionary.com/cafe-romano/$glossary$),
  ($glossary$Café au lait$glossary$, $glossary$Café au lait (French for “coffee with milk”) is a traditional coffee beverage consisting of equal parts brewed coffee and steamed milk . Unlike a latte , which uses espresso and steamed milk with microfoam , café au lait typically has regular hot milk without the frothy texture. The drink is traditionally served in a wide-brimmed bowl or large cup, making it ideal for dipping pastries .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$cafe-au-lait$glossary$, $glossary$https://coffee-dictionary.com/cafe-au-lait/$glossary$),
  ($glossary$Café con Leche$glossary$, $glossary$Café con Leche ( Spanish for “coffee with milk”) is a classic beverage of equal parts strong coffee, typically espresso , and scalded or steamed milk . A staple in Spain and Latin America, it is traditionally served in a glass and is the regional equivalent of the French café au lait or Italian caffè latte .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$cafe-con-leche$glossary$, $glossary$https://coffee-dictionary.com/cafe-con-leche/$glossary$),
  ($glossary$Camp Coffee$glossary$, $glossary$Camp Coffee is a concentrated liquid coffee essence that was a household staple in British kitchens throughout much of the 20th century. This dark, syrupy product combines coffee extract with chicory and sugar, creating a ready-to-use concentrate that requires only the addition of hot water or milk to make an instant coffee drink. The distinctive bottle design, featuring a Scottish Highland regiment soldier being served coffee by a Sikh soldier, became an iconic image on British grocery shelves.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Culture$cat$]::text[], ARRAY[]::text[], $glossary$camp-coffee$glossary$, $glossary$https://coffee-dictionary.com/camp-coffee/$glossary$),
  ($glossary$Cancer$glossary$, $glossary$Cancer (medical): A broad group of diseases characterized by unregulated cell growth and the formation of malignant neoplasms (tumors) that can invade nearby tissues and spread (metastasize) through the lymphatic system and bloodstream.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$, $cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$cancer$glossary$, $glossary$https://coffee-dictionary.com/cancer/$glossary$),
  ($glossary$Cappuccino$glossary$, $glossary$A cappuccino, is an Italian coffee drink traditionally prepared with espresso, hot milk, and steamed-milk foam. Istituto Nazionale Espresso Italiano defines cappuccino as a beverage prepared with 25 ml espresso, and 100 ml steam-foamed milk. In coffee shops in North America, cappuccino is prepared with a doppio espresso and frothed milk up to 6 fl oz.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$cappuccino$glossary$, $glossary$https://coffee-dictionary.com/cappuccino/$glossary$),
  ($glossary$Cappuccino Machine$glossary$, $glossary$A cappuccino machine is an espresso machine equipped with a steam wand or built-in milk frother, designed to prepare espresso and steam milk for cappuccinos. These machines vary from manual models requiring skill to fully automatic ones that simplify milk frothing and espresso extraction . The steam wand, a critical component, uses pressurized steam to create microfoam, essential for the cappuccino’s creamy texture.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$cappuccino-machine$glossary$, $glossary$https://coffee-dictionary.com/cappuccino-machine/$glossary$),
  ($glossary$Capresso$glossary$, $glossary$Capresso markets high-end coffeemakers, espresso machines, grinders, electric water kettles and frothers. The company is owned by Jura AG of Switzerland and was founded in 1994.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$capresso$glossary$, $glossary$https://coffee-dictionary.com/capresso/$glossary$),
  ($glossary$Caramelization$glossary$, $glossary$Caramelization refers to a form of non-enzymatic browning and a type of pyrolysis involving the thermal degradation of sugars, distinct from the Maillard reaction which requires amino acids. In coffee roasting , sucrose—the primary sugar in green coffee—breaks down through pyrolysis into simpler sugars and compounds. This process is known for generating sweet, nutty, buttery, and toffee-like flavors, while visually progressing the bean’s color from yellow through deepening browns.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$caramelization$glossary$, $glossary$https://coffee-dictionary.com/caramelization/$glossary$),
  ($glossary$Caramelly$glossary$, $glossary$Caramelly notes occupy the sweet segment of the coffee flavor wheel, positioned between chocolatey and vanilla subcategories. This descriptor refers to flavors reminiscent of caramelized sugar, butterscotch, and brown sugar in coffee. The perception of caramel sweetness is somewhat paradoxical, as research shows that roasting degrades 99 percent of sugars present in green coffee . Despite this reduction, light-roasted coffees retain approximately 2.9 percent of the original sucrose content, while medium roasts preserve only 0.9 percent .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$caramelly-a-sweet-note-in-coffee-tasting$glossary$, $glossary$https://coffee-dictionary.com/caramelly-a-sweet-note-in-coffee-tasting/$glossary$),
  ($glossary$Carbony$glossary$, $glossary$Carbony is a flavor descriptor for coffee that evokes the aroma and taste of charcoal, burnt wood, or dark toast, typically associated with dark roasts . This profile emerges as a foundational, bitter base note that defines many traditional espresso blends, French roasts, and Italian roasts . The sensory experience centers on deep, smoky characteristics reminiscent of campfire embers or toasted bread crusts.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$carbony-coffee-flavor-profiles$glossary$, $glossary$https://coffee-dictionary.com/carbony-coffee-flavor-profiles/$glossary$),
  ($glossary$Caro Beverage$glossary$, $glossary$A Caro beverage is a caffeine-free coffee substitute made from roasted barley, malted barley, chicory, and rye, replicating coffee’s richness without the stimulant. Originating in Germany, it is commonly prepared as an instant granular drink, offering a malty , slightly bitter flavor akin to coffee. Ideal for those reducing caffeine , Caro preserves the ritual of a warm, robust beverage.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$caro$glossary$, $glossary$https://coffee-dictionary.com/caro/$glossary$),
  ($glossary$Ceramic$glossary$, $glossary$Ceramic is an excellent material for the coffee industry. Its ability to conduct heat, which can be low or high depending on its specific makeup, makes it fit for a wide array of uses. The most common applications are coffee cups and mugs, where the right thermal traits keep a drink hot without making the outside too warm to hold. Ceramic kettles and pots are also popular, prized both for holding heat well and for their visual charm. Another important use is the coffee dripper, where ceramic aids in keeping a stable brewing temperature . Furthermore, ceramic coffee grinders mark a newer development; they are highly valued because the ceramic grinding burrs do not heat the coffee beans during the process, which protects the beans’ delicate flavors and aromas. This adaptability, coming from adjustable material properties, lets ceramics meet various functional and design needs throughout the entire coffee preparation and serving journey.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$ceramic$glossary$, $glossary$https://coffee-dictionary.com/ceramic/$glossary$),
  ($glossary$Cezve$glossary$, $glossary$A cezve is a pot designed specifically to make Turkish coffee . The body and handle are traditionally made of brass or copper (occasionally silver or gold); though, recently, cezve are more commonly made from stainless steel , aluminium, or ceramics. The long handle is particularly useful to avoid burning one’s hands, and the brim is designed to serve the coffee. Other regional variations of the word cezve are jezve and čezve. In Ukrainian and Russian, the word is spelled джезва .$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Turkish coffee$rel$]::text[], $glossary$cezve$glossary$, $glossary$https://coffee-dictionary.com/cezve/$glossary$),
  ($glossary$Chameleon Cold-Brew$glossary$, $glossary$Chameleon Cold Brew is a brand of organic, ready-to-drink cold brew coffee concentrate known for its smooth, low-acid profile and versatility. Founded in Austin, Texas in 2010, it helped popularize high-quality cold brew by offering a convenient, shelf-stable concentrate that could be mixed with water or milk. The brand uses beans from organic, fair-trade farms, focusing on ethical production and sustainability. Its products include black coffee concentrate and flavored varieties, catering to different consumer tastes.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$chameleon-cold-brew$glossary$, $glossary$https://coffee-dictionary.com/chameleon-cold-brew/$glossary$),
  ($glossary$Channeling$glossary$, $glossary$Channeling (spelled Channelling in British English) refers to a critical defect in espresso brewing. This problem occurs when water under high pressure finds or creates uneven paths through the compressed coffee puck, bypassing much of the grounds.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$channeling$glossary$, $glossary$https://coffee-dictionary.com/channeling/$glossary$),
  ($glossary$Chemex Coffeemaker$glossary$, $glossary$The Chemex Coffeemaker is a manual coffeemaker. It was introduced, and continues to be manufactured, by the Chemex Corporation in Pittsfield, Massachusetts. Peter Schlumbohm invented it in 1941.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Pour over coffee$rel$]::text[], $glossary$chemex-coffeemaker$glossary$, $glossary$https://coffee-dictionary.com/chemex-coffeemaker/$glossary$),
  ($glossary$Chicory$glossary$, $glossary$Common chicory, Cichorium intybus, is a somewhat woody, perennial herbaceous plant usually with bright blue flowers, rarely white or pink. Various varieties are cultivated for salad leaves, chicons, or for roots (var. sativum), which are baked, ground, and used for preparing a beverage. It is also grown as a forage crop for livestock. It lives as a wild plant on roadsides in its native Europe, and in North America and Australia, where it has become naturalized.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$chicory$glossary$, $glossary$https://coffee-dictionary.com/chicory/$glossary$),
  ($glossary$Chocolate Coffee Notes$glossary$, $glossary$Chocolate Coffee Notes refers to a natural flavor and aroma profile in coffee that is characteristic of chocolate. This characteristic can range from sweet milk chocolate to dark chocolate or cocoa, and it develops through roasting chemistry without any added flavorings . The profile is known for adding a comforting and rich dimension to coffee, and it is a feature of many popular coffee styles.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$chocolate-coffee-notes$glossary$, $glossary$https://coffee-dictionary.com/chocolate-coffee-notes/$glossary$),
  ($glossary$Cholesterol$glossary$, $glossary$Cholesterol, a name that comes from the Greek words for bile (*chole-*) and solid (*stereos*), plus the chemical suffix *-ol*, is an organic molecule known as a sterol. It is a basic building block of animal cell membranes, where it has the key job of maintaining proper membrane permeability and structural fluidity. Beyond this cellular role, cholesterol serves as the necessary starting point for the body to make vital substances. These include steroid hormones, bile acids for digestion, and vitamin D.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$cholesterol$glossary$, $glossary$https://coffee-dictionary.com/cholesterol/$glossary$),
  ($glossary$Citrus in Coffee$glossary$, $glossary$Citrus in coffee refers to flavor notes that evoke fruits such as lemon, orange, grapefruit, or lime, characterized by bright acidity and a refreshing tang . These flavors come from specific aromatic compounds present in coffee beans , which become detectable during tasting . Citrus notes appear mostly in light to medium roast coffees, with African origins—particularly Ethiopia, Kenya, and Tanzania—often showing these characteristics .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$citrus-in-coffee-a-flavor-profile$glossary$, $glossary$https://coffee-dictionary.com/citrus-in-coffee-a-flavor-profile/$glossary$),
  ($glossary$Clean Coffee$glossary$, $glossary$Clean coffee represents a category of high-quality, specialty coffee that prioritizes flavor clarity and artisanal production methods over mass-market approaches. This term refers to coffee produced through small-batch roasting, typically ranging from 5-25 kg per batch, which allows for precise control over the roasting process and enhanced flavor complexity.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$clean-coffee-dictionary-term$glossary$, $glossary$https://coffee-dictionary.com/clean-coffee-dictionary-term/$glossary$),
  ($glossary$Cocktail Shaker$glossary$, $glossary$A cocktail shaker in coffee context refers to the barware used to prepare chilled espresso -based beverages through shaking with ice. This technique produces drinks with a distinctive frothy, aerated texture that resembles cocktail preparation methods. The shaking action creates a light, foamy consistency while rapidly chilling the espresso, resulting in a refreshing beverage with an enhanced mouthfeel compared to traditional iced coffee preparations. Popular applications include the Italian Caffè Shakerato and modern specialty coffee interpretations.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$cocktail-shaker$glossary$, $glossary$https://coffee-dictionary.com/cocktail-shaker/$glossary$),
  ($glossary$Coffea$glossary$, $glossary$Coffea is a genus of flowering plants whose seeds, called coffee beans, are used to make coffee. It is a member of the Rubiaceae family. They are shrubs or small trees native to tropical and southern Africa and tropical Asia. Coffee ranks as one of the world’s most valuable and widely traded commodity crops and is an important export product of several countries. The plant is cultivated in over 70 countries, primarily in equatorial Latin America, Southeast Asia, India, and Africa.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffea Arabica$rel$, $rel$Coffea charrieriana$rel$, $rel$Coffea liberica$rel$]::text[], $glossary$coffea$glossary$, $glossary$https://coffee-dictionary.com/coffea/$glossary$),
  ($glossary$Coffea Arabica$glossary$, $glossary$Arabica ( Coffea arabica) Coffea arabica, commonly known as Arabica, is the world’s most widely cultivated coffee species, accounting for approximately 60-70% of global coffee production . Native to the highlands of Ethiopia , this species grows best at elevations between 1,000-2,000 meters in subtropical climates with distinct rainy and dry seasons . Arabica beans are distinguished by their oval shape and central crease, containing less caffeine (0.8-1.4%) than Robusta varieties .$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffea$rel$, $rel$Robusta coffee$rel$]::text[], $glossary$coffea-arabica$glossary$, $glossary$https://coffee-dictionary.com/coffea-arabica/$glossary$),
  ($glossary$Coffea charrieriana$glossary$, $glossary$Coffea charrieriana (or Charrier coffee) is a species of flowering plant in the Rubiaceae family. It is a caffeine-free coffee found in Cameroon. This plant is the only known caffeine-free coffee plant from Central Africa. C. charrieriana was selected as one of “The Top 10 New Species” described in 2008 by The International Institute for Species Exploration at Arizona State University and an international committee of taxonomists.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffea$rel$]::text[], $glossary$coffea-charrieriana$glossary$, $glossary$https://coffee-dictionary.com/coffea-charrieriana/$glossary$),
  ($glossary$Coffea liberica$glossary$, $glossary$Coffea liberica (or Liberian coffee) is a species of flowering plant in the Rubiaceae family. It is a coffee that is found in Liberia, West Africa.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffea$rel$]::text[], $glossary$coffea-liberica$glossary$, $glossary$https://coffee-dictionary.com/coffea-liberica/$glossary$),
  ($glossary$Coffee Acidity$glossary$, $glossary$Coffee Acidity is a fundamental sensory attribute in coffee tasting, referring to the bright, tangy, and vibrant sensation perceived on the palate, often characterized by fruity, citrus, or wine-like flavors. It is a key marker of quality and complexity, distinct from the scientific pH level of the beverage. The perceived acidity arises primarily from organic acids developed in the bean during growth, processing, and roasting.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-acidity$glossary$, $glossary$https://coffee-dictionary.com/coffee-acidity/$glossary$),
  ($glossary$Coffee Aroma$glossary$, $glossary$Coffee Aroma Definition and Sensory Perception Coffee aroma refers to the complex mixture of volatile compounds that create the characteristic scent of coffee, detected primarily through the nose. The development of these aromatic compounds depends heavily on roasting temperature and duration. During roasting, green coffee seeds undergo significant chemical transformations as temperatures rise. When roasted at 180°C for varying durations, coffee develops distinct aromatic profiles based on roast level .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-aroma$glossary$, $glossary$https://coffee-dictionary.com/coffee-aroma/$glossary$),
  ($glossary$Coffee Bloom$glossary$, $glossary$Coffee bloom refers to the rapid release of carbon dioxide gas that occurs when hot water first contacts freshly roasted coffee grounds. This process appears as a bubbling or swelling of the coffee grounds, often accompanied by a distinctive hissing sound. The mechanism behind blooming involves the displacement of trapped CO₂ gas that builds up during roasting . When water meets the grounds, this gas escapes rapidly, creating bubbles and temporarily preventing proper water saturation.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$Degassing$rel$]::text[], $glossary$coffee-bloom$glossary$, $glossary$https://coffee-dictionary.com/coffee-bloom/$glossary$),
  ($glossary$Coffee Body$glossary$, $glossary$Coffee body, also called mouthfeel, refers to the perceived weight, thickness, and texture of coffee on the palate, ranging from thin and watery to full and syrupy. This tactile sensation occurs independently from flavor, creating the physical impression of how coffee feels in the mouth rather than how it tastes. Body is primarily influenced by the concentration of soluble solids, oils, and fine particles suspended in the brewed coffee.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-body-the-texture-and-mouthfeel-of-coffee$glossary$, $glossary$https://coffee-dictionary.com/coffee-body-the-texture-and-mouthfeel-of-coffee/$glossary$),
  ($glossary$Coffee Bouquet$glossary$, $glossary$Coffee Bouquet: The Aroma of Freshly Ground Coffee is the complete, complex scent released when whole coffee beans are ground . It is a key sensory characteristic in professional coffee evaluation, consisting of hundreds of volatile aromatic compounds formed during roasting . This fragrant preview is distinct from the aroma of the brewed coffee itself and plays a major role in shaping our overall perception of flavor .$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-bouquet-the-aroma-of-freshly-ground-coffee$glossary$, $glossary$https://coffee-dictionary.com/coffee-bouquet-the-aroma-of-freshly-ground-coffee/$glossary$),
  ($glossary$Coffee Brewing$glossary$, $glossary$Coffee brewing refers to the preparation of the coffee beverage. There are many coffee brewing methods , and the extraction method can be different for these methods.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$coffee-brewing$glossary$, $glossary$https://coffee-dictionary.com/coffee-brewing/$glossary$),
  ($glossary$Coffee Brewing Methods$glossary$, $glossary$A coffee brewing method is a distinctive coffee preparation method, with specific brewing parameters, and using specific coffee making equipment. Some of the brewing parameters that can be altered to suit a coffee brewing method are:$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$AeroPress$rel$, $rel$Coffee Brewing$rel$, $rel$Coffee percolator$rel$, $rel$Cold Brew Coffee$rel$, $rel$Cowboy Coffee$rel$, $rel$Drip Coffee$rel$, $rel$Espresso$rel$, $rel$French press$rel$, $rel$Immersion Brewing$rel$, $rel$Indian Filter Coffee$rel$, $rel$Kopi Tubruk$rel$, $rel$Moka pot$rel$, $rel$Pour over coffee$rel$, $rel$Siphon Brewer$rel$, $rel$Turkish coffee$rel$]::text[], $glossary$coffee-brewing-methods$glossary$, $glossary$https://coffee-dictionary.com/coffee-brewing-methods/$glossary$),
  ($glossary$Coffee Brewing Temperature$glossary$, $glossary$Water temperature during coffee brewing determines the extraction yield, the total dissolved solids , and chemical profile of the coffee. All these parameters will affect the aroma and flavor of the final cup.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[$rel$Coffee extraction$rel$]::text[], $glossary$water-temperature$glossary$, $glossary$https://coffee-dictionary.com/water-temperature/$glossary$),
  ($glossary$Coffee Cabinet$glossary$, $glossary$The Coffee Cabinet, despite its name, has no connection to coffee roasting or brewing. Instead, it means a regional beverage popular in Rhode Island and southeastern Massachusetts—a milkshake with coffee syrup and ice cream . Rhode Islanders distinguish between “cabinets” and “milkshakes,” with the former containing ice cream and the latter being flavored milk.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$coffee-cabinet$glossary$, $glossary$https://coffee-dictionary.com/coffee-cabinet/$glossary$),
  ($glossary$Coffee Concentrate$glossary$, $glossary$Coffee concentrate is a highly concentrated coffee liquid crafted through a slow, cold extraction process—coarse coffee grounds steep in cold or room-temperature water for 12 to 24 hours before filtering. Unlike traditional hot brewing, this method yields a smooth, low-acidity concentrate valued for its versatility in both flavor and application.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-concentrate$glossary$, $glossary$https://coffee-dictionary.com/coffee-concentrate/$glossary$),
  ($glossary$Coffee Puck$glossary$, $glossary$A coffee puck is the dense, disc-shaped cake of spent coffee grounds left in an espresso machine’s portafilter after extraction. This compacted mass—formed by tamping fresh grounds before brewing—serves as the foundation for balanced extraction, with its structure directly affecting water flow and extraction quality.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-puck$glossary$, $glossary$https://coffee-dictionary.com/coffee-puck/$glossary$),
  ($glossary$Coffee Quality Institute$glossary$, $glossary$The Coffee Quality Institute (CQI) is a nonprofit organization founded in 1996, dedicated to enhancing coffee quality and improving the livelihoods of coffee farmers globally. It is renowned for its Q Grader certification program, which standardizes cupping protocols to assess coffee quality consistently, fostering a universal language for evaluation.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-quality-institute$glossary$, $glossary$https://coffee-dictionary.com/coffee-quality-institute/$glossary$),
  ($glossary$Coffee Sock$glossary$, $glossary$A coffee sock is a reusable cloth filter, typically made of cotton or linen, used to brew coffee by holding grounds as hot water passes through. Resembling a fabric pouch, often sock-shaped, it is suspended over a cup or pot via a wire frame or handle, a hallmark of Costa Rican chorreador or Southeast Asian kopi traditions.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-sock$glossary$, $glossary$https://coffee-dictionary.com/coffee-sock/$glossary$),
  ($glossary$Coffee culture$glossary$, $glossary$Explore the rich cultural traditions surrounding coffee. From cafe culture to coffee ceremonies, discover the social and cultural aspects of coffee around the world.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$]::text[], ARRAY[]::text[], $glossary$coffee-culture$glossary$, $glossary$https://coffee-dictionary.com/coffee-culture/$glossary$),
  ($glossary$Coffee extraction$glossary$, $glossary$Extraction in the context of coffee brewing, is the process of dissolving soluble solids and emulsifying aromatic oils in water. Coffee extraction is a precise process, and there are a few parameters that will determine the taste, aroma, and strength of the brewed coffee. Correctly brewing coffee requires using the correct amount of coffee grounds, extracted to the correct degree, (largely determined by the correct time), at the correct temperature .$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[$rel$Coffee Brewing Temperature$rel$, $rel$Coffee-to-Water Ratio$rel$, $rel$Extraction Time$rel$, $rel$Extraction Yield$rel$, $rel$Total dissolved solids$rel$]::text[], $glossary$coffee-extraction$glossary$, $glossary$https://coffee-dictionary.com/coffee-extraction/$glossary$),
  ($glossary$Coffee filter$glossary$, $glossary$A coffee filter is a porous barrier, typically made of paper, cloth, or metal, used to separate coffee grounds from the brewed liquid during preparation. Its primary function is to clarify the final beverage by retaining solid particles.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Drip Coffee$rel$]::text[], $glossary$coffee-filter$glossary$, $glossary$https://coffee-dictionary.com/coffee-filter/$glossary$),
  ($glossary$Coffee grinding$glossary$, $glossary$Coffee grinding is a critical step in the brewing process, enabling the extraction of soluble solids, caffeine, and oils from the coffee bean. Without this process, extraction would be impossible even at high temperatures, as the compounds remain locked inside the whole bean.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$coffee grind size$rel$, $rel$coffee grinder$rel$]::text[], $glossary$coffee-grinding$glossary$, $glossary$https://coffee-dictionary.com/coffee-grinding/$glossary$),
  ($glossary$Coffee oil$glossary$, $glossary$Aromatic oils are used in perfumery, cosmetics, flavoring of food, and in aromatherapy.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$General Terms$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$fragrance-oil$glossary$, $glossary$https://coffee-dictionary.com/fragrance-oil/$glossary$),
  ($glossary$Coffee percolator$glossary$, $glossary$A coffee percolator is a type of pot used to brew coffee. The name stems from the word “percolate” which means to cause (a solvent) to pass through a permeable substance especially for extracting a soluble constituent. In the case of coffee-brewing the solvent is water, the permeable substance is the coffee grounds, and the soluble constituents are the chemical compounds that give coffee its color, taste, aroma, and stimulating properties.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$coffee-percolator$glossary$, $glossary$https://coffee-dictionary.com/coffee-percolator/$glossary$),
  ($glossary$Coffee production$glossary$, $glossary$Coffee production is the industrial process of converting the raw fruit of the coffee plant, known as a cherry, into the finished green coffee ready for roasting . This journey from farm to roaster is crucial, as each step directly shapes the flavor profile in your cup. The process begins with harvesting, followed by the critical stage of processing—removing the fruit pulp and mucilage from the seed. The method used here, whether washed, natural, or honey processed, has a profound impact on the resulting coffee’s acidity , body , and sweetness.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-production$glossary$, $glossary$https://coffee-dictionary.com/coffee-production/$glossary$),
  ($glossary$Coffee tamping$glossary$, $glossary$Coffee tamping is the action of compacting ground coffee in an espresso portafilter with a tamp, prior to brewing .$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-tamping$glossary$, $glossary$https://coffee-dictionary.com/coffee-tamping/$glossary$),
  ($glossary$Coffee-to-Water Ratio$glossary$, $glossary$The coffee-to-water ratio—a fundamental metric in brewing—refers to the precise relationship between the mass of ground coffee and water, expressed as a weight-based proportion (e.g., 1:15).$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee extraction$rel$]::text[], $glossary$coffee-to-water-ratio$glossary$, $glossary$https://coffee-dictionary.com/coffee-to-water-ratio/$glossary$),
  ($glossary$Coffeehouse$glossary$, $glossary$Coffeehouse, coffee shop, and café are related terms for an establishment which primarily serves prepared coffee or other hot beverages. It shares some of the same characteristics of a bar or restaurant, but it is different from a cafeteria. As the name suggests, coffeehouses focus on providing coffee and tea as well as light snacks.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffeehouse$glossary$, $glossary$https://coffee-dictionary.com/coffeehouse/$glossary$),
  ($glossary$Coffeemaker$glossary$, $glossary$Coffeemakers are devices or cooking appliances used to brew coffee . An appliance can also be referred to as a coffee machine.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Drip Coffee$rel$]::text[], $glossary$coffeemaker$glossary$, $glossary$https://coffee-dictionary.com/coffeemaker/$glossary$),
  ($glossary$Cold Brew Coffee$glossary$, $glossary$Cold brew is a coffee preparation technique where coffee is extracted using cold water or at room temperature. Cold brew coffee is not the same as iced coffee, which refers to coffee that is brewed hot and then chilled by pouring over or adding ice.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$, $rel$Cold Brew Coffee Maker$rel$, $rel$Immersion Cold Brew$rel$, $rel$Nitro Cold Brew$rel$]::text[], $glossary$cold-brew$glossary$, $glossary$https://coffee-dictionary.com/cold-brew/$glossary$),
  ($glossary$Cold Brew Coffee Maker$glossary$, $glossary$A cold brew coffee maker is a specialized device designed for steeping coarsely ground coffee in cold or room-temperature water—typically for 12 to 24 hours—without heat. This slow extraction process yields a smooth, low-acid coffee concentrate, distinct from traditional hot-brewed methods. Most models have a built-in filter or mesh system to separate grounds from the liquid after steeping, ensuring clarity.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee$rel$, $rel$Filtron$rel$, $rel$Puckpuck$rel$, $rel$Takeya$rel$, $rel$Toddy$rel$]::text[], $glossary$cold-brew-coffee-maker$glossary$, $glossary$https://coffee-dictionary.com/cold-brew-coffee-maker/$glossary$),
  ($glossary$Complexity in Coffee$glossary$, $glossary$Complexity in Coffee: A Symphony of Flavors is a metaphorical term describing the multi-layered, evolving flavor profile in coffee tasting . Diverse sensory notes harmonize across aroma, taste, mouthfeel , and aftertaste like a musical symphony . It is a characteristic of high-quality specialty coffee , focusing on the variety and transformation of distinct flavors .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$complexity-in-coffee-a-symphony-of-flavors$glossary$, $glossary$https://coffee-dictionary.com/complexity-in-coffee-a-symphony-of-flavors/$glossary$),
  ($glossary$Concentration$glossary$, $glossary$In coffee brewing, concentration is an important factor, determining the coffee strength, taste and flavor. In specialty coffee , Total Dissolved Solids concentration is an important factor. Many people are particularly interested in caffeine concentration.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$concentration$glossary$, $glossary$https://coffee-dictionary.com/concentration/$glossary$),
  ($glossary$Cortadito$glossary$, $glossary$Cortadito (from Spanish cortar , meaning “to cut”) refers to a Cuban espresso -based coffee drink . It is a sweetened cortado, where a shot of strong espresso is first mixed with sugar to create a creamy foam known as espumita . This mixture is then “cut” with a small amount of warm steamed or condensed milk.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$cortadito$glossary$, $glossary$https://coffee-dictionary.com/cortadito/$glossary$),
  ($glossary$Cortado$glossary$, $glossary$A Cortado is a Spanish-origin coffee beverage consisting of one part espresso cut with an equal part of warm, lightly textured milk. The name derives from the Spanish verb ‘cortar’ (to cut), referring to how the milk cuts the espresso’s acidity. Originating in Spain’s Basque Country, it is a staple in Spanish and Portuguese cafés, defined by its small volume (4-6 oz) and balanced 1:1 to 1:2 espresso-to-milk ratio.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$cortado$glossary$, $glossary$https://coffee-dictionary.com/cortado/$glossary$),
  ($glossary$Cowboy Coffee$glossary$, $glossary$Cowboy Coffee refers to a traditional coffee brewing method from the American West . This method involves adding coarsely ground coffee directly to a pot of boiling water over an open fire, which produces an unfiltered immersion brew. Cowboy coffee is known for its strong flavor and practicality. It plays a role in outdoor culture, as the process uses no specialized equipment beyond a pot and a heat source.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$cowboy-coffee$glossary$, $glossary$https://coffee-dictionary.com/cowboy-coffee/$glossary$),
  ($glossary$Crema Quality$glossary$, $glossary$Quality crema displays distinct visual and textural characteristics that distinguish exceptional espresso from mediocre shots. Premium crema is known for a rich golden-brown to reddish-brown color, forming a smooth, velvety layer that measures 3-5mm in thickness. This foam should persist for 2-3 minutes without dissipating quickly, maintaining complete surface coverage across the espresso shot. The texture plays a role in showing crucial quality indicators.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$crema-quality$glossary$, $glossary$https://coffee-dictionary.com/crema-quality/$glossary$),
  ($glossary$Crust in Coffee Cupping$glossary$, $glossary$The crust in coffee cupping refers to the layer of coffee grounds that forms on the surface when hot water is poured over freshly ground coffee. This physical barrier develops as the grounds float and create a cohesive layer across the water’s surface.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$crust-in-coffee-cupping-an-essential-element$glossary$, $glossary$https://coffee-dictionary.com/crust-in-coffee-cupping-an-essential-element/$glossary$),
  ($glossary$Cuban espresso$glossary$, $glossary$Cuban espresso, known locally as ‘café cubano’ or ‘cafecito’, is a strong, sweetened shot of espresso that serves as a cornerstone of Cuban coffee culture . It originated in Cuba during the early 20th century, evolving from Italian espresso traditions adapted to local tastes and the availability of cheaper, darker roasted beans.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$cuban-espresso$glossary$, $glossary$https://coffee-dictionary.com/cuban-espresso/$glossary$),
  ($glossary$Cuisinart$glossary$, $glossary$Cuisinart is a brand for small kitchen appliances , especially the food processor of the same name, one of the first to become popular in the United States .$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$cuisinart$glossary$, $glossary$https://coffee-dictionary.com/cuisinart/$glossary$),
  ($glossary$Cup$glossary$, $glossary$A coffee cup is a container thatcoffeeandespresso-based drinks are served in. Coffee cupsare made of porcelain, ceramic, or tempered glass and they can have a handlefor portability. Ceramic and porcelain provide insulation , maintaining the beverage hot. Tempered glassware needs a double wall construction in order to provide insulation.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$cup$glossary$, $glossary$https://coffee-dictionary.com/cup/$glossary$),
  ($glossary$Dallah (coffee pot)$glossary$, $glossary$A dallah is a traditional metal coffee pot , instantly recognizable by its distinctive long, curved spout. It is specifically designed for preparing Arabic coffee , holding a place of particular importance in Saudi coffee culture . The pot is not merely a tool for brewing but a central object in the social and ceremonial serving of coffee, reflecting deep-rooted customs of hospitality and community.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Arabic coffee$rel$]::text[], $glossary$dallah-coffee-pot$glossary$, $glossary$https://coffee-dictionary.com/dallah-coffee-pot/$glossary$),
  ($glossary$Dark Roast$glossary$, $glossary$Dark roast coffee is roasted beyond the second crack, producing bold, smoky, and bittersweet flavors with low acidity, full body, and oily bean surfaces.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$coffee roasting$rel$]::text[], $glossary$dark-roast$glossary$, $glossary$https://coffee-dictionary.com/dark-roast/$glossary$),
  ($glossary$Decaffeination$glossary$, $glossary$Decaffeination refers to extracting at least 97% of caffeine from green coffee beans before roasting . The process began commercially in 1905 when Ludwig Roselius developed a benzene-based method . Today, four main techniques are used: Direct Solvent, Indirect Solvent, Swiss Water, and Carbon Dioxide.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$decaffeination$glossary$, $glossary$https://coffee-dictionary.com/decaffeination/$glossary$),
  ($glossary$Decanter$glossary$, $glossary$A decanter is a vessel that is used to hold the decantation of a liquid which may contain sediment. Decanters are normally used as serving vessels for wine. Decanters vary in shape and design. They are usually made of an inert material and will hold at least one standard bottle of wine (0.75 litre). A similar kind of vessel, the carafe /kəˈræf/, is used for serving wine as well as other drinks, but is not supplied with a stopper.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$decanter$glossary$, $glossary$https://coffee-dictionary.com/decanter/$glossary$),
  ($glossary$Degassing$glossary$, $glossary$Degassing is the process by which freshly roasted coffee releases CO2 gas over time, which must partially complete before brewing for optimal extraction.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee Bloom$rel$, $rel$coffee roasting$rel$]::text[], $glossary$carbon-dioxide$glossary$, $glossary$https://coffee-dictionary.com/carbon-dioxide/$glossary$),
  ($glossary$Dementia$glossary$, $glossary$Dementia (from Latin dementia , ‘madness’) refers to a medical condition characterized by a serious, progressive decline in global cognitive ability, including thinking, reasoning, memory, and emotional regulation, often resulting from widespread brain injury or neurodegenerative diseases like Alzheimer’s. This static, global impairment manifests as a loss of vibrancy and richness in mental function, akin to the flat, lifeless sensory experience of underdeveloped coffee beans known for a baked flavor profile.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$, $cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$dementia$glossary$, $glossary$https://coffee-dictionary.com/dementia/$glossary$),
  ($glossary$Demitasse$glossary$, $glossary$A demitasse is a small cup used to serve Turkish coffee or espresso . In some languages it is called fincan, fildžan, filxhan or φλιτζάνι (flidzáni). In Spanish, it is called a pocillo. It typically has about 60–90 ml capacity — half the size of a full coffee cup (a tasse à café is about 120 ml). Typically they are made of white pottery or porcelain and accompanied by matching saucers, but some coffeehouses and companies from chinaalso produce brightly decorated varieties.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$demitasse$glossary$, $glossary$https://coffee-dictionary.com/demitasse/$glossary$),
  ($glossary$Descaling$glossary$, $glossary$Descaling removes mineral buildup—primarily calcium and limescale—from coffee equipment after repeated heated water exposure. These deposits accumulate in critical components like boilers, pipes, and group heads, impairing heat transfer and restricting water flow while introducing off-flavors by disrupting extraction.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$descaling$glossary$, $glossary$https://coffee-dictionary.com/descaling/$glossary$),
  ($glossary$De’Longhi$glossary$, $glossary$De’Longhi Group, or De’Longhi S.p. A, is a major Italian small appliance manufacturer based in Treviso, Italy. They manufacture coffee making equipment, including drip coffee makers and espresso machines.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$delonghi$glossary$, $glossary$https://coffee-dictionary.com/delonghi/$glossary$),
  ($glossary$Diabetes mellitus$glossary$, $glossary$Diabetes mellitus, commonly called diabetes, is a long-term metabolic disorder marked by consistently high blood sugar levels. The condition stems from an issue with insulin, the hormone that manages blood glucose. This problem happens either because the pancreas does not produce sufficient insulin or because the body’s cells stop responding to it properly, a state known as insulin resistance. As a result, glucose builds up in the bloodstream. This leads to the three classic signs: polyuria (frequent urination), polydipsia (increased thirst), and polyphagia (heightened hunger). Without careful management, prolonged high blood sugar can cause severe damage to the heart, blood vessels, eyes, kidneys, and nerves. The disease is primarily divided into three types: Type 1 diabetes, where the immune system attacks insulin-producing cells; Type 2 diabetes, defined by insulin resistance and often a gradual loss of insulin production; and gestational diabetes, which emerges during pregnancy. While their origins differ, all forms share the core difficulty of controlling blood sugar through a combination of medication, dietary choices, and lifestyle changes.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$diabetes-mellitus$glossary$, $glossary$https://coffee-dictionary.com/diabetes-mellitus/$glossary$),
  ($glossary$Dialing In$glossary$, $glossary$Dialing In (spelled dialling in in UK/ Australia ) refers to the process of adjusting an espresso machine and grinder to produce a balanced shot from a specific coffee. This daily routine involves fine-tuning several variables based on taste . The term comes from the act of turning a grinder’s dial to change the fineness of the coffee grounds, a setting that plays a crucial role in extraction.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$dialing-in$glossary$, $glossary$https://coffee-dictionary.com/dialing-in/$glossary$),
  ($glossary$Dissolution (chemistry)$glossary$, $glossary$Dissolution is the process by which a solute forms a solution in a solvent. The solute, in the case of solids, has its crystalline structure disintegrated as separate ions, atoms, and molecules form. For liquids and gases, the molecules must be adaptable with those of the solvent for a solution to form. The outcome of the process of dissolution (the amount dissolved at equilibrium.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$dissolution-chemistry$glossary$, $glossary$https://coffee-dictionary.com/dissolution-chemistry/$glossary$),
  ($glossary$Dolce Gusto$glossary$, $glossary$The Nescafé Dolce Gusto is an espresso machine /coffee capsule system from Nestlé. The machines are produced by hardware manufacturers Krups and De’Longhi .$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$single serve coffee maker$rel$]::text[], $glossary$dolce-gusto$glossary$, $glossary$https://coffee-dictionary.com/dolce-gusto/$glossary$),
  ($glossary$Dorian Bodnariuc$glossary$, $glossary$Dorian Bodnariuc is the founder of Coffee-Brewing-Methods.com . He started his coffee career as a barista, then moved in the IT, but he kept the contact with the coffee industry.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$dorian-bodnariuc$glossary$, $glossary$https://coffee-dictionary.com/dorian-bodnariuc/$glossary$),
  ($glossary$Double Espresso Shot$glossary$, $glossary$Double, in the context of espresso brewing , refers to the volume of coffee pulled at one time. A double shot of espresso is pulled from approximately 14 grams of coffee grounds. The filter basket used for pulling it, is also called a double, and it can hold 14 grams of coffee grounds. The double espresso shot is also called a doppio, the Italian word for double.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$double$glossary$, $glossary$https://coffee-dictionary.com/double/$glossary$),
  ($glossary$Drink$glossary$, $glossary$A drink, or beverage, is a kind of liquid which is specifically prepared for human consumption. There are many groups of drinks. It can be divided into various groups such as plain water, alcohol, non alcoholic drinks, soft drinks (carbonated drinks), fruit or vegetable juices and hot drinks. In addition to fulfilling a basic need, drinks form part of the culture of human society.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$drink$glossary$, $glossary$https://coffee-dictionary.com/drink/$glossary$),
  ($glossary$Drip Coffee$glossary$, $glossary$Drip coffee is brewed by passing hot water through a paper or metal filter containing ground coffee, with the brewed liquid dripping into a carafe below.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$, $rel$Coffee filter$rel$, $rel$Coffeemaker$rel$]::text[], $glossary$drip-coffee$glossary$, $glossary$https://coffee-dictionary.com/drip-coffee/$glossary$),
  ($glossary$Drip Tray$glossary$, $glossary$A drip tray is a removable grate and reservoir positioned beneath an espresso machine’s group head, serving as the first line of defense against spills by collecting excess water, stray coffee grounds, and beverage overflow during brewing. This component does more than contain mess—it prevents liquid and residue buildup that could compromise machine surfaces or countertop hygiene.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$drip-tray$glossary$, $glossary$https://coffee-dictionary.com/drip-tray/$glossary$),
  ($glossary$Dual Boiler$glossary$, $glossary$A dual boiler espresso machine features two dedicated boilers—one for brewing and another for steaming—enabling independent temperature control for simultaneous operation. Unlike single-boiler models, this design eliminates task-switching delays, ensuring precise extraction temperatures and stable steam pressure . The brew boiler optimizes flavor extraction, while the steam boiler delivers consistent microfoam for milk drinks.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$dual-boiler$glossary$, $glossary$https://coffee-dictionary.com/dual-boiler/$glossary$),
  ($glossary$Dunkin’ Donuts$glossary$, $glossary$Dunkin’ Donuts is an American global doughnut company and coffeehouse chain based in Canton, Massachusetts. It was founded in 1950 by William Rosenberg in Quincy, Massachusetts. Its logo is two D’s side by side in orange and hot pink. The company primarily competes with Starbucks , as over half the company’s business is in coffee sales, and with Krispy Kreme for doughnut sales.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$]::text[], ARRAY[]::text[], $glossary$dunkin-donuts$glossary$, $glossary$https://coffee-dictionary.com/dunkin-donuts/$glossary$),
  ($glossary$E-61$glossary$, $glossary$E-61 is a class of espresso machine , defining a standard size and fitting for the portafilter which holds the ground coffee. E-61 is a common standard for commercial espresso machines. The name E-61 comes from the Faema E-61 espresso machine, which was named for the solar eclipse in its year of introduction, 1961.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$e-61$glossary$, $glossary$https://coffee-dictionary.com/e-61/$glossary$),
  ($glossary$ESE pods$glossary$, $glossary$An Easy Serving Espresso Pod, or E.S.E. pod, is a small coffee disc (Coffee pod), packed in a paper filter covering. Each pod contains 7 grams of compressed ground coffee, ready to be extracted into a shot. A double serving pod, (doppio), contains 14 grams of ground coffee. Pods are typically 44-45mm size for E.S.E. certified machines. There are many Espresso machines that can use the 45 mm diameter E.S.E Espresso standard Pod.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Pod Coffee Machine$rel$]::text[], $glossary$ese-pods$glossary$, $glossary$https://coffee-dictionary.com/ese-pods/$glossary$),
  ($glossary$Earthy Coffee$glossary$, $glossary$Earthy coffee presents a distinctive sensory experience characterized by rich, natural flavors that evoke soil, wood, and herbs . This flavor profile creates a connection to the earth through its deep, grounding taste sensations that coffee enthusiasts describe as reminiscent of forest floors or freshly turned garden soil. The aroma of earthy coffee typically carries notes of damp earth, mushrooms, and sometimes cedar or other woody elements .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$earthy-coffee-a-flavor-profile$glossary$, $glossary$https://coffee-dictionary.com/earthy-coffee-a-flavor-profile/$glossary$),
  ($glossary$Espressino$glossary$, $glossary$Espressino (pronounced es-press-EE-no, from the Italian diminutive suffix ‘-ino’ meaning ‘small’) is a small Italian coffee beverage that is a regional variation of a cortado or macchiato with chocolate. It originates from the Puglia (Apulia) region in southern Italy. The drink is defined by its combination of a single shot of espresso , a small amount of frothed milk, and cocoa powder or chocolate spread.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$espressino$glossary$, $glossary$https://coffee-dictionary.com/espressino/$glossary$),
  ($glossary$Espresso$glossary$, $glossary$Espresso is a concentrated coffee beverage brewed by forcing hot water under high pressure (9 bars) through finely ground, tightly packed coffee, producing a small, intense shot with crema.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Barista$rel$, $rel$Bicerin$rel$, $rel$Breve$rel$, $rel$Caffeine$rel$, $rel$Caffè Latte$rel$, $rel$Cappuccino$rel$, $rel$Coffee Brewing Methods$rel$, $rel$coffee grind size$rel$, $rel$Cortadito$rel$, $rel$Cortado$rel$, $rel$Dialing In$rel$, $rel$Double Espresso Shot$rel$, $rel$Espressino$rel$, $rel$Espresso Macchiato$rel$, $rel$Espresso Machine$rel$, $rel$Flat white$rel$, $rel$Galão$rel$, $rel$Latte$rel$, $rel$Latte macchiato$rel$, $rel$Lungo$rel$, $rel$Macchiato$rel$, $rel$Marocchino$rel$, $rel$Melya$rel$, $rel$Normale$rel$, $rel$Ristretto$rel$, $rel$Single Espresso Shot$rel$, $rel$Triple Espresso Shot$rel$]::text[], $glossary$espresso$glossary$, $glossary$https://coffee-dictionary.com/espresso/$glossary$),
  ($glossary$Espresso Beans$glossary$, $glossary$Espresso beans are coffee beans roasted and blended specifically for espresso preparation, typically with a darker roast profile. While any bean can be used for espresso, those labeled as ‘espresso beans’ are optimized for high-pressure extraction , yielding a balanced, concentrated shot with lower acidity and richer body. These qualities make them ideal for milk-based drinks like lattes and cappuccinos.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$coffee beans$rel$]::text[], $glossary$espresso-beans$glossary$, $glossary$https://coffee-dictionary.com/espresso-beans/$glossary$),
  ($glossary$Espresso Blend$glossary$, $glossary$An espresso blend combines beans from multiple origins, roasted and blended to create a balanced, flavorful shot when extracted under high pressure. Crafted to highlight complementary flavors, these blends emphasize sweetness, body , and acidity while ensuring batch-to-batch consistency. A well-designed blend has equal appeal in straight espresso and milk-based drinks, delivering harmony whether enjoyed alone or with dairy.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$coffee beans$rel$]::text[], $glossary$espresso-blend$glossary$, $glossary$https://coffee-dictionary.com/espresso-blend/$glossary$),
  ($glossary$Espresso Macchiato$glossary$, $glossary$The espresso macchiato is a coffee espresso drink with a small amount of steamed milk , usually as foam, on top.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$espresso-macchiato$glossary$, $glossary$https://coffee-dictionary.com/espresso-macchiato/$glossary$),
  ($glossary$Espresso Machine$glossary$, $glossary$An espresso machine is a device that forces hot water under high pressure (9 bars) through finely ground coffee to produce concentrated espresso shots.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$brew group$rel$, $rel$Espresso$rel$, $rel$filter basket$rel$, $rel$Manual Espresso Machine$rel$, $rel$portafilter$rel$, $rel$Semi Automatic Espresso Machine$rel$, $rel$Super Automatic Espresso Machine$rel$]::text[], $glossary$espresso-machine$glossary$, $glossary$https://coffee-dictionary.com/espresso-machine/$glossary$),
  ($glossary$Espresso con panna$glossary$, $glossary$Espresso con panna, Italian for “espresso with cream,” refers to a standard shot of espresso topped with a dollop of whipped cream . The whipped cream gradually melts into the espresso, creating a sweetened and textured drinking experience without additional sugar. This preparation highlights the intensity of espresso while softening its edge with the richness of cream. Some variations include a light dusting of cocoa powder or a drizzle of caramel as optional garnishes .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$espresso-con-panna$glossary$, $glossary$https://coffee-dictionary.com/espresso-con-panna/$glossary$),
  ($glossary$Espro P7$glossary$, $glossary$The Espro P7 features a double-walled stainless steel French press design with a patented two-stage micro-filter system, minimizing sediment while preserving coffee’s natural oils and full-bodied texture. Developed by Canadian brand Espro, it combines immersion brewing benefits with a cleaner cup, eliminating paper filters entirely. Its dual precision filters (fine and ultra-fine mesh) trap grounds without over-extraction, ensuring a balanced, grit-free brew.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$espro-p7$glossary$, $glossary$https://coffee-dictionary.com/espro-p7/$glossary$),
  ($glossary$Ethiopia$glossary$, $glossary$Ethiopia, officially the Federal Democratic Republic of Ethiopia, is a country in the Horn of Africa. It shares borders with Eritrea to the north, Djibouti and Somalia to the east, Sudan and South Sudan to the west, and Kenya to the south. With a population of over 91 million, it is the most populous landlocked country in the world and the second-most populous nation on the African continent.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$ethiopia$glossary$, $glossary$https://coffee-dictionary.com/ethiopia/$glossary$),
  ($glossary$Extraction Time$glossary$, $glossary$Extraction time—the period from water’s initial contact with coffee grounds to the final drip—determines flavor balance by regulating the dissolution of soluble compounds: acids, sugars, and bitter elements. Shorter extractions (e.g., espresso) highlight bright acidity but may lack sweetness, yielding a sour taste. Longer extractions (e.g., immersion brewing ) risk over-extracting tannins, introducing astringency.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee extraction$rel$]::text[], $glossary$extraction-time$glossary$, $glossary$https://coffee-dictionary.com/extraction-time/$glossary$),
  ($glossary$Extraction Yield$glossary$, $glossary$Extraction yield measures the percentage of coffee solids dissolved into the brewed liquid, calculated as extracted solubles relative to the original dry coffee mass. This metric shapes flavor balance by determining how much of the coffee’s key compounds (acids, sugars, and bitter elements) transfer during brewing. In specialty coffee , the 18–22% range is widely targeted for optimal extraction, where sweetness, acidity , and bitterness harmonize.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee extraction$rel$]::text[], $glossary$extraction-yield$glossary$, $glossary$https://coffee-dictionary.com/extraction-yield/$glossary$),
  ($glossary$Ferment Flavor in Coffee$glossary$, $glossary$Ferment flavor in coffee refers to the distinctive sensory characteristics in the cup that develop when coffee cherries undergo controlled microbial activity during post-harvest processing. This flavor profile, valued by baristas and roasters , typically presents as bright acidity with fruity , winey , or complex notes.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$ferment-flavor-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/ferment-flavor-in-coffee/$glossary$),
  ($glossary$Filtration$glossary$, $glossary$Filtration is commonly the mechanical or physical operation which is used for the separation of solids from fluids (liquids or gases) by interposing a medium through which only the fluid can pass. Oversize solids in the fluid are retained, but the separation is not complete; solids will be contaminated with some fluid and filtrate will contain fine particles (depending on the pore size and filter thickness).$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$filtration$glossary$, $glossary$https://coffee-dictionary.com/filtration/$glossary$),
  ($glossary$Filtron$glossary$, $glossary$A Filtron is a gravity-fed cold brew coffee maker designed for slow, controlled extraction—typically one drop per second—over 12-24 hours. Modeled after Japanese Kyoto-style brewers, its three-part system (water reservoir, filter chamber, and carafe) ensures even saturation while minimizing agitation.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee Maker$rel$]::text[], $glossary$filtron$glossary$, $glossary$https://coffee-dictionary.com/filtron/$glossary$),
  ($glossary$Flat Coffee$glossary$, $glossary$The Flat White is a distinct coffee preparation that emerged from Australia and New Zealand before gaining international popularity. Traditionally served in a 180 ml ceramic cup in Australia, the Flat White contains less milk than the Australian latte, which typically comes in a 200 ml glass . This smaller milk-to-coffee ratio creates a more concentrated flavor profile. Size specifications vary globally, with the authentic Flat White measuring approximately 162 ml (5.5 oz) .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$flat-coffee-what-does-it-mean$glossary$, $glossary$https://coffee-dictionary.com/flat-coffee-what-does-it-mean/$glossary$),
  ($glossary$Flat white$glossary$, $glossary$A flat white is a coffee beverage consisting of espresso topped with microfoam-textured milk . Distinguished by its velvety texture and strong coffee flavor, it is typically served in a small cup (5-8oz/150-240ml) to maintain a coffee-forward profile .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$flat-white$glossary$, $glossary$https://coffee-dictionary.com/flat-white/$glossary$),
  ($glossary$Flavor$glossary$, $glossary$Flavor or flavour is the sensory impression of a foods, drinks, or other substances, and is determined mainly by the chemical senses of taste and smell. The “trigeminal senses”, which detect chemical irritants in the mouth and throat as well as temperature and texture, are also very important to the overall Gestalt of flavor perception. The flavor of the food, as such, can be altered with natural or artificial flavorants, which affect these senses.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$flavor$glossary$, $glossary$https://coffee-dictionary.com/flavor/$glossary$),
  ($glossary$Flavored Coffee$glossary$, $glossary$Flavored coffee refers to coffee beans treated with natural or artificial flavoring agents—typically after roasting—to create distinct aromatic and taste profiles. These oil-based flavorings, ranging from vanilla to seasonal spices, originated to enhance lower-quality beans but now cater to consumers seeking consistent, dessert-like experiences without extra additives.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$flavored-coffee$glossary$, $glossary$https://coffee-dictionary.com/flavored-coffee/$glossary$),
  ($glossary$Floral Notes in Coffee$glossary$, $glossary$Floral notes in coffee represent aromatic and flavor characteristics that evoke flowers, ranging from delicate jasmine and rose to bright lavender and orange blossom. These sensory qualities emerge from complex interactions between coffee origin, post-harvest processing methods, roasting techniques, and brewing parameters. Processing methods influence floral expression.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$floral-notes-in-coffee-an-overview$glossary$, $glossary$https://coffee-dictionary.com/floral-notes-in-coffee-an-overview/$glossary$),
  ($glossary$Flow Rate$glossary$, $glossary$Flow rate quantifies the speed of water moving through coffee grounds during brewing, measured in grams per second. In espresso, this metric tracks water exiting the portafilter; for pour-overs, it governs drainage through the filter. This critical variable shapes extraction, influencing contact time and extraction outcomes.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$flow-rate$glossary$, $glossary$https://coffee-dictionary.com/flow-rate/$glossary$),
  ($glossary$Foam$glossary$, $glossary$Foam is an important aspect of coffee preparation, and it determines, or validates quality in some coffee drinks.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$foam$glossary$, $glossary$https://coffee-dictionary.com/foam/$glossary$),
  ($glossary$Food$glossary$, $glossary$Food is any substance consumed to provide nutritional support for the body . It is usually of plant or animal origin, and contains essential nutrients, such as carbohydrates, fats, proteins, vitamins, or minerals. The substance is ingested by an organism and assimilated by the organism’s cells in an effort to produce energy, maintain life, or stimulate growth. Historically, people secured food through two methods: hunting and gathering, and agriculture.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$food$glossary$, $glossary$https://coffee-dictionary.com/food/$glossary$),
  ($glossary$Francis Francis!$glossary$, $glossary$FrancisFrancis! is an espresso machine manufacturer owned by illy. Founded in 1994 by Francesco Illy , FrancisFrancis produces espresso machines for the home market. Italian architect Luca Trazzi was responsible for the aesthetics. In 2004 the company was purchased by illy. Since then, FrancisFrancis! have become the espresso machines of choice for illy; always associated with the coffee brand. Various FrancisFrancis! machines are designed by other award-winning designers and are considered a piece of industrial art on their own. The Francis Francis! espresso makers were some of the first to feature the option of E.S.E. pods. Later on, illy introduced the iperEspresso system which produces one of the best capsule based espresso beverages.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$francisfrancis$glossary$, $glossary$https://coffee-dictionary.com/francisfrancis/$glossary$),
  ($glossary$Frappuccino$glossary$, $glossary$Frappuccino is a trademarked line of blended coffee beverages sold by Starbucks . It consists of coffee , blended with ice and other various ingredients, usually topped with whipped cream. Frappuccinos are also sold as bottled coffee beverages in stores and from vending machines.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$frappuccino$glossary$, $glossary$https://coffee-dictionary.com/frappuccino/$glossary$),
  ($glossary$Frappé$glossary$, $glossary$The Frappé is a shaken or blended iced coffee beverage famously reliant on instant coffee as its base. This choice highlights the tension between accessibility and specialty values. Nearly 50 percent of the world’s coffee crop is processed into instant coffee. For coffee professionals, the Frappé is known for its unique preparation method, where agitation creates a stable, creamy foam without dairy. This technique plays a role in understanding emulsion and texture in other coffee applications, from whipped coffee to shaken espresso .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$frappe$glossary$, $glossary$https://coffee-dictionary.com/frappe/$glossary$),
  ($glossary$French drip$glossary$, $glossary$French drip is a manual coffee brewing method that uses a special carafe. The carafe has a filter and a lid that are placed on top. The brewing technique is similar to other manual drip coffee brewing methods . Coffee is coarsely ground and placed in the filter. The filter is placed on top of the carafe, and it is designed to fit snugly. Then hot water is poured over the coffee grounds. The filter retains the grounds, while brewed coffee passes through in the pot. At the end the filter is covered with a lid that prevents coffee from getting cold.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[]::text[], $glossary$french-drip$glossary$, $glossary$https://coffee-dictionary.com/french-drip/$glossary$),
  ($glossary$French press$glossary$, $glossary$The French press is a full-immersion brewing method where coarsely ground coffee steeps in hot water before a metal mesh plunger is pressed down to separate grounds from the brew.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$french-press$glossary$, $glossary$https://coffee-dictionary.com/french-press/$glossary$),
  ($glossary$Fruity Notes in Coffee$glossary$, $glossary$Fruity notes in coffee refer to the aromatic and flavor characteristics reminiscent of various fruits detected during a coffee cupping or brew evaluation . These notes are categorized into distinct sensory groups central to coffee flavor profiling. Berry notes include raspberry and blueberry characteristics prized in some African coffees, while citrus covers lemon and orange impressions. Stone fruit notes show peach and plum qualities, and tropical fruit notes include pineapple and passion fruit .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$fruity-notes-in-coffee-an-overview$glossary$, $glossary$https://coffee-dictionary.com/fruity-notes-in-coffee-an-overview/$glossary$),
  ($glossary$Full Immersion$glossary$, $glossary$Full immersion is a coffee brewing method where ground coffee remains fully submerged in water throughout extraction, ensuring even saturation and uniform flavor development. Unlike percolation methods—which pass water through grounds once—full immersion maintains continuous contact, yielding a balanced, full-bodied cup. This approach prioritizes control, enabling precise adjustment of steep time, temperature, and agitation to influence extraction.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$full-immersion$glossary$, $glossary$https://coffee-dictionary.com/full-immersion/$glossary$),
  ($glossary$Gaggia$glossary$, $glossary$Gaggia is an Italian company that makes coffee machines, especially espresso and cappuccino machines, in addition to small kitchen appliances . The company is mainly owned by Saeco International Group, a division of Dutch consumer electronics giant Philips.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$gaggia$glossary$, $glossary$https://coffee-dictionary.com/gaggia/$glossary$),
  ($glossary$Gaggia Classic Pro$glossary$, $glossary$The Gaggia Classic Pro is an entry-level semi-automatic espresso machine crafted by Italian manufacturer Gaggia for home use. Designed with commercial-grade components like a 58mm portafilter and a three-way solenoid valve, it bridges professional and domestic espresso-making. Its robust construction and straightforward design make it ideal for mastering techniques such as shot extraction and milk texturing.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$gaggia-classic-pro$glossary$, $glossary$https://coffee-dictionary.com/gaggia-classic-pro/$glossary$),
  ($glossary$Galão$glossary$, $glossary$Galão ( Portuguese pronunciation: [ɡɐˈlɐ̃w̃]) refers to a traditional Portuguese hot coffee drink . It consists of one part espresso combined with three parts foamed milk, served in a tall glass. This beverage is a type of Portugal’s standard café-style latte and is known for its mild, creamy flavor profile. The name translates to “gallon,” which means the drink’s substantial milk volume.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$galao$glossary$, $glossary$https://coffee-dictionary.com/galao/$glossary$),
  ($glossary$God Shot$glossary$, $glossary$A God shot can be described as a perfect shot achieved from an espresso machine, where the recipe and all of the parameters that go into espresso brewing such as bean type, roast, grind size , dose, water volume and temperature , as well as properly maintained and clean machinery all align to produce a coffee shot that is considered to be perfect by the taster, barista or customer.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$god-shot$glossary$, $glossary$https://coffee-dictionary.com/god-shot/$glossary$),
  ($glossary$Grassy Notes in Coffee$glossary$, $glossary$Grassy notes in coffee represent a distinct flavor characteristic that manifests as fresh-cut grass, hay, or herbaceous qualities in the cup. These flavors typically indicate underdeveloped coffee beans or processing issues that prevent proper flavor maturation during roasting. The identification and classification of such defects is known for increasing sophistication through research initiatives.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$grassy-notes-in-coffee-a-detailed-examination$glossary$, $glossary$https://coffee-dictionary.com/grassy-notes-in-coffee-a-detailed-examination/$glossary$),
  ($glossary$Grouphead$glossary$, $glossary$The grouphead is the component of an espresso machine where the portafilter attaches, housing the dispersion screen and gasket that distribute hot water evenly to the coffee puck. It functions as the critical interface between the machine and the coffee, enabling precise water distribution and temperature control during extraction.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$grouphead$glossary$, $glossary$https://coffee-dictionary.com/grouphead/$glossary$),
  ($glossary$Hamilton Beach Brands$glossary$, $glossary$Hamilton Beach Brands, Inc. is an American manufacturer of home appliances , air purifiers, and commercial restaurant equipment marketed primarily in the United States, Canada , and Mexico including: Blenders, Mixers, Toasters, Slow cookers, Irons and Air purifiers. Until sometime in the 1980s the company’s products were marketed under the brand name “Hamilton Beach Scovill”, reflecting a merger that occurred in the 1940s.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$hamilton-beach-brands$glossary$, $glossary$https://coffee-dictionary.com/hamilton-beach-brands/$glossary$),
  ($glossary$Handpresso$glossary$, $glossary$Handpresso SARL is a French manufacturer of portable espresso machines . Founded in Fontainebleau in 2006 by Henrik Nielsen as a spin-off from Nielsen Innovation SARL. Handpresso is inspired by Danish Design and has created and patented the world’s first handheld espresso coffeemaker, Handpresso WILD ESE, which is sold in 25 countries. The first Handpresso machines were designed for E.S.E. coffee pods . In the year 2008, Handpresso won 7 international design prizes including IF and Formland.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$handpresso$glossary$, $glossary$https://coffee-dictionary.com/handpresso/$glossary$),
  ($glossary$Hario$glossary$, $glossary$Hario is a Japanese company specializing in high-quality glassware and coffee brewing equipment, renowned for its V60 pour-over dripper. Founded in 1921 as a manufacturer of laboratory glass, Hario transitioned to coffee products, leveraging its expertise in heat-resistant materials to create precise, durable tools. The V60, introduced in the 2000s, features a distinctive cone shape with spiral ribs, promoting even extraction.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$hario$glossary$, $glossary$https://coffee-dictionary.com/hario/$glossary$),
  ($glossary$Hario V60$glossary$, $glossary$The Hario V60 is a cone-shaped pour-over dripper with spiral ridges and a large single hole, allowing precise control over flow rate and extraction.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Pour over coffee$rel$]::text[], $glossary$hario-v60$glossary$, $glossary$https://coffee-dictionary.com/hario-v60/$glossary$),
  ($glossary$Harsh Coffee$glossary$, $glossary$Harsh coffee represents an undesirable flavor profile characterized by sharp, aggressive, and unpleasant sensory experiences. This negative descriptor includes off-putting characteristics that make coffee difficult to enjoy, typically featuring bitter compounds that create an astringent, mouth-puckering sensation. These flavors often present as metallic, acrid, or burning notes that linger.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$harsh-coffee-a-flavor-profile$glossary$, $glossary$https://coffee-dictionary.com/harsh-coffee-a-flavor-profile/$glossary$),
  ($glossary$Heart$glossary$, $glossary$The heart is a hollow muscle that pumps blood throughout the blood vessels by repeated, rhythmic contractions . It is found in all animals with a circulatory system. The term cardiac means “related to the heart” and comes from the Greek καρδιά, kardia, for “heart”.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$heart$glossary$, $glossary$https://coffee-dictionary.com/heart/$glossary$),
  ($glossary$Heat exchanger$glossary$, $glossary$A heat exchanger is a piece of equipment built for efficient heat transfer from one medium to another. The media may be separated by a solid wall, so that they never mix, or they may be in direct contact. They are widely used in space heating, refrigeration, air conditioning, power plants, chemical plants, petrochemical plants, petroleum refineries, natural gas processing, and sewage treatment.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$heat-exchanger$glossary$, $glossary$https://coffee-dictionary.com/heat-exchanger/$glossary$),
  ($glossary$Herbal$glossary$, $glossary$Definition and Lexicon Placement “Herbal” serves as a primary descriptor in coffee tasting vocabulary, identifying flavor notes that resemble fresh or dried herbs such as sage, thyme, basil, or oregano. This term occupies a distinct position within established coffee flavor lexicons, including the Specialty Coffee Association’s Flavor Wheel, where it falls under the broader category of plant-like qualities .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$herbal-a-descriptor-in-coffee-tasting$glossary$, $glossary$https://coffee-dictionary.com/herbal-a-descriptor-in-coffee-tasting/$glossary$),
  ($glossary$Hermetic seal$glossary$, $glossary$A hermetic seal has the quality of being airtight. In common usage, the term often implies being impervious to air or gas. When used technically, it is stated in conjunction with a specific test method and conditions of usage.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$hermetic-seal$glossary$, $glossary$https://coffee-dictionary.com/hermetic-seal/$glossary$),
  ($glossary$Hidey$glossary$, $glossary$Hidey is a coffee tasting term describing a specific, often undesirable, flavor note in a brew, reminiscent of animal hides or leather . This descriptor emerged in professional cupping to identify a pungent savory note that differs from standard earthy defects in a roast . It captures an animalistic quality that separates it from other off-flavors in the coffee lexicon.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$hidey-a-coffee-tasting-term$glossary$, $glossary$https://coffee-dictionary.com/hidey-a-coffee-tasting-term/$glossary$),
  ($glossary$High-density lipoprotein$glossary$, $glossary$High-density lipoprotein (HDL) is one of the five main types of lipoproteins that carry fats like cholesterol and triglycerides through the watery environment of the blood. These particles are often listed by size, from the largest to the smallest: chylomicrons, very-low-density lipoprotein (VLDL), intermediate-density lipoprotein (IDL), low-density lipoprotein (LDL) , and finally HDL. In a person with good health, roughly thirty percent of the total blood cholesterol is transported by HDL particles. Standard blood tests measure HDL-C, which refers specifically to the amount of cholesterol found inside these HDL carriers.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$high-density-lipoprotein$glossary$, $glossary$https://coffee-dictionary.com/high-density-lipoprotein/$glossary$),
  ($glossary$Home appliance$glossary$, $glossary$Home appliances are electrical/mechanical machines which accomplish some household functions, such as cooking or cleaning. Home appliances can be classified into: Major appliances, or White goods, Small appliances, or Brown goods Consumer electronics, or Shiny goods. The consumer electronics division is also notable for the maintenance and repair of these kinds of products.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$home-appliance$glossary$, $glossary$https://coffee-dictionary.com/home-appliance/$glossary$),
  ($glossary$Hot Chocolate$glossary$, $glossary$Hot chocolate, traditionally made from melted chocolate or cocoa powder mixed with milk or water, is sweetened and enhanced with vanilla or spices. As a caffeine-free option, it holds a significant place in coffee culture, historically served in European coffeehouses alongside espresso drinks. Today, specialty cafés treat it with the same care as coffee, using high-quality cocoa and refined techniques.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$hot-chocolate$glossary$, $glossary$https://coffee-dictionary.com/hot-chocolate/$glossary$),
  ($glossary$Hot plate$glossary$, $glossary$A hot plate is a small, portable tabletop appliance that has one or more electric heating elements or gas burners. This self-contained unit works on its own but often acts as a substitute for a single burner from a full-sized stove . Its compact and standalone design makes it a highly versatile tool for locations without a full kitchen, including dormitory rooms, office break areas, small apartments, and outdoor spaces. The device offers a direct and adjustable source of heat for various cooking jobs such as boiling water, simmering sauces, or frying foods. Its simplicity and portability have secured its place in both domestic and professional settings where a permanent cooking installation is impractical or unavailable.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$hot-plate$glossary$, $glossary$https://coffee-dictionary.com/hot-plate/$glossary$),
  ($glossary$Hypertension$glossary$, $glossary$Hypertension (HTN or arterial hypertension) is a chronic condition of elevated arterial blood pressure , summarized by systolic pressure—the higher number measuring arterial pressure during heartbeats when the heart muscle contracts—and diastolic pressure—the lower number measuring pressure between beats when the heart is relaxed. This elevation requires the heart to work harder than normal.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$hypertension$glossary$, $glossary$https://coffee-dictionary.com/hypertension/$glossary$),
  ($glossary$Iced Latte$glossary$, $glossary$An iced latte typically refers to a beverage that is prepared with freshly brewed, hot espresso and chilled milk over ice. This drink is very typical in the United States.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$iced-latte$glossary$, $glossary$https://coffee-dictionary.com/iced-latte/$glossary$),
  ($glossary$Iced coffee$glossary$, $glossary$Iced coffee is a cold variant of coffee. In more recent times it has become common for coffee shops to offer ‘iced’ versions of their most popular coffee drinks. The iced latte and iced mocha are the two most common examples of this. A quick way of preparing such drinks is to make a small quantity of strong, hot espresso , dissolving the required sweetener/flavorings in the hot liquid and then pouring this directly into a cup of ice cold milk. This method is common in busier coffee shops. The hot coffee can also be cooled using cold water, ice, cream or ice cream.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$iced-coffee$glossary$, $glossary$https://coffee-dictionary.com/iced-coffee/$glossary$),
  ($glossary$Iced mocha$glossary$, $glossary$The iced mocha is a variant of the iced latte and another beverage that would fall into the bracket of iced coffee .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$iced-mocha$glossary$, $glossary$https://coffee-dictionary.com/iced-mocha/$glossary$),
  ($glossary$Illy$glossary$, $glossary$illycaffè is a brand of coffee produced in Trieste, Italy. illy produces principally one blend in three roast variations: normal, dark roast , and decaffeinated. The blend is packaged as whole beans, pre-ground coffee, E.S.E. pods , or iperEspresso Capsules.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$]::text[], ARRAY[]::text[], $glossary$illy$glossary$, $glossary$https://coffee-dictionary.com/illy/$glossary$),
  ($glossary$Immersion Brewing$glossary$, $glossary$Immersion brewing is any method where coffee grounds are fully submerged in water for the entire brew time, allowing for even extraction and consistent results.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$immersion-brewing$glossary$, $glossary$https://coffee-dictionary.com/immersion-brewing/$glossary$),
  ($glossary$Immersion Cold Brew$glossary$, $glossary$Immersion cold brew is a coffee preparation method where coarsely ground coffee steeps in cold or room-temperature water for 12 to 24 hours before filtration. Unlike drip or flash-chilled methods, immersion brewing achieves full saturation of grounds, allowing a slow, balanced extraction that boosts sweetness while cutting acidity.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee$rel$]::text[], $glossary$immersion-cold-brew$glossary$, $glossary$https://coffee-dictionary.com/immersion-cold-brew/$glossary$),
  ($glossary$Indian Filter Coffee$glossary$, $glossary$Indian Filter Coffee refers to a distinctive coffee beverage characterized by its thick, syrupy consistency and robust flavor profile. The drink is prepared using a traditional two-chamber metal filter device specific to South Indian coffee culture . The coffee consists of pre-ground arabica and/or robusta beans blended with chicory—sometimes in ratios as high as 50:50 . This unique composition gives the beverage its strong, distinctive taste.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$indian-filter-coffee$glossary$, $glossary$https://coffee-dictionary.com/indian-filter-coffee/$glossary$),
  ($glossary$Inka Beverage$glossary$, $glossary$Inka is a Polish roasted grain beverage and brand. Developed in the late 1960s during communist rule, Inka has been produced in Skawina since 1971, a centre of coffee production since the early 20th century. Presently it is manufactured by GRANA Sp. Z O.O. While it was used in part as a coffee substitute to alleviate coffee shortages in the 1970s, Inka remains popular, in part to the fact that it is caffeine-free.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$inka-beverage$glossary$, $glossary$https://coffee-dictionary.com/inka-beverage/$glossary$),
  ($glossary$Instant Taste (Coffee Term)$glossary$, $glossary$Instant taste describes the distinctive sensory profile of instant coffee, characterized by a concentrated flavor that differs from traditionally brewed coffee. The taste results from the extraction process where coffee grounds undergo pressurized water treatment at 175°C (347°F), producing a concentrated brew containing 25% to 60% extracted soluble compounds. This concentrated extraction creates a flavor profile that tends toward intensity rather than complexity . The sweetness component plays a crucial role in instant coffee’s taste profile.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$instant-taste-coffee-term$glossary$, $glossary$https://coffee-dictionary.com/instant-taste-coffee-term/$glossary$),
  ($glossary$Ipoh White Coffee$glossary$, $glossary$Ipoh White Coffee is a distinctive Malaysian coffee beverage that originated in the city of Ipoh, located in the state of Perak . This specialty drink differs from conventional coffee through its unique roasting process , where green coffee beans are roasted at lower temperatures between 325°F and 375°F, creating a lighter-colored bean with reduced bitterness .$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$ipoh-white-coffee$glossary$, $glossary$https://coffee-dictionary.com/ipoh-white-coffee/$glossary$),
  ($glossary$Irish coffee$glossary$, $glossary$Irish coffee is a hot coffee cocktail that combines a strong coffee brew, Irish whiskey, sugar, and a layer of cream on top . This beverage is traditionally served in a clear glass mug, which shows its distinct layered appearance valued in coffee presentation . The standard preparation includes approximately 30ml (1oz) of Irish whiskey, though premium versions might use specific varieties such as Jameson 12-year or Redbreast .$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$irish-coffee$glossary$, $glossary$https://coffee-dictionary.com/irish-coffee/$glossary$),
  ($glossary$James Hoffmann$glossary$, $glossary$James Hoffmann is a British coffee expert, author, and 2007 World Barista Champion whose work has redefined specialty coffee culture. As co-founder of London’s Square Mile Coffee Roasters, he gained global recognition through his YouTube channel and *The World Atlas of Coffee*. This guide translates coffee’s complexities for professionals and enthusiasts alike, blending scientific precision with approachable storytelling.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$james-hoffmann$glossary$, $glossary$https://coffee-dictionary.com/james-hoffmann/$glossary$),
  ($glossary$Joshua Spink$glossary$, $glossary$Joshua Spink is an Irish opera singer and writer. His specialist topics are coffee, food, wellness and culture.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$joshua-spink$glossary$, $glossary$https://coffee-dictionary.com/joshua-spink/$glossary$),
  ($glossary$Jura Elektroapparate$glossary$, $glossary$Jura Elektroapparate AG is a Swiss developer and distributor of home appliances , headquartered in Niederbuchsiten, Canton of Solothurn. The company was founded in 1931 by Leo Henzirohs. Formerly, Jura ran its own factory, but outsourced production to outside companies in the 1990s. Jura is currently best known for its fully automatic espresso machines . This core area originated in the early 1980s and is nowadays a main element of the brand image as well as creating most of its sales. The espresso machines are produced by Eugster/Frismag in Romanshorn, which also makes coffee machines for Siemens, Bosch and AEG.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$jura-elektroapparate$glossary$, $glossary$https://coffee-dictionary.com/jura-elektroapparate/$glossary$),
  ($glossary$Kahweol$glossary$, $glossary$Kahweol is a diterpene molecule found in the beans of Coffea arabica . It is structurally related to cafestol . Recent research suggests that kahweol may have beneficial effects on bone by inhibiting osteoclast differentiation. Another recent study confirmed that kahweol has anti-inflammatory and anti-angiogenic effects, offering a possible mechanism for the association found in epidemiological studies between consumption of unfiltered coffee and decreased risk of cancer .$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$kahweol$glossary$, $glossary$https://coffee-dictionary.com/kahweol/$glossary$),
  ($glossary$Kalita$glossary$, $glossary$Kalita is a Japanese coffee equipment manufacturer known for its distinctive pour-over brewing devices, particularly the Kalita Wave dripper. This flat-bottomed dripper features three small holes that regulate water flow and promote even extraction , contributing to a consistent and balanced brew.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Pour over coffee$rel$]::text[], $glossary$kalita$glossary$, $glossary$https://coffee-dictionary.com/kalita/$glossary$),
  ($glossary$Karsk$glossary$, $glossary$Karsk (from Old Norse karskr , meaning vigorous), also known as kask or kaffekask , refers to a traditional Scandinavian cocktail. It consists of strong, hot black coffee and high-proof neutral spirits, typically moonshine or vodka. This warming drink originates from rural Scandinavia and is a type of utilitarian beverage distinct from cream-topped cocktails like Irish coffee . Karsk is known for its unique preparation method, which involves using a coin to measure the balance between coffee and alcohol.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$karsk$glossary$, $glossary$https://coffee-dictionary.com/karsk/$glossary$),
  ($glossary$Kettle$glossary$, $glossary$A kettle, sometimes called a tea kettle or teakettle, is a type of pot, typically metal, specialized for boiling water over a heat source, with a lid, spout and handle, or a small kitchen appliance of similar shape that functions in a self-contained manner. Kettles can be heated either by placing on a stove, or by their own internal electric heating element in the appliance versions.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$kettle$glossary$, $glossary$https://coffee-dictionary.com/kettle/$glossary$),
  ($glossary$Keurig$glossary$, $glossary$Keurig, is a North American manufacturer of coffee brewers for both home and commercial use. It is a part of Green Mountain Coffee Roasters , Inc. (GMCR). Keurig is based in Massachusetts. Their best selling products are the single serve coffee machine Keurig, and the coffee capsules for the brewer.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$single serve coffee maker$rel$]::text[], $glossary$keurig$glossary$, $glossary$https://coffee-dictionary.com/keurig/$glossary$),
  ($glossary$Kitchen$glossary$, $glossary$A kitchen is a room or part of a room used for cooking and food preparation. In the West, a modern residential kitchen is typically equipped with a stove , a sink with hot and cold running water, a refrigerator and kitchen cabinets arranged according to a modular design. Many households have a microwave oven, a dishwasher and other electric appliances.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$kitchen$glossary$, $glossary$https://coffee-dictionary.com/kitchen/$glossary$),
  ($glossary$KitchenAid$glossary$, $glossary$KitchenAid is an American home appliance brand owned by Whirlpool Corporation. The company was started in 1919 by The Hobart Corporation to produce stand mixers; the “H-5” was the first model introduced. The company faced stiff competition as rivals moved into this emerging market, and introduced its trademarked silhouette in the 1930s with the model “K”, the work of designer Egmont Arens.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$kitchenaid$glossary$, $glossary$https://coffee-dictionary.com/kitchenaid/$glossary$),
  ($glossary$Kopi Tubruk$glossary$, $glossary$Kopi Tubruk (from the Javanese word for ‘collision’) is a traditional Indonesian coffee brewing method where coarsely or medium-ground coffee is steeped directly in hot water without filtration . It is an unfiltered immersion brew, similar in concept to a rustic cowboy coffee . The grounds settle at the bottom of the cup, creating a strong, full-bodied beverage often called ‘mud coffee.’$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Culture$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$kopi-tubruk$glossary$, $glossary$https://coffee-dictionary.com/kopi-tubruk/$glossary$),
  ($glossary$Krups$glossary$, $glossary$Krups is a German kitchen appliance manufacturer, named after its founder Robert Krups. It is often confused with the Krupp conglomerate. The company also produces a large variety of household appliances. Krups competes with De’Longhi, Sunbeam, Braun, Russell Hobbs, Bosch and Black & Decker .$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$krups$glossary$, $glossary$https://coffee-dictionary.com/krups/$glossary$),
  ($glossary$Latte$glossary$, $glossary$A latte, which translates from Italian as “coffee milk,” is a popular coffee drink built on a foundation of espresso and steamed milk . In English, the word is occasionally misspelled as latté or lattè, with the added accent mark considered a hyperforeignism—an attempt to make the word seem more authentically foreign than it is. Interestingly, the term ‘ Café au lait ’ has historically been used for espresso with milk in Northern Europe and Scandinavia. In the United States, however, that same phrase typically refers to a combination of brewed coffee and steamed milk, highlighting a key regional difference in coffee terminology.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$latte$glossary$, $glossary$https://coffee-dictionary.com/latte/$glossary$),
  ($glossary$Latte Art$glossary$, $glossary$Latte art is the technique of pouring steamed milk into espresso to create patterns or designs on the surface of the drink, demonstrating barista skill and milk quality.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Microfoam$rel$]::text[], $glossary$latte-art$glossary$, $glossary$https://coffee-dictionary.com/latte-art/$glossary$),
  ($glossary$Latte macchiato$glossary$, $glossary$Latte Macchiato refers to a hot milk beverage ‘stained’ with espresso, distinguished by its three-layer presentation . Originating in Italy during the 1980s, it emerged as a response to American-style caffè lattes, designed to emphasize the espresso ‘mark’ more prominently .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$latte-macchiato$glossary$, $glossary$https://coffee-dictionary.com/latte-macchiato/$glossary$),
  ($glossary$Lavazza$glossary$, $glossary$Luigi Lavazza S.p.A. is an Italian manufacturer of coffee products. Founded in Turin in 1895 by Luigi Lavazza, it was initially run from a small grocery store at Via San Tommaso 10. The business of Lavazza S.p.A. is currently administered by the third and fourth generation of the Lavazza family.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$]::text[], ARRAY[]::text[], $glossary$lavazza$glossary$, $glossary$https://coffee-dictionary.com/lavazza/$glossary$),
  ($glossary$Lelit$glossary$, $glossary$Lelit, an Italian espresso machine manufacturer founded in 1993 in Casella d’Asolo, specializes in compact yet high-performance home equipment. By incorporating commercial-grade components—PID temperature controllers, stainless steel boilers, and E61 group heads—Lelit achieves professional-level precision in temperature stability and extraction consistency.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$lelit$glossary$, $glossary$https://coffee-dictionary.com/lelit/$glossary$),
  ($glossary$Light Roast$glossary$, $glossary$Light roast coffee is roasted to an internal temperature of 180-205 degrees C, preserving the bean origin flavors with high acidity, light body, and no surface oils.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$coffee roasting$rel$]::text[], $glossary$light-roast$glossary$, $glossary$https://coffee-dictionary.com/light-roast/$glossary$),
  ($glossary$Long black$glossary$, $glossary$A long black is a style of coffee, most commonly found in Australia , New Zealand and Brazil. It is now becoming available in the UK, predominantly in London.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$long-black$glossary$, $glossary$https://coffee-dictionary.com/long-black/$glossary$),
  ($glossary$Low-density lipoprotein$glossary$, $glossary$Low-density lipoprotein (LDL) is one of the five major groups of lipoproteins, which in order of size, largest to smallest, are chylomicrons, VLDL, IDL, LDL, and HDL, that enable transport of multiple different fat molecules, including cholesterol , within the water around cells and within the water-based bloodstream. Studies have shown that higher levels of type-B LDL particles (as opposed to type-A LDL particles) are associated with health problems, including cardiovascular disease.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$low-density-lipoprotein$glossary$, $glossary$https://coffee-dictionary.com/low-density-lipoprotein/$glossary$),
  ($glossary$Lungo$glossary$, $glossary$A lungo is a long espresso shot brewed with double the water of a standard espresso, producing a larger, milder, and slightly more bitter cup.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$lungo$glossary$, $glossary$https://coffee-dictionary.com/lungo/$glossary$),
  ($glossary$Macchiato$glossary$, $glossary$A macchiato is an espresso-based drink made with a single or double shot of espresso, lightly ‘marked’ with steamed milk or foam. Derived from the Italian *caffè macchiato* (‘stained coffee’), its name refers to the espresso’s delicate milk accent. This method softens the espresso’s intensity—mellowing acidity and bitterness—while keeping its bold core, creating a balanced yet potent profile.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$macchiato$glossary$, $glossary$https://coffee-dictionary.com/macchiato/$glossary$),
  ($glossary$Malty (Coffee Term)$glossary$, $glossary$Malty describes a coffee flavor characteristic that evokes the taste and aroma of malted grains, particularly those used in brewing beer or making malted milk products. This tasting note presents as a sweet, grain-forward flavor with subtle nutty undertones and a smooth, rounded mouthfeel. It shows a cereal-like sweetness reminiscent of barley malt, wheat, or oats, creating a comforting and familiar taste profile. Coffee with malty characteristics often has a medium body with low to moderate acidity.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$malty-coffee-term$glossary$, $glossary$https://coffee-dictionary.com/malty-coffee-term/$glossary$),
  ($glossary$Manual Espresso Machine$glossary$, $glossary$A manual espresso machine is a lever-operated device that uses human force to generate the pressure required for espresso extraction, bypassing the need for an electric pump. Originating with the 1948 Gaggia lever machine, it revolutionized espresso-making by introducing high-pressure extraction, which produces the signature crema.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Espresso Machine$rel$]::text[], $glossary$manual-espresso-machine$glossary$, $glossary$https://coffee-dictionary.com/manual-espresso-machine/$glossary$),
  ($glossary$Mark Prince$glossary$, $glossary$Mark Prince is a leading voice in the online coffee and espresso community. He is the founder and webmaster of the influential websites CoffeeGeek and CoffeeKid . His acknowledged expertise and passion for coffee have made him a sought-after source for interviews with various newspapers, magazines, and radio programs.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$mark-prince$glossary$, $glossary$https://coffee-dictionary.com/mark-prince/$glossary$),
  ($glossary$Marocchino$glossary$, $glossary$A Marocchino refers to a classic Italian coffee drink known for its distinct layered presentation. It consists of a shot of espresso , a layer of cocoa powder, and a topping of milk froth . The drink is served in a small, clear glass to show its structure and has a balanced combination of bitter, sweet, and creamy flavors.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$marocchino$glossary$, $glossary$https://coffee-dictionary.com/marocchino/$glossary$),
  ($glossary$Mason Jar$glossary$, $glossary$A Mason jar—a glass jar with a screw-on lid—was originally designed for home canning but has become indispensable in coffee preparation, particularly for cold brew. Its simplicity and affordability shine in this method, where coarsely ground coffee steeps in cold water before filtering. The wide mouth simplifies filling and cleaning, while the airtight seal maintains freshness during extended steeping.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$mason-jar$glossary$, $glossary$https://coffee-dictionary.com/mason-jar/$glossary$),
  ($glossary$Mazagran$glossary$, $glossary$Mazagran is a distinctive, refreshing coffee beverage with origins in Algeria. It consists of strong coffee or espresso mixed with an equal portion of cold water. The drink is often sweetened and is known as a historical precursor to modern iced coffee .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$mazagran$glossary$, $glossary$https://coffee-dictionary.com/mazagran/$glossary$),
  ($glossary$Medicinal (Coffee Term)$glossary$, $glossary$Medicinal (Coffee Term) In coffee terminology, “medicinal” refers to the health-promoting bioactive compounds naturally present in coffee beans . Research indicates that moderate coffee consumption (1-5 cups daily) gives beneficial compounds with potential therapeutic effects . These include caffeine (50-400 mg/day), which at appropriate doses helps various physiological functions without triggering adverse effects like anxiety or sleep disturbances that appear at higher intakes (>500 mg/day) .$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$medicinal-coffee-term$glossary$, $glossary$https://coffee-dictionary.com/medicinal-coffee-term/$glossary$),
  ($glossary$Medium Roast$glossary$, $glossary$Medium roast coffee is roasted between the first and second crack, offering a balance of origin flavors and roast characteristics with moderate acidity and body.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$coffee roasting$rel$]::text[], $glossary$medium-roast$glossary$, $glossary$https://coffee-dictionary.com/medium-roast/$glossary$),
  ($glossary$Medium-dark Roast$glossary$, $glossary$A medium dark roast is a coffee roast level defined by beans that reach a deep brown color with visible surface oil, producing a cup with balanced bittersweet flavors, moderate acidity , and a fuller body .$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$coffee roasting$rel$]::text[], $glossary$medium-dark-roast$glossary$, $glossary$https://coffee-dictionary.com/medium-dark-roast/$glossary$),
  ($glossary$Melitta$glossary$, $glossary$Melitta is a German-based company selling coffee, paper coffee filters , and coffee makers as part of the Melitta Group, which also has Melitta branches in other countries world-wide. The company is headquartered in Minden, North Rhine-Westphalia. It is named after Melitta Bentz (1873–1950) who founded the company after she invented the drip brew paper coffee filter (German patent granted July 8, 1908). Bentz later ran the company as a family business.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$melitta$glossary$, $glossary$https://coffee-dictionary.com/melitta/$glossary$),
  ($glossary$Mellow Coffee Flavor$glossary$, $glossary$Mellow Coffee Flavor A mellow coffee presents a balanced sensory profile characterized by smoothness and subdued acidity. This flavor profile typically develops in medium roasts, where beans reach internal temperatures of 410°F to 430°F, falling between first and second crack . The resulting cup offers gentle, rounded flavor notes without sharp peaks or valleys in taste perception. Mellow coffees have a soft mouthfeel that coats the palate evenly, creating a sensation often described as silky or velvety.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$mellow-coffee-flavor$glossary$, $glossary$https://coffee-dictionary.com/mellow-coffee-flavor/$glossary$),
  ($glossary$Melya$glossary$, $glossary$Melya is a distinctive coffee drink characterized by its simple yet flavorful combination of brewed coffee , honey, and a dusting of cocoa powder . It offers a sweet, rich, and slightly bitter profile, serving as a comforting and dessert-like alternative to traditional black coffee. While its exact origins are debated, its name derives from the French and Spanish word “miel,” meaning honey, highlighting a core ingredient .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$melya$glossary$, $glossary$https://coffee-dictionary.com/melya/$glossary$),
  ($glossary$Microfoam$glossary$, $glossary$Microfoam is a smooth, dense emulsion of steamed milk and tiny air bubbles, formed through precise aeration and texturing with an espresso machine’s steam wand. Its velvety, glossy texture—reminiscent of wet paint—sets it apart from frothier or unevenly steamed milk, a distinction critical for specialty coffee .$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Latte Art$rel$, $rel$Milk Frother$rel$]::text[], $glossary$microfoam$glossary$, $glossary$https://coffee-dictionary.com/microfoam/$glossary$),
  ($glossary$Milk Frother$glossary$, $glossary$A milk frother is a device that aerates milk to create foam or microfoam for lattes, cappuccinos, and other espresso-based milk drinks.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Microfoam$rel$]::text[], $glossary$milk-frother$glossary$, $glossary$https://coffee-dictionary.com/milk-frother/$glossary$),
  ($glossary$Mocha$glossary$, $glossary$The name ‘Mocha’ originates from the port city of Al Mokha in Yemen, a major coffee trading hub from the 15th to 17th centuries. This port was the primary gateway for Arabian coffee to reach Europe, establishing Yemen as one of the earliest commercial coffee exporters.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$mocha$glossary$, $glossary$https://coffee-dictionary.com/mocha/$glossary$),
  ($glossary$Mocha Java$glossary$, $glossary$Mocha Java represents the world’s oldest recorded coffee blend, combining beans from Yemen’s port of Mocha (also spelled Mokha) and the Indonesian island of Java . This classic pairing balances the wild, fruity intensity of Yemeni beans with the earthy, full-bodied character of Javanese coffee. The blend originated in the 15th-16th centuries when ships from the Dutch East India Company transported both varieties to European markets .$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$mocha-java$glossary$, $glossary$https://coffee-dictionary.com/mocha-java/$glossary$),
  ($glossary$Moka Express$glossary$, $glossary$Invented by Alfonso Bialetti in 1933, the Moka Express revolutionized home coffee brewing with its stovetop design, producing concentrated, espresso-like coffee through steam pressure . Its three-chamber system—comprising a bottom chamber for water, a middle basket for grounds, and an upper chamber for the brew—combines simplicity with efficiency.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Moka pot$rel$]::text[], $glossary$moka-express$glossary$, $glossary$https://coffee-dictionary.com/moka-express/$glossary$),
  ($glossary$Moka pot$glossary$, $glossary$A moka pot is a stovetop coffee maker that uses steam pressure to force boiling water through finely ground coffee, producing a strong, espresso-like brew.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Bialetti Moka Express$rel$, $rel$Brikka pot$rel$, $rel$Coffee Brewing Methods$rel$, $rel$Moka Express$rel$]::text[], $glossary$moka-pot$glossary$, $glossary$https://coffee-dictionary.com/moka-pot/$glossary$),
  ($glossary$Mr. Coffee$glossary$, $glossary$Mr. Coffee is a owned by Sunbeam Products, Inc. d/b/a Jarden Consumer Solutions and is a registered product of Newell Brands . The Mr. Coffee brand manufactures automatic-drip kitchen coffee machines as well as other products.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$mr-coffee$glossary$, $glossary$https://coffee-dictionary.com/mr-coffee/$glossary$),
  ($glossary$Mug$glossary$, $glossary$A mug is a sturdily built type of cup often used for drinking hot beverages, such as coffee , tea, or hot chocolate . Mugs often have handles and hold a larger amount of fluid than other types of cup. Usually a mug holds approximately 12 fluid ounces (350 mL) of liquid; double a tea cup. A mug is a less formal style of drink container and is not usually used in formal place settings, where a teacup or coffee cup is preferred.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$mug$glossary$, $glossary$https://coffee-dictionary.com/mug/$glossary$),
  ($glossary$Muscle contraction$glossary$, $glossary$A coffee percolator is a type of pot used to brew coffee . The name stems from the word “percolate” which means to cause (a solvent ) to pass through a permeable substance especially for extracting a soluble constituent. In the case of coffee-brewing the solvent is water, the permeable substance is the coffee grounds , and the soluble constituents are the chemical compounds that give coffee its color, taste , aroma, and stimulating properties.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$muscle-contraction$glossary$, $glossary$https://coffee-dictionary.com/muscle-contraction/$glossary$),
  ($glossary$Myocardial infarction$glossary$, $glossary$Myocardial infarction (MI) or acute myocardial infarction (AMI), commonly known as a heart attack, results from the partial interruption of blood supply to a part of the heart , causing heart cells to die. This is most commonly due to occlusion (blockage) of a coronary artery following the rupture of a vulnerable atherosclerotic plaque, which is an unstable collection of lipids ( cholesterol and fatty acids) and white blood cells in the wall of an artery.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$myocardial-infarction$glossary$, $glossary$https://coffee-dictionary.com/myocardial-infarction/$glossary$),
  ($glossary$National Coffee Association$glossary$, $glossary$The National Coffee Association (NCA) or (National Coffee Association of U.S.A. , Inc. ), is the main market research, consumer information, and lobbying association for the coffee industry in the United States . Surveys produced by the NCA are widely cited in mainstream media. The association has numerous functions and services that include: Market and scientific research Domestic and international government relations, including lobbying Public relations and education.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Culture$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$national-coffee-association$glossary$, $glossary$https://coffee-dictionary.com/national-coffee-association/$glossary$),
  ($glossary$Natural rubber$glossary$, $glossary$Natural rubber , also called India rubber or caoutchouc, as initially produced, consists of suitable polymers of the organic compound isoprene with minor impurities of other organic compounds plus water. Forms of polyisoprene that are useful as natural rubbers are classified as elastomers. Currently the rubber is harvested mainly in the form of the latex from certain trees. The latex is a sticky, milky colloid drawn off by making incisions into the bark and collecting the fluid in vessels.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$natural-rubber$glossary$, $glossary$https://coffee-dictionary.com/natural-rubber/$glossary$),
  ($glossary$Nescafé$glossary$, $glossary$Nescafé is a brand of instant coffee made by Nestlé. It comes in many different product forms. The name is a portmanteau of the words “ Nestlé ” and “café“. Nestlé’s flagship powdered coffee product was introduced in Switzerland on April 1, 1938 after being developed for seven or eight years by Max Morgenthaler.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$]::text[], ARRAY[]::text[], $glossary$nescafe$glossary$, $glossary$https://coffee-dictionary.com/nescafe/$glossary$),
  ($glossary$Nespresso$glossary$, $glossary$Nespresso is the brand name of Nestlé Nespresso S.A. , an operating unit of the Nestlé Group based in Lausanne, Switzerland. Nespresso machines brew espresso from coffee capsules, a type of pre-apportioned single-use container of ground coffee and flavorings.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$single serve coffee maker$rel$]::text[], $glossary$nespresso$glossary$, $glossary$https://coffee-dictionary.com/nespresso/$glossary$),
  ($glossary$Nestlé$glossary$, $glossary$Nestlé S.A. is a Swiss multinational nutritional, snack food, and health-related consumer goods company headquartered in Vevey, Switzerland. It is the largest food company in the world measured by revenues. Nestlé’s products include baby food, bottled water, breakfast cereals, coffee, confectionery, dairy products, ice cream, pet foods and snacks.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$]::text[], ARRAY[]::text[], $glossary$nestle$glossary$, $glossary$https://coffee-dictionary.com/nestle/$glossary$),
  ($glossary$Neutral Flavor$glossary$, $glossary$Neutral flavor serves as the reference point against which coffee professionals evaluate all other taste characteristics. This baseline represents a clean, balanced cup with no dominant flavor notes – neither overly acidic nor bitter, without pronounced sweetness or astringency . Professional tasters use neutral coffee as their calibration standard before evaluating samples with distinct regional or processing characteristics. The neutral cup has subtle grain-like or nutty undertones without sharp edges or overwhelming intensity.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$neutral-flavor-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/neutral-flavor-in-coffee/$glossary$),
  ($glossary$New Orleans$glossary$, $glossary$New Orleans is a major United States port and the largest city and metropolitan area in the state of Louisiana . The population of the city was 343,829 as of the 2010 U.S. Census . The New Orleans metropolitan area (New Orleans– Metairie –Kenner Metropolitan Statistical Area) had a population of 1,167,764 in 2010 and was the 46th largest in the United States. The New Orleans–Metairie–Bogalusa Combined Statistical Area, a larger trading area, had a 2010 population of 1,214,932.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$new-orleans$glossary$, $glossary$https://coffee-dictionary.com/new-orleans/$glossary$),
  ($glossary$Nitro Cold Brew$glossary$, $glossary$Nitro cold brew is cold brew coffee infused with nitrogen gas, served on tap to create a creamy, cascading texture similar to a stout beer.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee$rel$]::text[], $glossary$nitro-cold-brew$glossary$, $glossary$https://coffee-dictionary.com/nitro-cold-brew/$glossary$),
  ($glossary$Normale$glossary$, $glossary$Normale, in the context of espresso, is the standard way of extracting a shot. A single shot normale is obtained by extracting approximately 1 oz of coffee, using 7 grams of ground coffee. A single is often named solo, using the Italian word for it. A normale is the standard espresso concentration , whereas ristretto is a concentrated version, and lungo is the diluted version of it.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$normale$glossary$, $glossary$https://coffee-dictionary.com/normale/$glossary$),
  ($glossary$Nose in Coffee Tasting$glossary$, $glossary$Nose in coffee tasting refers to the systematic evaluation of coffee aroma during the cupping process, representing a critical stage in professional coffee assessment. This evaluation occurs after the initial fragrance assessment of dry grounds. The process begins when boiled water is added to the coffee grounds, which are then allowed to steep for 4 minutes.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$nose-in-coffee-tasting$glossary$, $glossary$https://coffee-dictionary.com/nose-in-coffee-tasting/$glossary$),
  ($glossary$Nutty Flavor in Coffee$glossary$, $glossary$Nutty flavor in coffee represents one of the most recognizable and beloved taste profiles, characterized by distinct notes reminiscent of almonds, hazelnuts, walnuts, or pecans. This sensory experience typically shows as a warm, rich undertone that adds depth and complexity to the cup without overwhelming other flavor components.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$nutty-flavor-in-coffee-an-in-depth-look$glossary$, $glossary$https://coffee-dictionary.com/nutty-flavor-in-coffee-an-in-depth-look/$glossary$),
  ($glossary$OXO Good Grips$glossary$, $glossary$Oxo Good Grips, a product line by OXO, specializes in ergonomic kitchen tools featuring soft, non-slip handles and user-friendly designs. Within the coffee realm, the brand provides precision tools such as gooseneck kettles, scales, and frothing pitchers, essential for achieving consistency in brewing and milk texturing.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$oxo-good-grips$glossary$, $glossary$https://coffee-dictionary.com/oxo-good-grips/$glossary$),
  ($glossary$Oliang$glossary$, $glossary$Oliang ( โอเลี้ยง ), also known as Thai iced coffee , is a popular and distinctive coffee beverage from Thailand. It is characterized by its unique blend of robusta coffee beans roasted together with grains like corn and soybeans, and often spices like cardamom or star anise, resulting in a deeply aromatic, nutty, smoky, and strong brew .$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$oliang$glossary$, $glossary$https://coffee-dictionary.com/oliang/$glossary$),
  ($glossary$Oniony in Coffee$glossary$, $glossary$Oniony in Coffee Definition and Sensory Profile “Oniony” refers to an off-flavor in coffee characterized by distinct allium notes reminiscent of raw or cooked onions. This defect has a sharp, pungent aroma that can range from subtle to overwhelming, often accompanied by a savory, sulfurous taste that lingers unpleasantly on the palate. The onion character typically emerges during cupping evaluation as the coffee cools, becoming more pronounced at lower temperatures (room temperature ) than when hot (~70°C) .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$oniony-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/oniony-in-coffee/$glossary$),
  ($glossary$Osteoporosis$glossary$, $glossary$Osteoporosis is a skeletal disease characterized by reduced bone mineral density (BMD) and deterioration of bone microarchitecture, including trabecular bone loss. This leads to compromised bone tensile strength, mineralization, and repair processes due to reduced collagen type I and an altered ratio of non-collagenous proteins to collagen. The consequence is an increased risk of fracture from minor impacts or falls.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$osteoporosis$glossary$, $glossary$https://coffee-dictionary.com/osteoporosis/$glossary$),
  ($glossary$Over Pressure Valve$glossary$, $glossary$An over pressure valve (OPV) is a one-way vent installed in coffee packaging to release carbon dioxide emitted by freshly roasted beans while blocking oxygen ingress. As coffee degasses post-roast, CO₂ buildup can inflate or rupture bags without a controlled escape. The OPV ensures package integrity by allowing gas to exit while maintaining a sealed environment.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$over-pressure-valve$glossary$, $glossary$https://coffee-dictionary.com/over-pressure-valve/$glossary$),
  ($glossary$Oxidation$glossary$, $glossary$Oxidation is the chemical reaction between oxygen and the volatile compounds in roasted coffee, altering its flavor and aroma over time. This process begins immediately after roasting as the beans release carbon dioxide and interact with air, breaking down the delicate oils and organic compounds responsible for coffee’s complex taste.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$oxidation$glossary$, $glossary$https://coffee-dictionary.com/oxidation/$glossary$),
  ($glossary$PID controller$glossary$, $glossary$In the coffee maker industry, a PID controller improves brewing precision by keeping the water temperature within a tight, desired range. This is especially critical for espresso, where even a few degrees can change a shot from perfectly balanced to unpleasantly sour or bitter . By replacing older, less responsive thermostats, the PID brings a level of temperature control once found only in professional machines to a wider market, directly impacting the quality and consistency of the final cup.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$pid-controller$glossary$, $glossary$https://coffee-dictionary.com/pid-controller/$glossary$),
  ($glossary$Panarello Steam Wand$glossary$, $glossary$A Panarello steam wand is a frothing attachment for home espresso machines, featuring a plastic sleeve that fits over a standard steam wand. Its built-in air-intake hole automatically aerates milk, simplifying microfoam creation for beginners. Unlike traditional steam wands, it mechanically introduces air, producing consistently thick foam with minimal skill.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Steam Wand$rel$]::text[], $glossary$panarello-steam-wand$glossary$, $glossary$https://coffee-dictionary.com/panarello-steam-wand/$glossary$),
  ($glossary$Paper Filters$glossary$, $glossary$Paper filters are thin, disposable sheets of porous paper designed to hold ground coffee while allowing water to pass through. Patented by Melitta Bentz in 1908, they are essential for pour-over drippers and automatic coffee makers. By trapping fine particles and oils, they produce a clean, sediment-free cup with bright clarity, enhancing delicate flavors in light to medium roasts.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Pour over coffee$rel$]::text[], $glossary$paper-filters$glossary$, $glossary$https://coffee-dictionary.com/paper-filters/$glossary$),
  ($glossary$Papery Flavor in Coffee$glossary$, $glossary$Papery flavor represents a negative taste descriptor for coffee, characterized by a dry, thin, and flat taste reminiscent of wet paper or cardboard . This unwanted sensory profile creates an unpleasant drinking experience that masks the coffee’s intended flavor characteristics. Coffee professionals categorize papery flavor as a type of ‘ taint ‘ or ‘off-flavor’ related to staleness and oxidation , rather than a roast defect or inherent bean characteristic .$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Flavors & Cupping$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$papery-flavor-in-coffee-an-unwanted-taste-profile$glossary$, $glossary$https://coffee-dictionary.com/papery-flavor-in-coffee-an-unwanted-taste-profile/$glossary$),
  ($glossary$Past Crop$glossary$, $glossary$Past crop refers to coffee beans from a harvest that is more than 12 months past its harvest date, having undergone significant physical and chemical changes due to prolonged storage.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$past-crop-the-impact-of-aging-on-coffee$glossary$, $glossary$https://coffee-dictionary.com/past-crop-the-impact-of-aging-on-coffee/$glossary$),
  ($glossary$Peaberry Coffee$glossary$, $glossary$Peaberry Coffee was a coffee shop chain that was started in Denver , Colorado in 1990 by Bill Tointon. The store’s concept was founded on serving a variety of coffee from all over the world and roasting it in Denver. It was categorized in a menu format called the “Peaberry Profile System”. The system offered four selections of coffee roasting styles, Light & Mild, Rich & Creamy, Extravagant & Exotic and Dark & Intense.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Culture$cat$]::text[], ARRAY[$rel$coffee beans$rel$]::text[], $glossary$peaberry-coffee-2$glossary$, $glossary$https://coffee-dictionary.com/peaberry-coffee-2/$glossary$),
  ($glossary$Peasy$glossary$, $glossary$Peasy refers to a specific off-flavor in coffee characterized by distinct vegetal notes reminiscent of raw green peas or bell peppers . This undesirable taste attribute typically manifests when coffee has been under-roasted or when beans have not fully developed during the roasting process before reaching pyrolysis at approximately 465°F (240°C) . In sensory evaluation, peasy notes present a sharp, somewhat astringent mouthfeel accompanied by a lingering aftertaste that lacks sweetness.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$peasy-an-unpleasant-taste-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/peasy-an-unpleasant-taste-in-coffee/$glossary$),
  ($glossary$Pero$glossary$, $glossary$Pero is a brand of caffeine-free roasted grain beverages. It is historically sold under names such as Pero. Some consider it a coffee substitute . It is manufactured by Nestlé and was first introduced in West Germany in 1954.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$caro-beverage$glossary$, $glossary$https://coffee-dictionary.com/caro-beverage/$glossary$),
  ($glossary$Philips$glossary$, $glossary$Koninklijke Philips Electronics N.V. (Royal Philips Electronics, commonly known as Philips) is a Dutch multinational electronics company headquartered in Amsterdam. It was founded in Eindhoven in 1891 by Gerard Philips and his father Frederik. It is one of the largest electronics companies in the world and employs around 122,000 people across more than 60 countries.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$philips$glossary$, $glossary$https://coffee-dictionary.com/philips/$glossary$),
  ($glossary$Plastic$glossary$, $glossary$Generally, plastic is best avoided in coffee making equipment, particularly for components that touch hot water. While BPA is widely recognized as a health concern when consumed in significant amounts, other chemical compounds used in plastic production can present greater risks, though they are less familiar to the public. Heat can accelerate the transfer of these substances from the plastic into the beverage, a process known as leaching. For this reason, materials like stainless steel, glass, or certified ceramics are often recommended for hot brewing stages to ensure purity and safety.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$plastic$glossary$, $glossary$https://coffee-dictionary.com/plastic/$glossary$),
  ($glossary$Plunger$glossary$, $glossary$A plunger, or French press, is a manual brewing device featuring a cylindrical carafe and a plunger equipped with a metal mesh filter. Coffee grounds steep in hot water, and the plunger separates them to produce a full-bodied brew. This immersion method extracts rich flavors and retains natural oils, unlike paper-filtered methods, through direct contact between water and coffee.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$plunger$glossary$, $glossary$https://coffee-dictionary.com/plunger/$glossary$),
  ($glossary$Pod Coffee Machine$glossary$, $glossary$A pod coffee machine brews single servings using pre-portioned, sealed capsules of ground coffee, delivering speed and consistency in every cup. Pioneered in the 1980s by brands like Nespresso and Keurig, these systems transformed home brewing by replacing manual measurements with unmatched convenience. The airtight pods keep coffee fresh while ensuring uniform extraction, though some purists critique the lack of customization.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$ESE pods$rel$]::text[], $glossary$pod-coffee-machine$glossary$, $glossary$https://coffee-dictionary.com/pod-coffee-machine/$glossary$),
  ($glossary$Polycarbonate$glossary$, $glossary$Polycarbonate is a high-performance thermoplastic polymer known for its strength, clarity, and heat resistance Wikipedia . In coffee gear, it is valued for its thermal insulation, which is known for trapping heat up to 60% better than glass Acme Plastics . Its softening temperature can range from 150–160°C, while its glass transition temperature is approximately 145–150°C, ensuring durability and clarity at typical coffee-serving temperatures Merriam-Webster . Polycarbonate’s lightweight and impact-resistant properties make it ideal for travel mugs, French presses, and other coffee accessories. Its transparency is similar to glass, while its resistance to thermal stress plays a role in preventing cracks under rapid temperature changes, making it a reliable choice for both hot and cold beverages.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$polycarbonate$glossary$, $glossary$https://coffee-dictionary.com/polycarbonate/$glossary$),
  ($glossary$Porcelain$glossary$, $glossary$Porcelain is a preferred material for many coffee-making items, such as mugs , cups, drippers, kettles, and pots. Its widespread use comes from its unique qualities, which result from a special recipe and a precise making process. Although it is part of the larger ceramic family, porcelain is often seen as a premium choice. It can replace other ceramics for numerous tasks because it is more durable and has a finer, more elegant look.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$porcelain$glossary$, $glossary$https://coffee-dictionary.com/porcelain/$glossary$),
  ($glossary$Postum$glossary$, $glossary$Postum is a powdered roasted grain beverage often used as a coffee substitute . The caffeine-free beverage was created by Post Cereal Company founder C. W. Post in 1895 and marketed as a healthful alternative to coffee. (The Postum Cereal Company eventually became General Foods, which was bought by Kraft Foods. ) Post was a student of John Harvey Kellogg, who believed caffeine to be unhealthy. The “instant” drink mix version was developed in 1912, replacing the original brewed beverage.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$postum$glossary$, $glossary$https://coffee-dictionary.com/postum/$glossary$),
  ($glossary$Pour over coffee$glossary$, $glossary$Pour over coffee is a manual brewing method where hot water is poured over coffee grounds in a filter, allowing the brewed coffee to drip into a vessel below. The technique uses a controlled, circular pouring motion to ensure even extraction of flavors. It uses a grind size ranging from medium to fine, which is finer than French press but coarser than espresso, influencing extraction rate and flow.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$Chemex Coffeemaker$rel$, $rel$Coffee Brewing Methods$rel$, $rel$Hario V60$rel$, $rel$Kalita$rel$, $rel$Paper Filters$rel$]::text[], $glossary$pour-over-coffee$glossary$, $glossary$https://coffee-dictionary.com/pour-over-coffee/$glossary$),
  ($glossary$Pre-infusion$glossary$, $glossary$Pre-infusion is the initial phase of espresso extraction where water is gently introduced to the coffee puck at low pressure (typically 1-3 bars) before full brewing pressure is applied. This technique, rooted in traditional lever espresso machines, serves two critical functions: it evenly hydrates the coffee grounds, allowing them to expand and release trapped gases, while simultaneously preventing channeling by eliminating dry pockets.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$pre-infusion$glossary$, $glossary$https://coffee-dictionary.com/pre-infusion/$glossary$),
  ($glossary$Pressure$glossary$, $glossary$Pressure is the ratio of force to the area over which that force is distributed. Pressure is force per unit area applied in a direction perpendicular to the surface of an object. Gauge pressure (also spelled gage pressure) is the pressure relative to the local atmospheric or ambient pressure. While pressure may be measured in any unit of force divided by any unit of area, the SI unit of pressure is called the pascal (Pa) after the seventeenth-century philosopher and scientist Blaise Pascal.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Bar (unit)$rel$]::text[], $glossary$pressure$glossary$, $glossary$https://coffee-dictionary.com/pressure/$glossary$),
  ($glossary$Pressure Profiling$glossary$, $glossary$Pressure profiling involves the controlled variation of water pressure during espresso extraction, adjusted in real time by the barista or programmed into an espresso machine. Unlike traditional espresso brewing, which has a steady pressure of around 9 bars, this technique enables precise manipulation of the extraction process, influencing variables like flow rate and contact time.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$pressure-profiling$glossary$, $glossary$https://coffee-dictionary.com/pressure-profiling/$glossary$),
  ($glossary$Pressure gauge$glossary$, $glossary$A pressure gauge is an instrument on an espresso machine that measures the water pressure applied to the coffee puck during extraction, typically displayed in bars or PSI (pounds per square inch). It ensures consistent espresso quality by monitoring the ideal 9-bar range, the standard for optimal extraction, preventing under-extraction or over-extraction.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Bar (unit)$rel$]::text[], $glossary$pressure-gauge$glossary$, $glossary$https://coffee-dictionary.com/pressure-gauge/$glossary$),
  ($glossary$Pressurized Basket$glossary$, $glossary$A pressurized basket is a specialized portafilter basket designed to create artificial pressure during espresso extraction through a single, restricted exit hole. Unlike traditional baskets, it works with inconsistent grind size or uneven tamping by forcing water through this narrow opening, producing a crema-like foam. This adaptable design suits entry-level machines and beginners but limits extraction control, yielding less nuanced flavors than non-pressurized alternatives.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$pressurized-basket$glossary$, $glossary$https://coffee-dictionary.com/pressurized-basket/$glossary$),
  ($glossary$Primary Tastes in Coffee$glossary$, $glossary$Coffee perception centers around five primary taste sensations detected by taste buds on the tongue and palate. Bitterness , the most prominent taste in coffee, results from compounds like caffeine and chlorogenic acids, with intensity varying based on roast level . Sweetness manifests as pleasant, sugar-like notes often found in properly extracted coffees. Sourness ( acidity ) contributes brightness and vibrancy, ranging from crisp citrus to softer malic acid notes.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$primary-tastes-in-coffee-a-sensory-exploration$glossary$, $glossary$https://coffee-dictionary.com/primary-tastes-in-coffee-a-sensory-exploration/$glossary$),
  ($glossary$Puckpuck$glossary$, $glossary$Puckpuck is a specialized cold drip brewing attachment that converts an AeroPress into a slow-drip cold brew device. It consists of a drip regulator and a stand, enabling precise control over water flow for consistent extraction. By adjusting the drip rate, users can produce a clean, concentrated cold brew with balanced acidity and nuanced flavors, typically over several hours. The attachment’s compact design leverages the AeroPress’s portability, making it a practical option for home brewers seeking café-quality cold brew without bulky equipment. Cold drip brewing minimizes bitterness and astringency by avoiding prolonged immersion, resulting in a smoother, more aromatic cup. The Puckpuck’s affordability and simplicity have made it popular among coffee enthusiasts exploring alternative cold brew methods beyond traditional immersion or toddy systems.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee Maker$rel$]::text[], $glossary$puckpuck$glossary$, $glossary$https://coffee-dictionary.com/puckpuck/$glossary$),
  ($glossary$Quakery in Coffee$glossary$, $glossary$Quakers are defective coffee beans that create distinct negative sensory characteristics when present in sufficient quantities within a coffee blend. These underdeveloped beans appear lighter in color compared to properly developed coffee beans , often displaying a pale, whitish, or lighter brown appearance that makes them identifiable during visual inspection. The flavor impact of quakers has harsh , astringent, and unpleasantly bitter notes that can overpower the desired flavor characteristics of quality coffee.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$quakery-in-coffee-a-flavor-profile$glossary$, $glossary$https://coffee-dictionary.com/quakery-in-coffee-a-flavor-profile/$glossary$),
  ($glossary$Rancid Flavor in Coffee$glossary$, $glossary$Rancid Flavor in Coffee: Definition and Sensory Profile Rancid flavor is a distinct off-note in coffee characterized by unpleasant, fatty, sour qualities reminiscent of spoiled butter or oxidized oils. In sensory evaluation, rancid notes present as a combination of stale, cardboard-like aromas with sour, pungent undertones. The flavor typically intensifies over time as coffee ages, particularly when stored improperly. Research comparing Arabica and Robusta varieties found that both develop rancid characteristics during storage, though at different rates .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$rancid-flavor-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/rancid-flavor-in-coffee/$glossary$),
  ($glossary$Rancilio$glossary$, $glossary$Rancilio is an espresso machine manufacturer, founded in 1927 by Roberto Rancilio in Parabiago, Milan, Italy. Rancilio would become best known for its innovative distribution networks, effective use of industrial design and reputable reliability. Rancilio’s earliest well-known machine was ‘La Regina’ – a vertical boiler machine, similar to the original Bezzera and Victoria Arduino devices in function and gilded ‘Belle Epoque’ styling.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$rancilio$glossary$, $glossary$https://coffee-dictionary.com/rancilio/$glossary$),
  ($glossary$Rancilio Silvia$glossary$, $glossary$The Rancilio Silvia, introduced in 1997 by Italian manufacturer Rancilio, is a semi-automatic espresso machine designed for home use. Featuring commercial-grade components like a brass boiler and sturdy portafilter, it produces café-quality espresso when paired with proper technique and a high-quality grinder. Its durable construction and minimalist design appeal to espresso enthusiasts seeking skill development.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$rancilio-silvia$glossary$, $glossary$https://coffee-dictionary.com/rancilio-silvia/$glossary$),
  ($glossary$Ready-to-drink Coffee$glossary$, $glossary$Ready To Drink Coffee (RTD) refers to pre-brewed, packaged coffee beverages made for immediate consumption without extra preparation. These products include cold brews, lattes, nitro coffees, and espresso shots, usually sold in cans, bottles, or cartons. RTD coffee gained popularity in Japan during the 1960s with canned coffee vending machines, later spreading globally as a convenient alternative to freshly brewed coffee. Its appeal lies in portability, consistency, and shelf stability, catering to busy consumers who prioritize speed without compromising quality.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$ready-to-drink-coffee$glossary$, $glossary$https://coffee-dictionary.com/ready-to-drink-coffee/$glossary$),
  ($glossary$Red eye$glossary$, $glossary$A Red Eye is a coffee beverage that combines drip coffee with a shot of espresso. The standard preparation involves brewing an 8 oz (237 ml) cup of drip coffee using gravity filtration , then adding a 1 oz (30 ml) espresso shot produced under high pressure . This combination gives a significant caffeine boost, typically containing between 160-200 mg of caffeine, though exact amounts vary based on brew strength and shot size .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$red-eye$glossary$, $glossary$https://coffee-dictionary.com/red-eye/$glossary$),
  ($glossary$Review$glossary$, $glossary$A review is an evaluation of a publication, product, service, or company such as a movie, video game, musical composition (music review of a composition or recording), book; a piece of hardware like a car, home appliance , or computer; or an event or performance, such as a live music concert, play, musical theater show, or dance show. In addition to a critical evaluation, the review’s author may assign the work a rating to indicate its relative merit.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$review$glossary$, $glossary$https://coffee-dictionary.com/review/$glossary$),
  ($glossary$Ristretto$glossary$, $glossary$A ristretto is a short, restricted espresso shot brewed with the same amount of coffee but half the water, producing a sweeter, more concentrated, and less bitter result.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$ristretto$glossary$, $glossary$https://coffee-dictionary.com/ristretto/$glossary$),
  ($glossary$Robusta coffee$glossary$, $glossary$Robusta coffee, also known as Coffea canephora or Coffea robusta, is a variety of coffee plant, with its origins in central and western sub-Saharan Africa. It is a species of flowering plant in the Rubiaceae family. Though widely known as Coffea robusta, the plant is scientifically identified as Coffea canephora, which has two main varieties – Robusta and Nganda.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffea Arabica$rel$]::text[], $glossary$robusta-coffee$glossary$, $glossary$https://coffee-dictionary.com/robusta-coffee/$glossary$),
  ($glossary$Rubbery Flavor in Coffee$glossary$, $glossary$Rubbery Flavor in Coffee: Definition and Sensory Profile Rubbery flavor is an undesirable taste characteristic in coffee that resembles burnt rubber or synthetic materials . This off-flavor indicates quality issues or processing problems in the coffee supply chain. When present, the rubbery notes create an unpleasant sensory experience that masks the coffee’s intended flavor profile.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$rubbery-flavor-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/rubbery-flavor-in-coffee/$glossary$),
  ($glossary$SCAA$glossary$, $glossary$The Specialty Coffee Association of America (SCAA), founded in 1982, is a non-profit trade organization for the specialty coffee industry. With members located in more than 40 countries, SCAA represents every segment of the specialty coffee industry, including producers, coffee roasters , importers/exporters, retailers,coffee brewing equipment manufacturers, baristas and other industry professionals.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$scaa$glossary$, $glossary$https://coffee-dictionary.com/scaa/$glossary$),
  ($glossary$Saeco$glossary$, $glossary$Saeco International Group S.p.A., or Saeco for short, is an Italian manufacturer of manual, super-automatic and capsule based espresso machines as well other electrical goods, with headquarters and factories in Gaggio Montano, located near Bologna.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$saeco$glossary$, $glossary$https://coffee-dictionary.com/saeco/$glossary$),
  ($glossary$Scorched Coffee$glossary$, $glossary$Scorched coffee represents one of the most recognizable roasting defects, occurring when excessive heat application damages coffee beans during the roasting process. This defect shows when roasters apply too much heat quickly, particularly during the early stages, causing the bean’s exterior to burn while the interior remains underdeveloped . The resulting coffee has characteristic burnt, acrid flavors that overpower the bean’s natural characteristics. The phenomenon differs from intentionally dark roasts through its uneven development pattern.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$scorched-coffee-an-exploration-of-over-roasting$glossary$, $glossary$https://coffee-dictionary.com/scorched-coffee-an-exploration-of-over-roasting/$glossary$),
  ($glossary$Screen filter$glossary$, $glossary$A screen filter is a type of filter using a rigid or flexible screen to separate sand and other fine particles out of water. Typical screen materials include stainless steel , polypropylene, nylon and polyester.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$screen-filter$glossary$, $glossary$https://coffee-dictionary.com/screen-filter/$glossary$),
  ($glossary$Semi Automatic Espresso Machine$glossary$, $glossary$Semi-automatic espresso machines are devices that partially automate the espresso brewing process . Compared with super automatic machines , they require more work and know-how from the barista. They are the choice of coffee shops and espresso aficionados. They offer excellent reliability and control over the brewing process.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Espresso Machine$rel$]::text[], $glossary$semi-automatic-espresso-machine$glossary$, $glossary$https://coffee-dictionary.com/semi-automatic-espresso-machine/$glossary$),
  ($glossary$Senseo$glossary$, $glossary$Senseo is a registered trademark for a coffee brewing system from Dutch companies Philips and Douwe Egberts. The three main characteristics of the system are its coffee pods (called pads in some countries), its design and its easy to use system.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$single serve coffee maker$rel$]::text[], $glossary$senseo$glossary$, $glossary$https://coffee-dictionary.com/senseo/$glossary$),
  ($glossary$Single Espresso Shot$glossary$, $glossary$Single in the context of espresso brewing , refers to a single shot of espresso , pulled from approximately 7-8 grams of coffee grounds. Also called a solo, by the Italian name, a single shot normale espresso holds about 1 oz. of brewed coffee, and it is prepared using a single filter basket .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$single$glossary$, $glossary$https://coffee-dictionary.com/single/$glossary$),
  ($glossary$Single Origin$glossary$, $glossary$Single origin coffee comes from one specific geographic location (country, region, or farm), allowing the unique terroir and flavor characteristics of that place to be expressed.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$coffee beans$rel$]::text[], $glossary$single-origin$glossary$, $glossary$https://coffee-dictionary.com/single-origin/$glossary$),
  ($glossary$Single-origin coffee$glossary$, $glossary$Single-origin coffee is coffee grown within a single known geographical origin. Sometimes this is a single farm or a specific collection of beans from a single country. The name of the coffee is then usually the place it was grown to whatever degree available. Single-origins are viewed by some as a way to get a specific taste, and some independent coffee shops have found that this gives them a way to add value over large chains.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$single-origin-coffee$glossary$, $glossary$https://coffee-dictionary.com/single-origin-coffee/$glossary$),
  ($glossary$Siphon Brewer$glossary$, $glossary$A siphon brewer is a vacuum-style coffee maker that uses vapor pressure and gravity to cycle water between two chambers—first steeping coffee grounds, then filtering the brewed coffee downward. Developed in the 1830s, this hybrid immersion-and-filtration method achieves precise temperature control , yielding a sediment-free cup with exceptional clarity and aroma.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee Brewing Methods$rel$]::text[], $glossary$siphon-brewer$glossary$, $glossary$https://coffee-dictionary.com/siphon-brewer/$glossary$),
  ($glossary$Small appliance$glossary$, $glossary$Small appliances, also called brown goods (because the color of the wooden and bakelite cases once used) are portable or semi-portable machines, generally used on table-tops, counter-tops, or other platforms, to accomplish a household task. Examples of brown goods are: television and wireless sets; microwave ovens; coffee makers; and personal computers.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$small-appliance$glossary$, $glossary$https://coffee-dictionary.com/small-appliance/$glossary$),
  ($glossary$Smoothness in Coffee$glossary$, $glossary$Smoothness in coffee represents a harmonious sensory experience characterized by a low-acidity, mellow flavor profile that lacks harshness or bitterness . This quality shows a pleasant mouthfeel—neither thin nor watery—that glides across the palate without astringency . The perception of smoothness emerges when all flavor components integrate seamlessly, with no single element creating jarring sensations. Achieving this balance requires proper brewing conditions, particularly water quality and temperature. Filtered water heated to 195–205°F (90–96°C) helps produce consistently smooth results.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$smoothness-in-coffee-a-desirable-quality$glossary$, $glossary$https://coffee-dictionary.com/smoothness-in-coffee-a-desirable-quality/$glossary$),
  ($glossary$Solvent$glossary$, $glossary$SOLVENT In coffee chemistry, a solvent is a substance that dissolves other materials (solutes) during brewing. Water serves as the primary solvent in coffee preparation , extracting hundreds of compounds that contribute to flavor, aroma, and mouthfeel . The solvent’s effectiveness depends on temperature , contact time , and pressure. In decaffeination processes, various solvents play crucial roles: water alone (Swiss Water Process), supercritical carbon dioxide, ethyl acetate, or methylene chloride. .$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$solvent$glossary$, $glossary$https://coffee-dictionary.com/solvent/$glossary$),
  ($glossary$Sourness in Coffee$glossary$, $glossary$Sourness in coffee refers to a bright, sharp, tangy, or tart taste sensation, primarily perceived on the sides of the tongue, and is a fundamental taste attribute distinct from bitterness. This characteristic is central in coffee evaluation. When balanced and pleasant, it is described as “ acidity ” or “ brightness ,” which plays a role in a coffee’s complexity and liveliness.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$sourness-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/sourness-in-coffee/$glossary$),
  ($glossary$South America$glossary$, $glossary$South America, earlier known simply as America (1507–1538), is a continent located in the Western Hemisphere, mostly in the Southern Hemisphere, with a relatively small portion in the Northern Hemisphere. It is also considered a subcontinent of the Americas. It is bordered on the west by the Pacific Ocean and on the north and east by the Atlantic Ocean; North America and the Caribbean Sea lie to the northwest.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$south-america$glossary$, $glossary$https://coffee-dictionary.com/south-america/$glossary$),
  ($glossary$Specialty coffee$glossary$, $glossary$Specialty coffee refers to coffee that scores 80 or above on the SCA 100-point scale, representing the highest quality tier with traceable origins and exceptional flavor.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$specialty-coffee$glossary$, $glossary$https://coffee-dictionary.com/specialty-coffee/$glossary$),
  ($glossary$Spicy Notes in Coffee$glossary$, $glossary$Spicy notes in coffee represent a diverse category of aromatic and flavor characteristics that add complexity to the cup. On the Specialty Coffee Association ( Specialty Coffee Association (SCA)) Flavor Wheel, spice descriptors appear in multiple sections, including the brown spice family (cinnamon, clove, nutmeg) and pungent spices (black pepper, anise) .$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$spicy-notes-in-coffee-an-overview$glossary$, $glossary$https://coffee-dictionary.com/spicy-notes-in-coffee-an-overview/$glossary$),
  ($glossary$Stainless steel$glossary$, $glossary$In metallurgy, stainless steel , also known as inox steel or inox from French “inoxydable”, is a steel alloy with a minimum of 10.5% to 11% chromium content by mass. Stainless steel does not readily corrode, rust or stain with water as ordinary steel does, but despite the name it is not fully stain-proof, most notably under low oxygen, high salinity, or poor circulation environments.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$stainless-steel$glossary$, $glossary$https://coffee-dictionary.com/stainless-steel/$glossary$),
  ($glossary$Starbucks$glossary$, $glossary$Starbucks Corporation is an American global coffee company and coffee house chain based in Seattle, Washington. Starbucks is the largest coffeehouse company in the world, with 20,891 stores in 62 countries, including 13,279 in the United States, 1,324 in Canada, 989 in Japan, 851 in China, 806 in the United Kingdom, 556 in South Korea, 377 in Mexico, 291 in Taiwan, 206 in the Philippines, 171 in Thailand and 10 in India.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$]::text[], ARRAY[]::text[], $glossary$starbucks$glossary$, $glossary$https://coffee-dictionary.com/starbucks/$glossary$),
  ($glossary$Steam$glossary$, $glossary$Although steam is generally too hot for brewing coffee, the power of steam is used in certain coffee brewing methods to create pressure . Pressure, in turn, improves the extraction .$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$steam$glossary$, $glossary$https://coffee-dictionary.com/steam/$glossary$),
  ($glossary$Steam Wand$glossary$, $glossary$A steam wand is a metal tube on an espresso machine that injects steam into milk to heat and froth it for lattes, cappuccinos, and other milk-based drinks.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Panarello Steam Wand$rel$, $rel$Steamed Milk$rel$]::text[], $glossary$steam-wand$glossary$, $glossary$https://coffee-dictionary.com/steam-wand/$glossary$),
  ($glossary$Steamed Milk$glossary$, $glossary$Steamed milk—heated and aerated by an espresso machine ‘s steam wand —has a velvety microfoam with subtle sweetness. The steam heats the milk while forming tiny air bubbles, yielding a smooth texture. Essential for espresso drinks like lattes and cappuccinos, steamed milk softens the espresso’s intensity while adding body and richness. Maintaining the ideal temperature range (140–160°F) preserves milk’s natural sugars without scalding, enhancing specialty coffee . For baristas, mastering this technique is critical—it uses the foundation of crafting balanced coffee drinks.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Bicerin$rel$, $rel$Breve$rel$, $rel$Caffè Latte$rel$, $rel$Cappuccino$rel$, $rel$Cortadito$rel$, $rel$Cortado$rel$, $rel$Espressino$rel$, $rel$Espresso Macchiato$rel$, $rel$Flat white$rel$, $rel$Galão$rel$, $rel$Latte$rel$, $rel$Latte macchiato$rel$, $rel$Macchiato$rel$, $rel$Marocchino$rel$, $rel$Melya$rel$, $rel$Steam Wand$rel$]::text[], $glossary$steamed-milk$glossary$, $glossary$https://coffee-dictionary.com/steamed-milk/$glossary$),
  ($glossary$Steampunk coffeemaker$glossary$, $glossary$A Steampunk Coffeemaker is a commercial single-cup brewer that harnesses halogen heating, vacuum pressure, and digital precision to recreate siphon-style extraction. Developed by Alpha Dominche in the early 2010s, this innovative system enables baristas to fine-tune water temperature and agitation with surgical accuracy, yielding a remarkably clean and nuanced cup.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$steampunk-coffeemaker$glossary$, $glossary$https://coffee-dictionary.com/steampunk-coffeemaker/$glossary$),
  ($glossary$Steeping Time$glossary$, $glossary$Steeping time—the period coffee grounds soak in water during immersion brewing —is a pivotal variable controlling flavor extraction. It directly governs how much oils, soluble compounds, and aromatic elements dissolve, shaping the brew’s taste, strength, and mouthfeel. Extended steeping increases extraction for bolder intensity, while shorter durations highlight brighter, nuanced flavors.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$steeping-time$glossary$, $glossary$https://coffee-dictionary.com/steeping-time/$glossary$),
  ($glossary$Stomach$glossary$, $glossary$The stomach is a muscular, hollow, dilated part of the digestion system which functions as an important organ of the digestive tract in some animals, including vertebrates, echinoderms, insects (mid-gut), and molluscs. It is involved in the second phase of digestion, following mastication (chewing). The stomach is located between the esophagus and the small intestine.$glossary$, $glossary$Coffee & Health$glossary$, ARRAY[$cat$Coffee & Health$cat$]::text[], ARRAY[]::text[], $glossary$stomach$glossary$, $glossary$https://coffee-dictionary.com/stomach/$glossary$),
  ($glossary$Stove$glossary$, $glossary$An electric stove or electric range is a stove that converts electrical energy into heat to cook and bake. Stoves are used for coffee preparation in order to heat up water. There are many manual brewing methods that require hot water, but they don’t involve an automated way to do it.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$stove$glossary$, $glossary$https://coffee-dictionary.com/stove/$glossary$),
  ($glossary$Super Automatic Espresso Machine$glossary$, $glossary$A super-automatic espresso machine performs all or almost all of the coffee brewing automatically. A super automatic espresso machine will automate the following operations that are typically performed manually by the barista:$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Espresso Machine$rel$]::text[], $glossary$super-automatic$glossary$, $glossary$https://coffee-dictionary.com/super-automatic/$glossary$),
  ($glossary$Surface area$glossary$, $glossary$Surface area is the measurement of the total area (faces or curved surface) of a solid figure.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$surface-area$glossary$, $glossary$https://coffee-dictionary.com/surface-area/$glossary$),
  ($glossary$Taint$glossary$, $glossary$Taint (pronounced /teɪnt/) is a specific quality defect in coffee, defined as a noticeable but not overwhelming undesirable off- flavor or aroma that falls outside the expected profile. It is a category of sensory defect less severe than a “fault,” which would make the coffee unpalatable. The term is standardized in professional cupping protocols, such as those from the Specialty Coffee Association (SCA), to describe aromatic off-flavors that are perceptible but not overpowering.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$taint$glossary$, $glossary$https://coffee-dictionary.com/taint/$glossary$),
  ($glossary$Takeya$glossary$, $glossary$Takeya, a Japanese brand renowned for its cold brew coffee makers, focuses on its signature airtight pitcher featuring a fine-mesh infuser for steeping coarsely ground coffee in cold water. Designed for home use, the pitcher’s BPA-free Tritan construction and leak-proof seal streamline the process of creating smooth , low-acid cold brew over 12 to 24 hours.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee Maker$rel$]::text[], $glossary$takeya$glossary$, $glossary$https://coffee-dictionary.com/takeya/$glossary$),
  ($glossary$Tassimo$glossary$, $glossary$The Tassimo Hot Beverage System is a consumer coffee machine that prepares one-cup servings of espresso, regular coffee, tea, hot chocolate , and various other coffee drinks, notably those including milk such as latte or cappuccino . It was first introduced in France in 2004 and is now also available in Andorra, Austria, Canada, Czech Republic, Greece, Germany, Norway, Spain, Sweden, Switzerland, Russia, Poland, Portugal, the United Kingdom and the United States.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$single serve coffee maker$rel$]::text[], $glossary$tassimo$glossary$, $glossary$https://coffee-dictionary.com/tassimo/$glossary$),
  ($glossary$Taste$glossary$, $glossary$Taste, gustatory perception, or gustation is one of the five traditional senses. Taste is the sensation produced when a substance in the mouth reacts chemically with receptors of taste buds. Taste, along with smell and trigeminal nerve stimulation (which also handles touch for texture, also pain, and temperature), determines flavors, the sensory impressions of food or other substances.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$taste$glossary$, $glossary$https://coffee-dictionary.com/taste/$glossary$),
  ($glossary$Technivorm$glossary$, $glossary$Technivorm is a Dutch coffeemaker manufacturer. Technivorm manufactures the Moccamaster, one of the few coffee makers approved by the SCAA . They also manufacture coffee grinders , but they are most known for their flagship product the Moccamaster.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$technivorm$glossary$, $glossary$https://coffee-dictionary.com/technivorm/$glossary$),
  ($glossary$Temperature Surfing$glossary$, $glossary$Temperature surfing is a manual technique used to stabilize brew temperature on home espresso machines with cycling thermostats. This method involves timing extraction to coincide with a specific phase in the heating cycle, addressing temperature fluctuations common in lower-cost machines like the Rancilio Silvia. Precise temperature control is critical for even extraction and balanced flavor.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$temperature-surfing$glossary$, $glossary$https://coffee-dictionary.com/temperature-surfing/$glossary$),
  ($glossary$Temperature control$glossary$, $glossary$Temperature control is a process in which change of temperature of a space (and objects collectively there within) is measured or otherwise detected, and the passage of heat energy into or out of the space is adjusted to achieve a desired average temperature.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$temperature-control$glossary$, $glossary$https://coffee-dictionary.com/temperature-control/$glossary$),
  ($glossary$Terroir$glossary$, $glossary$Terroir refers to the environmental factors (altitude, soil, climate, rainfall) of a coffee growing region that impart distinctive flavor characteristics to the beans.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$terroir$glossary$, $glossary$https://coffee-dictionary.com/terroir/$glossary$),
  ($glossary$Thermal shock$glossary$, $glossary$Glassware in coffee brewing equipment is exposed to thermal shock when hot water, or coffee is poured into glass beakers, carafes, or other recipients. In order to solve the problem with glass cracking, manufacturers use borosilicate glass , which is resistant to thermal shocks.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$thermal-shock$glossary$, $glossary$https://coffee-dictionary.com/thermal-shock/$glossary$),
  ($glossary$Thermoblock$glossary$, $glossary$A thermoblock is a compact, on-demand heating element in espresso machines, where water flows through internal channels of a heated metal block—typically aluminum or stainless steel . Unlike traditional boilers, thermoblocks heat water instantly during flow, eliminating warm-up delays and reducing energy consumption. This efficiency enables smaller, cost-effective machines, fueling their dominance in home espresso setups.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$thermoblock$glossary$, $glossary$https://coffee-dictionary.com/thermoblock/$glossary$),
  ($glossary$Thermocoil$glossary$, $glossary$A thermocoil is a heating system in espresso machines where water flows through a coiled metal tube heated by an internal electric element. Unlike traditional boilers that store and heat larger water volumes, it heats water on demand, reducing warm-up time while maintaining precise temperature control. This design enhances energy efficiency and minimizes temperature fluctuations, crucial for balanced espresso flavor.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$thermocoil$glossary$, $glossary$https://coffee-dictionary.com/thermocoil/$glossary$),
  ($glossary$Thermostat$glossary$, $glossary$The thermostat is a key component of coffee brewing equipment. It is used to ensure coffee is brewed properly, and the extraction is optimal.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$thermostat$glossary$, $glossary$https://coffee-dictionary.com/thermostat/$glossary$),
  ($glossary$Thomas$glossary$, $glossary$Thomas — see the full article.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$thomas$glossary$, $glossary$https://coffee-dictionary.com/thomas/$glossary$),
  ($glossary$Timer$glossary$, $glossary$Timers are used in coffee makers for various applications. The most common applications are: timing the brewing , starting the coffee maker, or turning it off, timing coffee grinders, as a way to measure the amount of coffee beans used, timing the extraction as a way of controlling the brewed coffee volume.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$timer$glossary$, $glossary$https://coffee-dictionary.com/timer/$glossary$),
  ($glossary$Tobacco Notes in Coffee$glossary$, $glossary$Tobacco notes in coffee describe a complex flavor profile in the brew, characterized by earthy, woody, and somewhat smoky characteristics that resemble the aroma of dried tobacco leaves. These notes typically present as dry, leathery sensations on the palate, often in darker roasts, accompanied by subtle hints of cedar or hay. The flavor shows most prominently in the coffee’s finish, leaving a lingering impression similar to the scent of a tobacco pouch after extraction .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$tobacco-notes-in-coffee$glossary$, $glossary$https://coffee-dictionary.com/tobacco-notes-in-coffee/$glossary$),
  ($glossary$Toddy$glossary$, $glossary$Toddy is a cold brew coffee concentrate created by steeping coarse coffee grounds in cold water for 12–24 hours using the Toddy® immersion system, developed by Todd Simpson in the 1960s. This slow extraction yields a smooth, low-acid concentrate with minimal bitterness , ideal for mixing with water or milk or as a base for other drinks.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Cold Brew Coffee Maker$rel$]::text[], $glossary$toddy$glossary$, $glossary$https://coffee-dictionary.com/toddy/$glossary$),
  ($glossary$Total dissolved solids$glossary$, $glossary$Total Dissolved Solids (often abbreviated TDS) is a measure of the combined content of all inorganic and organic substances contained in a liquid in: molecular, ionized or micro-granular suspended form. Generally the operational definition is that the solids must be small enough to survive filtration through a sieve the size of two micrometer. Total dissolved solids are normally discussed only for freshwater systems, as salinity comprises some of the ions constituting the definition of TDS.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$Coffee extraction$rel$]::text[], $glossary$total-dissolved-solids$glossary$, $glossary$https://coffee-dictionary.com/total-dissolved-solids/$glossary$),
  ($glossary$Triple Espresso Shot$glossary$, $glossary$Triple, in the context of espresso brewing , refers to a triple shot of espresso, pulled from approximately 21 grams of coffee grounds. The triple is pulled using special filter baskets that can hold the necessary 21 grams of coffee. Triplo, as is also called with the Italian name, is not just simply a time and volume adjustment variant of the solo. The triple shot needs to be pulled in about the same time as a single. For this, the grind size needs to be adjusted accordingly.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[$rel$Espresso$rel$]::text[], $glossary$triple$glossary$, $glossary$https://coffee-dictionary.com/triple/$glossary$),
  ($glossary$Turkish coffee$glossary$, $glossary$Turkish coffee is an unfiltered brewing method where very finely ground coffee is simmered in water in a small pot called a cezve, producing a thick, strong, and aromatic beverage.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$]::text[], ARRAY[$rel$Cezve$rel$, $rel$Coffee Brewing Methods$rel$]::text[], $glossary$turkish-coffee$glossary$, $glossary$https://coffee-dictionary.com/turkish-coffee/$glossary$),
  ($glossary$United States$glossary$, $glossary$United States of America Flag of the United States Great Seal of the United States Motto: “ In God we trust ” (official)” E pluribus unum ” (traditional)”Out of many, one” Anthem: “The Star-Spangled Banner”File:Star Spangled Banner instrumental. ogg Location of the United States CapitalWashington, D.C.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$united-states$glossary$, $glossary$https://coffee-dictionary.com/united-states/$glossary$),
  ($glossary$Valve$glossary$, $glossary$In the coffee maker industry there are many devices that are equipped with a valve. The use of a valve is different though from a coffee brewing method to another. Immersion coffee makers such as coffee drippers, use a valve to control the steeping time . A simple valve is often found on automatic drip coffee machines as a way to temporarily stop the dripping for pouring a cup.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$valve$glossary$, $glossary$https://coffee-dictionary.com/valve/$glossary$),
  ($glossary$Vibration$glossary$, $glossary$Vibration refers to a mechanical phenomenon involving oscillations about an equilibrium point. The motion is calibrated by frequency and amplitude to match specific bean size profiles, enabling processes such as specific gravity separation and density-based bean separation.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$vibration$glossary$, $glossary$https://coffee-dictionary.com/vibration/$glossary$),
  ($glossary$Vienna$glossary$, $glossary$A Vienna roast is a medium-dark roast level, darker than an American roast but lighter than Full City or French roast.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$vienna$glossary$, $glossary$https://coffee-dictionary.com/vienna/$glossary$),
  ($glossary$Vietnamese iced coffee$glossary$, $glossary$Vietnamese iced coffee (cà phê đá) is a distinctive cold coffee beverage characterized by its bold flavor profile and layered presentation. This drink typically consists of strong, dark-roasted coffee—traditionally made with robusta beans —combined with sweetened condensed milk and poured over ice. Visually, Vietnamese iced coffee presents as a striking two-toned beverage when unmixed, with the thick white condensed milk layer beneath the dark coffee. Once stirred, it transforms into a caramel-colored drink.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$vietnamese-iced-coffee$glossary$, $glossary$https://coffee-dictionary.com/vietnamese-iced-coffee/$glossary$),
  ($glossary$Volatility (chemistry)$glossary$, $glossary$In chemistry and physics, volatility is the tendency of a substance to vaporize. Volatility is directly related to a substance’s vapor pressure. At a given temperature, a substance with higher vapor pressure vaporizes more readily than a substance with a lower vapor pressure.$glossary$, $glossary$Coffee Science$glossary$, ARRAY[$cat$Coffee Science$cat$]::text[], ARRAY[]::text[], $glossary$volatility-chemistry$glossary$, $glossary$https://coffee-dictionary.com/volatility-chemistry/$glossary$),
  ($glossary$Water tank$glossary$, $glossary$Many coffee makers rely on a water tank, or reservoir to supply the machine during brewing. The water tank solution is convenient, makes it possible to move the equipment, and it doesn’t require an expensive installation.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$water-tank$glossary$, $glossary$https://coffee-dictionary.com/water-tank/$glossary$),
  ($glossary$Wiener Melange$glossary$, $glossary$Wiener Melange (pronounced VEE-ner meh-LAHNJ, from German for “ Viennese blend”) refers to a traditional Austrian coffee beverage . It is a gentler, creamier variation of a cappuccino , distinguished by its use of milder coffee and a balanced ratio of coffee to milk . The drink consists of a shot of espresso or lightly brewed coffee, an equal amount of steamed milk, and is topped with a light milk foam .$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$]::text[], ARRAY[]::text[], $glossary$wiener-melange$glossary$, $glossary$https://coffee-dictionary.com/wiener-melange/$glossary$),
  ($glossary$Wigomat$glossary$, $glossary$Developed in 1954 by German inventor Gottlob Widmann, the Wigomat revolutionized home brewing as the first fully automatic drip coffee maker. Its design featured an electric heating element, paper filter, and automated drip mechanism, replacing manual pour-over methods while ensuring consistent temperature and extraction for balanced flavor.$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$wigomat$glossary$, $glossary$https://coffee-dictionary.com/wigomat/$glossary$),
  ($glossary$Winey Coffee$glossary$, $glossary$Winey Coffee refers to coffee with distinct wine-like characteristics in its flavor profile. This descriptor indicates a cup with bright acidity , fruity notes , and a complex, sometimes fermented quality that resembles wine . The sensory experience includes berry-like flavors (blackberry, blueberry), red fruits (cherry, currant), and occasionally dark grape notes . This profile commonly appears in coffees processed using natural or honey methods, where controlled fermentation develops these distinctive attributes .$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$winey-coffee$glossary$, $glossary$https://coffee-dictionary.com/winey-coffee/$glossary$),
  ($glossary$Woody Coffee$glossary$, $glossary$Woody Coffee refers to a flavor and aroma characteristic in coffee that is reminiscent of dry wood, oak barrels, or tree bark. This descriptor is complex and can range from a valued note in some premium coffees to an undesirable defect. The distinction depends on whether the woody note is a fresh, intrinsic part of the flavor profile or a stale one resulting from improper storage or excessive aging.$glossary$, $glossary$Flavors & Cupping$glossary$, ARRAY[$cat$Flavors & Cupping$cat$]::text[], ARRAY[]::text[], $glossary$woody-coffee$glossary$, $glossary$https://coffee-dictionary.com/woody-coffee/$glossary$),
  ($glossary$brew group$glossary$, $glossary$Side view of a Slayer V3 boiler for a multi-group machine.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Espresso Machine$rel$]::text[], $glossary$brew-group$glossary$, $glossary$https://coffee-dictionary.com/brew-group/$glossary$),
  ($glossary$coffee$glossary$, $glossary$The word “coffee” traces its roots to the Arabic “qahwah,” which originally referred to wine but later became associated with the beverage made from coffee beans . This term evolved as it traveled through trade routes, becoming “kahve” in Turkish and eventually “coffee” in English by the 16th century.$glossary$, $glossary$Coffee Culture$glossary$, ARRAY[$cat$Coffee Culture$cat$, $cat$Coffee Origins$cat$]::text[], ARRAY[]::text[], $glossary$coffee$glossary$, $glossary$https://coffee-dictionary.com/coffee/$glossary$),
  ($glossary$coffee beans$glossary$, $glossary$A coffee bean refers to the dried and roasted seed of a tropical plant belonging to the genus * Coffea * . Botanically, it is not a true bean but the pit found inside the coffee cherry fruit. The plural form is “coffee beans” .$glossary$, $glossary$General Terms$glossary$, ARRAY[$cat$General Terms$cat$]::text[], ARRAY[$rel$Espresso Beans$rel$, $rel$Espresso Blend$rel$, $rel$Peaberry Coffee$rel$, $rel$Single Origin$rel$]::text[], $glossary$coffee-beans$glossary$, $glossary$https://coffee-dictionary.com/coffee-beans/$glossary$),
  ($glossary$coffee grind size$glossary$, $glossary$Grind size is an important factor in coffee preparation, and it refers to the how fine or coarse the coffee bean is ground in order to prepare the coffee beverage.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Coffee grinding$rel$, $rel$Espresso$rel$]::text[], $glossary$grind-size$glossary$, $glossary$https://coffee-dictionary.com/grind-size/$glossary$),
  ($glossary$coffee grinder$glossary$, $glossary$A coffee grinder is a device for crushing coffee beans into fine grains or a powder. There are several types of coffee grinders, the most popular ones are burr grinders and blade grinders.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Burr Grinder$rel$, $rel$Coffee grinding$rel$]::text[], $glossary$coffee-grinder$glossary$, $glossary$https://coffee-dictionary.com/coffee-grinder/$glossary$),
  ($glossary$coffee roasters$glossary$, $glossary$A coffee roasting company, or a coffee roaster for short, is a company that buys green coffee beans and roasts them. A coffee roaster sells various single origin or blends of coffee beans . There are various types of roasteries, depending on the niche and the company size. The third wave of coffee brought to the consumer’s attention micro roasters and artisan roasters, who cater to specialty coffee consumers and roast in small batches.$glossary$, $glossary$Coffee Brands$glossary$, ARRAY[$cat$Coffee Brands$cat$, $cat$General Terms$cat$, $cat$Coffee Roasting$cat$]::text[], ARRAY[]::text[], $glossary$coffee-roasters$glossary$, $glossary$https://coffee-dictionary.com/coffee-roasters/$glossary$),
  ($glossary$coffee roasting$glossary$, $glossary$Roasting, in general, is a cooking method that uses dry heat, whether an open flame, oven, or other heat source. Roasting can enhance flavor through caramelization and Maillard browning on the surface of the food.$glossary$, $glossary$Coffee Roasting$glossary$, ARRAY[$cat$Coffee Roasting$cat$, $cat$General Terms$cat$]::text[], ARRAY[$rel$After Dinner Roast$rel$, $rel$American Roast$rel$, $rel$Dark Roast$rel$, $rel$Degassing$rel$, $rel$Light Roast$rel$, $rel$Medium Roast$rel$, $rel$Medium-dark Roast$rel$]::text[], $glossary$roasting$glossary$, $glossary$https://coffee-dictionary.com/roasting/$glossary$),
  ($glossary$coffee substitute$glossary$, $glossary$A coffee substitute is a substance that is consumed instead of coffee . It will normally have coffee like properties such as taste and appearance. Coffee drinkers will often drink coffee substitutes if they are trying to avoid coffee but want to have the coffee experience.$glossary$, $glossary$Coffee Drinks$glossary$, ARRAY[$cat$Coffee Drinks$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$coffee-substitute$glossary$, $glossary$https://coffee-dictionary.com/coffee-substitute/$glossary$),
  ($glossary$crema$glossary$, $glossary$Crema is the golden-brown, foam-like layer that forms on top of a freshly pulled espresso shot, composed of emulsified coffee oils and CO2 bubbles.$glossary$, $glossary$Brewing Methods$glossary$, ARRAY[$cat$Brewing Methods$cat$, $cat$Coffee Science$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$crema$glossary$, $glossary$https://coffee-dictionary.com/crema/$glossary$),
  ($glossary$dosing$glossary$, $glossary$Coffee brewing requires following strict recipes. This includes brewing temperature, coffee grind size , brewing time and the coffee dose.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$, $cat$General Terms$cat$]::text[], ARRAY[]::text[], $glossary$dosing$glossary$, $glossary$https://coffee-dictionary.com/dosing/$glossary$),
  ($glossary$filter basket$glossary$, $glossary$Filter Basket: Definition and Core Function A filter basket is a perforated metal component that fits inside an espresso machine ‘s portafilter, designed to hold ground coffee during the brewing process . It has tiny holes through which pressurized hot water passes, extracting flavor compounds from the coffee grounds. Filter baskets come in various sizes, with 18g capacity being recommended for consistent home brewing . While 8g baskets exist for single shots, they present extraction challenges .$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Espresso Machine$rel$]::text[], $glossary$filter-basket$glossary$, $glossary$https://coffee-dictionary.com/filter-basket/$glossary$),
  ($glossary$portafilter$glossary$, $glossary$A portafilter is the handle-equipped filter basket that holds ground coffee in an espresso machine, locking into the group head for pressurized extraction.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Espresso Machine$rel$]::text[], $glossary$portafilter$glossary$, $glossary$https://coffee-dictionary.com/portafilter/$glossary$),
  ($glossary$single serve coffee maker$glossary$, $glossary$A single serve coffee maker is a coffeemaker that can be used to brew a single cup of coffee. The concept of single serve is usually related to automatic drip coffee brewers, since the classic automatic drip coffee machine cannot make small quantities of coffee. Although espresso machines brew a single serve, they are not included in the category. The same with manual coffee brewers.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[$rel$Dolce Gusto$rel$, $rel$Keurig$rel$, $rel$Nespresso$rel$, $rel$Senseo$rel$, $rel$Tassimo$rel$]::text[], $glossary$single-serve-coffee-maker$glossary$, $glossary$https://coffee-dictionary.com/single-serve-coffee-maker/$glossary$),
  ($glossary$tamper$glossary$, $glossary$A tamper is a flat-bottomed tool used to compress ground coffee evenly in an espresso portafilter basket, creating a uniform puck for consistent extraction.$glossary$, $glossary$Coffee Equipment$glossary$, ARRAY[$cat$Coffee Equipment$cat$]::text[], ARRAY[]::text[], $glossary$tamper$glossary$, $glossary$https://coffee-dictionary.com/tamper/$glossary$),
  ($glossary$Bolivia$glossary$, $glossary$Bolivia is a coffee-producing country in west-central South America , a small but distinctive origin whose farms sit among the highest coffee-growing elevations on earth. Its coffee industry is modest by volume yet increasingly valued by specialty buyers for clean , sweet, floral lots that are hard to find elsewhere.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Terroir$rel$, $rel$Altura Coffee$rel$, $rel$Brightness in Coffee$rel$, $rel$Floral Notes in Coffee$rel$]::text[], $glossary$bolivia$glossary$, $glossary$https://coffee-dictionary.com/bolivia/$glossary$),
  ($glossary$Brazil$glossary$, $glossary$Brazil is the world’s largest coffee-producing country, supplying roughly a third of all coffee grown on earth, and a defining coffee origin in its own right. A South American giant whose output dwarfs every other origin, Brazil anchors the global market and provides the base of countless espresso blends thanks to its smooth, low-acid, chocolatey profile.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Robusta coffee$rel$, $rel$Espresso$rel$, $rel$Chocolate Coffee Notes$rel$, $rel$Nutty Flavor in Coffee$rel$]::text[], $glossary$brazil$glossary$, $glossary$https://coffee-dictionary.com/brazil/$glossary$),
  ($glossary$Burundi$glossary$, $glossary$Burundi is a small, landlocked coffee-producing country in East Africa’s Great Lakes region and a rising specialty origin. Despite its size, it has earned a strong specialty reputation for bright, sweet, berry-driven coffees grown by hundreds of thousands of smallholder families at high elevations.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Brightness in Coffee$rel$, $rel$Fruity Notes in Coffee$rel$, $rel$Terroir$rel$]::text[], $glossary$burundi$glossary$, $glossary$https://coffee-dictionary.com/burundi/$glossary$),
  ($glossary$China$glossary$, $glossary$China is a rising coffee-producing country, with nearly all of its Arabica grown in the southern province of Yunnan. A relatively new player on the global origin map, China has expanded planting rapidly and is increasingly exporting clean , mild, approachable coffees.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Coffee production$rel$, $rel$Nutty Flavor in Coffee$rel$]::text[], $glossary$china$glossary$, $glossary$https://coffee-dictionary.com/china/$glossary$),
  ($glossary$Colombia$glossary$, $glossary$Colombia is one of the world’s leading coffee-producing countries and the most famous Arabica origin in the Americas. Its washed, high-grown coffees are the benchmark for balance, prized worldwide for a smooth, caramel-sweet cup with a bright, clean finish.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Terroir$rel$, $rel$Balance in Coffee$rel$, $rel$Caramelly$rel$, $rel$Coffee Acidity$rel$]::text[], $glossary$colombia$glossary$, $glossary$https://coffee-dictionary.com/colombia/$glossary$),
  ($glossary$Costa Rica$glossary$, $glossary$Costa Rica is a Central American coffee-producing country with an outsized reputation for quality and one of the defining origins of the specialty era. Though small in volume, it was the first country to ban Robusta by law and pioneered the honey process, producing clean, bright, sweet coffees that helped define specialty coffee.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Brightness in Coffee$rel$, $rel$Citrus in Coffee$rel$]::text[], $glossary$costa-rica$glossary$, $glossary$https://coffee-dictionary.com/costa-rica/$glossary$),
  ($glossary$Cuba$glossary$, $glossary$Cuba is a Caribbean coffee-producing country and coffee origin with a long growing tradition centred on the Sierra Maestra mountains. Its small Arabica harvest is known for a smooth, mild, low-acid cup, and its coffee culture produced the intensely sweet cafecito served across the island.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Cuban espresso$rel$, $rel$Mellow Coffee Flavor$rel$]::text[], $glossary$cuba$glossary$, $glossary$https://coffee-dictionary.com/cuba/$glossary$),
  ($glossary$Dominican Republic$glossary$, $glossary$The Dominican Republic is a Caribbean coffee-producing country and coffee origin on the island of Hispaniola, with most of its Arabica grown in the highlands of the Barahona region. Its coffees are mild, sweet, and balanced, with a smooth body typical of well-made island coffee.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Mellow Coffee Flavor$rel$, $rel$Balance in Coffee$rel$]::text[], $glossary$dominican-republic$glossary$, $glossary$https://coffee-dictionary.com/dominican-republic/$glossary$),
  ($glossary$DR Congo$glossary$, $glossary$The Democratic Republic of the Congo is a large coffee-producing country in Central Africa and a resurgent coffee origin, with its best Arabica grown on the shores of Lake Kivu. Its high-grown coffees are full-bodied and deeply fruity, and its speciality sector has rebuilt after decades of conflict.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Earthy Coffee$rel$, $rel$Winey Coffee$rel$, $rel$Coffee Body$rel$]::text[], $glossary$dr-congo$glossary$, $glossary$https://coffee-dictionary.com/dr-congo/$glossary$),
  ($glossary$Ecuador$glossary$, $glossary$Ecuador is a coffee-producing country on South America’s Pacific coast and a small but fast-rising coffee origin, stretching from Andean highlands down to the Galápagos. Its high-grown Arabica from the southern province of Loja is increasingly celebrated for a sweet, floral, complex cup.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Floral Notes in Coffee$rel$, $rel$Terroir$rel$, $rel$Altura Coffee$rel$]::text[], $glossary$ecuador$glossary$, $glossary$https://coffee-dictionary.com/ecuador/$glossary$),
  ($glossary$El Salvador$glossary$, $glossary$El Salvador is a small Central American coffee-producing country and a respected coffee origin with a long and proud growing heritage. Its highland farms produce sweet, honeyed, chocolate-toned coffees, and the country is famous for the Pacamara variety it helped bring to the world stage.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Chocolate Coffee Notes$rel$]::text[], $glossary$el-salvador$glossary$, $glossary$https://coffee-dictionary.com/el-salvador/$glossary$),
  ($glossary$Guatemala$glossary$, $glossary$Guatemala is a Central American coffee-producing country renowned for some of the region’s most distinctive, full-bodied coffees, and one of its premier coffee origins. Its volcanic highlands — above all the Antigua valley — yield cups with rich chocolate, gentle smoke, and a bright, complex finish.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Chocolate Coffee Notes$rel$, $rel$Coffee Body$rel$, $rel$Coffee Acidity$rel$, $rel$Terroir$rel$]::text[], $glossary$guatemala$glossary$, $glossary$https://coffee-dictionary.com/guatemala/$glossary$),
  ($glossary$Honduras$glossary$, $glossary$Honduras is the largest coffee-producing country in Central America by volume and a rising force in specialty coffee . Its highland farms turn out sweet, balanced, nutty -and- caramel coffees that have quietly become a mainstay of blends and single origins alike.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Caramelly$rel$, $rel$Nutty Flavor in Coffee$rel$, $rel$Balance in Coffee$rel$]::text[], $glossary$honduras$glossary$, $glossary$https://coffee-dictionary.com/honduras/$glossary$),
  ($glossary$India$glossary$, $glossary$India is a major coffee-producing country in South Asia and the origin of the famous Monsooned Malabar process. Its southern plantations grow both Arabica and Robusta , yielding smooth , low-acid coffees that underpin the country’s beloved filter-coffee tradition.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Indian Filter Coffee$rel$, $rel$Robusta coffee$rel$, $rel$Coffea Arabica$rel$, $rel$Spicy Notes in Coffee$rel$, $rel$Earthy Coffee$rel$]::text[], $glossary$india$glossary$, $glossary$https://coffee-dictionary.com/india/$glossary$),
  ($glossary$Indonesia$glossary$, $glossary$Indonesia is one of the world’s largest coffee-producing countries and the source of some of its most distinctive beans, a coffee origin defined by its island terroir. Its coffees — from Sumatra, Java, and Sulawesi — are famous for a heavy, earthy, low-acid cup shaped by the unique wet-hulled process.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Mocha Java$rel$, $rel$Robusta coffee$rel$, $rel$Coffea Arabica$rel$, $rel$Earthy Coffee$rel$, $rel$Coffee Body$rel$, $rel$Kopi Tubruk$rel$]::text[], $glossary$indonesia$glossary$, $glossary$https://coffee-dictionary.com/indonesia/$glossary$),
  ($glossary$Jamaica$glossary$, $glossary$Jamaica is a Caribbean coffee-producing country best known for its Blue Mountain coffee, one of the most famous and expensive coffees in the world, and a coffee origin synonymous with luxury. Grown in a strictly defined highland zone, it is prized for a mild, sweet, impeccably balanced cup.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Mellow Coffee Flavor$rel$, $rel$Balance in Coffee$rel$]::text[], $glossary$jamaica$glossary$, $glossary$https://coffee-dictionary.com/jamaica/$glossary$),
  ($glossary$Kenya$glossary$, $glossary$Kenya is an East African coffee-producing country whose coffees are among the most distinctive and sought-after in the world, and one of the great benchmark origins. Known for intense blackcurrant and berry notes and a wine-like acidity, Kenyan coffee sets the standard for bright, complex African flavour.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$AA Coffee Grading$rel$, $rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Brightness in Coffee$rel$, $rel$Winey Coffee$rel$, $rel$Coffee Acidity$rel$]::text[], $glossary$kenya$glossary$, $glossary$https://coffee-dictionary.com/kenya/$glossary$),
  ($glossary$Laos$glossary$, $glossary$Laos is a landlocked coffee-producing country in Southeast Asia and an emerging coffee origin, with most of its crop grown on the volcanic Bolaven Plateau in the south. Its Arabica is sweet and mild, and its coffee sector has grown steadily as a source of rural income.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Mellow Coffee Flavor$rel$, $rel$Nutty Flavor in Coffee$rel$]::text[], $glossary$laos$glossary$, $glossary$https://coffee-dictionary.com/laos/$glossary$),
  ($glossary$Malawi$glossary$, $glossary$Malawi is a small East African coffee-producing country and an emerging coffee origin whose highland Arabica is a rising specialty name. Grown mainly in the northern Mzuzu region, Malawian coffee is sweet, floral, and bright, with a clean finish that belies the country’s small output.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Brightness in Coffee$rel$, $rel$Floral Notes in Coffee$rel$]::text[], $glossary$malawi$glossary$, $glossary$https://coffee-dictionary.com/malawi/$glossary$),
  ($glossary$Mexico$glossary$, $glossary$Mexico is one of the world’s larger coffee-producing countries, with a long growing tradition across its southern states, and a longstanding coffee origin. Its highland Arabica is mild and smooth, with nutty, chocolate notes, and much of it is shade-grown and organic.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Nutty Flavor in Coffee$rel$, $rel$Chocolate Coffee Notes$rel$, $rel$Mellow Coffee Flavor$rel$]::text[], $glossary$mexico$glossary$, $glossary$https://coffee-dictionary.com/mexico/$glossary$),
  ($glossary$Myanmar$glossary$, $glossary$Myanmar is an emerging coffee-producing country in Southeast Asia and a young coffee origin, with its best Arabica grown in the cool highlands of Shan State. Its coffees are sweet and fruity, and its specialty sector has grown rapidly as a source of rural development.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Fruity Notes in Coffee$rel$, $rel$Altura Coffee$rel$]::text[], $glossary$myanmar$glossary$, $glossary$https://coffee-dictionary.com/myanmar/$glossary$),
  ($glossary$Nicaragua$glossary$, $glossary$Nicaragua is a Central American coffee-producing country and a dependable coffee origin, whose highland coffees are sweet, balanced, and chocolatey. Grown across the northern highlands around Jinotega and Matagalpa, Nicaraguan coffee is a crowd-pleasing favourite.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Chocolate Coffee Notes$rel$, $rel$Nutty Flavor in Coffee$rel$, $rel$Balance in Coffee$rel$]::text[], $glossary$nicaragua$glossary$, $glossary$https://coffee-dictionary.com/nicaragua/$glossary$),
  ($glossary$Panama$glossary$, $glossary$Panama is a small coffee-producing country that has become legendary in specialty coffee as the home of the Geisha variety, and one of the world’s most coveted coffee origins. Grown on the volcanic slopes of Boquete and Volcán, Panamanian Geisha commands record prices for its astonishing floral, tea-like cup.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Floral Notes in Coffee$rel$, $rel$Citrus in Coffee$rel$, $rel$Terroir$rel$, $rel$Altura Coffee$rel$]::text[], $glossary$panama$glossary$, $glossary$https://coffee-dictionary.com/panama/$glossary$),
  ($glossary$Papua New Guinea$glossary$, $glossary$Papua New Guinea is a coffee-producing country in the western Pacific and a distinctive coffee origin whose highland Arabica grows in remote, rugged terrain. Its coffees are sweet and full-bodied, with a syrupy texture and a fruity, gently earthy character.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Coffee Body$rel$, $rel$Fruity Notes in Coffee$rel$]::text[], $glossary$papua-new-guinea$glossary$, $glossary$https://coffee-dictionary.com/papua-new-guinea/$glossary$),
  ($glossary$Peru$glossary$, $glossary$Peru is a leading coffee-producing country on the eastern slopes of the Andes and a major coffee origin known for high-grown, organic Arabica. Its coffees are mild and sweet, with nutty, chocolate notes and a clean finish, grown largely by smallholder farmers.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Altura Coffee$rel$, $rel$Nutty Flavor in Coffee$rel$, $rel$Chocolate Coffee Notes$rel$]::text[], $glossary$peru$glossary$, $glossary$https://coffee-dictionary.com/peru/$glossary$),
  ($glossary$Puerto Rico$glossary$, $glossary$Puerto Rico is a Caribbean coffee-producing island and coffee origin with a heritage dating back centuries. Its highland Arabica is smooth, sweet, and balanced, and the island’s coffee tradition is celebrated in its daily café culture.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Mellow Coffee Flavor$rel$, $rel$Balance in Coffee$rel$]::text[], $glossary$puerto-rico$glossary$, $glossary$https://coffee-dictionary.com/puerto-rico/$glossary$),
  ($glossary$Rwanda$glossary$, $glossary$Rwanda, the “land of a thousand hills,” is a small East African coffee-producing country and a model specialty origin, whose Bourbon coffees are bright, floral, and sweet. Its sector has become a benchmark of quality-driven, smallholder-led production.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Brightness in Coffee$rel$, $rel$Floral Notes in Coffee$rel$, $rel$Citrus in Coffee$rel$]::text[], $glossary$rwanda$glossary$, $glossary$https://coffee-dictionary.com/rwanda/$glossary$),
  ($glossary$Tanzania$glossary$, $glossary$Tanzania is an East African coffee-producing country whose coffees grow on the slopes of Mount Kilimanjaro and the southern highlands. Known for bright , fruity , sweet cups — and for its prized peaberry lots — Tanzania is a respected origin in its own right.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Arusha Coffee$rel$, $rel$Peaberry Coffee$rel$, $rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Fruity Notes in Coffee$rel$]::text[], $glossary$tanzania$glossary$, $glossary$https://coffee-dictionary.com/tanzania/$glossary$),
  ($glossary$Thailand$glossary$, $glossary$Thailand is a coffee-producing country in Southeast Asia and a growing coffee origin, with most of its Arabica grown in the northern highlands around Chiang Mai and Chiang Rai. Its coffees are mild, sweet, and increasingly refined, alongside a strong domestic coffee-drinking culture.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Oliang$rel$, $rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Mellow Coffee Flavor$rel$]::text[], $glossary$thailand$glossary$, $glossary$https://coffee-dictionary.com/thailand/$glossary$),
  ($glossary$Uganda$glossary$, $glossary$Uganda is a major coffee-producing country in East Africa and one of the world’s leading Robusta growers, and a substantial coffee origin. Its highland Arabica from Mount Elgon and the Rwenzori range is full-bodied and winey, while its Robusta anchors blends worldwide.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Robusta coffee$rel$, $rel$Coffea Arabica$rel$, $rel$Winey Coffee$rel$, $rel$Coffee Body$rel$, $rel$Coffee production$rel$]::text[], $glossary$uganda$glossary$, $glossary$https://coffee-dictionary.com/uganda/$glossary$),
  ($glossary$Vietnam$glossary$, $glossary$Vietnam is the world’s second-largest coffee-producing country and its leading Robusta grower, and a powerhouse coffee origin. Its coffee, centred on the Central Highlands, is bold, earthy, and heavy-bodied, powering espresso blends, instant coffee, and the country’s famous sweetened iced coffee.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Vietnamese iced coffee$rel$, $rel$Robusta coffee$rel$, $rel$Coffea Arabica$rel$, $rel$Coffee Body$rel$]::text[], $glossary$vietnam$glossary$, $glossary$https://coffee-dictionary.com/vietnam/$glossary$),
  ($glossary$Yemen$glossary$, $glossary$Yemen is a historic coffee-producing country and the birthplace of the world coffee trade, the source of the legendary Mocha and one of the oldest coffee origins on earth. Its highland Arabica, dried naturally on sun-baked terraces, is prized for a wild, winey, spiced cup unlike any other origin.$glossary$, $glossary$Coffee Origins$glossary$, ARRAY[$cat$Coffee Origins$cat$]::text[], ARRAY[$rel$Mocha$rel$, $rel$Arabian Mocha Coffee$rel$, $rel$Mocha Java$rel$, $rel$Single Origin$rel$, $rel$Coffea Arabica$rel$, $rel$Winey Coffee$rel$, $rel$Spicy Notes in Coffee$rel$]::text[], $glossary$yemen$glossary$, $glossary$https://coffee-dictionary.com/yemen/$glossary$)
