-- T8/T10: full glossary seed — 409 terms, normalized by
-- ~/coffee-dictionary-import/scripts/normalize.py. Definition = the lead
-- (first paragraph) of each article; full content lives on the site and is
-- linked via source_url. `categories` = full (consolidated) WP taxonomy list,
-- `category` = primary label. Idempotent: unique term index + upsert.

create unique index if not exists glossary_terms_term_key
  on public.glossary_terms (term);

on conflict (term) do update set
  definition = excluded.definition,
  category = excluded.category,
  categories = excluded.categories,
  related_terms = excluded.related_terms,
  slug = excluded.slug,
  source_url = excluded.source_url;
